def check_backup_contents__1aa0aa31(result, expected, **options):
    """Check if backup directory contains expected files.

    Args:
        result: List of filenames from getter
        expected: Dict with 'min_files' count
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, list) or not isinstance(expected, dict):
        return 0.0
    min_files = expected.get('min_files', 0)
    if len(result) >= min_files:
        return 1.0
    return 0.0

def check_pkill_usage__9831bd277f4e7279a633502cadeec21e(result, expected, **options):
    """Check if pkill command was used successfully.

    Args:
        result: Output string from the command
        expected: Dict containing 'include' and 'exclude' patterns
        **options: Additional options

    Returns:
        float: 1.0 if all include patterns are found and all exclude patterns are not found, 0.0 otherwise
    """
    if result is None:
        return 0.0
    include = expected.get('include', [])
    exclude = expected.get('exclude', [])
    logger.info(f'Checking result: {result}')
    logger.info(f'Include patterns: {include}')
    logger.info(f'Exclude patterns: {exclude}')
    for pattern in include:
        if pattern not in result:
            logger.info(f'Missing required pattern: {pattern}')
            return 0.0
    for pattern in exclude:
        if pattern in result:
            logger.info(f'Found excluded pattern: {pattern}')
            return 0.0
    return 1.0

def check_brightness_decrease__4c7b26ad7d6a1a697cf659bf75175126(result_state, expected, **options):
    """
    Check if brightness decreased by at least 30% from original.

    Calculates the decrease in brightness units and verifies it meets
    the percentage requirement specified in the instruction.

    Args:
        result_state: Current brightness value from getter (float)
        expected: Dict with 'original_brightness' key (float)
        **options: Additional options (unused)

    Returns:
        float: 1.0 if brightness reduced by at least 30%, 0.0 otherwise
    """
    if result_state is None:
        return 0.0
    original_brightness = expected.get('original_brightness')
    if original_brightness is None:
        return 0.0
    brightness_decrease = original_brightness - result_state
    required_decrease = original_brightness * 0.3
    if brightness_decrease >= required_decrease:
        return 1.0
    return 0.0

def check_title_exists__944d9bdb(result, expected, **options):
    """Check if the expected title was found in the spreadsheet.

    This metric verifies that a specific paper title exists in the spreadsheet.
    It does NOT verify:
    - Whether the paper was newly added during task execution
    - Publication dates or temporal constraints
    - Number of papers added

    It ONLY verifies:
    - Presence of the required title in the spreadsheet (case-insensitive match)

    Args:
        result: Dict from getter with:
            - 'found_titles': List of titles found in spreadsheet
            - 'found': Boolean indicating if any matches were found
        expected: Rules dict (when type="rule") containing:
            - 'title_required': The title that must be present
        **options: Additional options

    Returns:
        float: 1.0 if the expected title is found, 0.0 otherwise
    """
    if not isinstance(expected, dict):
        return 0.0
    title_required = expected.get('title_required', '')
    if not title_required:
        return 0.0
    if not isinstance(result, dict) or not result.get('found', False):
        return 0.0
    found_titles = result.get('found_titles', [])
    title_required_lower = title_required.lower()
    for found_title in found_titles:
        if title_required_lower in found_title.lower():
            return 1.0
    return 0.0

def check_populated_rows__46f371eb(result_state, expected_state, **options):
    """
    Check if all employee records have been properly decomposed into complete rows.
    Verifies:
    1. Total number of rows matches expected (21)
    2. All rows have complete data in all three fields (first name, last name, rank)

    Args:
        result_state: Dictionary from getter with total_rows, complete_rows, incomplete_rows
        expected_state: Dictionary with 'expected_total' and 'expected_complete' keys
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0:
               - 50% for correct total row count
               - 50% for all rows having complete data (all three fields populated)
    """
    total_rows = result_state.get('total_rows', 0)
    complete_rows = result_state.get('complete_rows', 0)
    incomplete_rows = result_state.get('incomplete_rows', 0)
    expected_total = expected_state.get('expected_total', 0)
    expected_complete = expected_state.get('expected_complete', 0)
    if expected_total == 0:
        return 0.0
    if total_rows == expected_total:
        total_score = 1.0
    elif total_rows > 0:
        total_score = min(total_rows / expected_total, 1.0)
    else:
        total_score = 0.0
    if complete_rows == expected_complete:
        complete_score = 1.0
    elif complete_rows > 0:
        complete_score = min(complete_rows / expected_complete, 1.0)
    else:
        complete_score = 0.0
    final_score = total_score * 0.5 + complete_score * 0.5
    return final_score

def check_min_max_output__b465704f1232640ce96f6f030d4bb3a1(result: str, expected: Dict, **options) -> float:
    """
    Check if text output contains expected min and max values.
    Handles various output formats flexibly.

    Args:
        result: Actual text output from file
        expected: Dict with 'min_value' and 'max_value' keys
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    expected_min = expected.get('min_value')
    expected_max = expected.get('max_value')
    if expected_min is None or expected_max is None:
        logger.warning('Missing expected min or max value')
        return 0.0
    score = 0.0
    numbers = re.findall('-?\\d+', result)
    try:
        parsed_numbers = [int(n) for n in numbers]
        lines = result.strip().split('\n')
        if len(lines) >= 2:
            try:
                first_line_nums = re.findall('-?\\d+', lines[0])
                second_line_nums = re.findall('-?\\d+', lines[1])
                if first_line_nums and second_line_nums:
                    first_num = int(first_line_nums[0])
                    second_num = int(second_line_nums[0])
                    if first_num == expected_min:
                        score += 0.5
                    if second_num == expected_max:
                        score += 0.5
                    if score > 0:
                        return score
            except (ValueError, IndexError):
                pass
        min_pattern = re.compile('\\b(?:min(?:imum)?)\\s*[:\\-=]?\\s*(\\d+)', re.IGNORECASE)
        max_pattern = re.compile('\\b(?:max(?:imum)?)\\s*[:\\-=]?\\s*(\\d+)', re.IGNORECASE)
        min_match = min_pattern.search(result)
        max_match = max_pattern.search(result)
        if min_match and max_match:
            min_value = int(min_match.group(1))
            max_value = int(max_match.group(1))
            if min_value == expected_min:
                score += 0.5
            if max_value == expected_max:
                score += 0.5
            return score
        if len(parsed_numbers) == 2:
            if parsed_numbers[0] == expected_min:
                score += 0.5
            if parsed_numbers[1] == expected_max:
                score += 0.5
            return score
        if expected_min in parsed_numbers:
            score += 0.5
        if expected_max in parsed_numbers:
            score += 0.5
        return score
    except (ValueError, IndexError) as e:
        logger.warning(f'Could not parse min/max values: {e}')
        return 0.0

def check_task_pane__be7f4bd7(accessibility_tree, expected, **options):
    """
    Check if Task Pane (Layouts panel) is visible in LibreOffice Impress.

    Args:
        accessibility_tree: XML accessibility tree from the environment
        expected: Expected rules (not used for this check)
        **options: Additional options

    Returns:
        float: 1.0 if Task Pane is visible, 0.0 otherwise
    """
    try:
        namespaces = {'st': 'uri:deskat:state.at-spi.gnome.org', 'cp': 'uri:deskat:component.at-spi.gnome.org'}
        root = ET.fromstring(accessibility_tree)
        for panel in root.iter('panel'):
            name = panel.attrib.get('name', '')
            if 'Task' in name or 'Layout' in name:
                return 1.0
        for scroll_pane in root.iter('scroll-pane'):
            name = scroll_pane.attrib.get('name', '')
            if 'Layout' in name or 'Task' in name:
                return 1.0
        return 0.0
    except Exception as e:
        logger.error(f'Error checking Task Pane: {e}')
        return 0.0

