def check_uppercase__a2b18a6b(result: List, expected: List, **opts) -> float:
    if not result or len(result) != len(expected):
        return 0.0
    m = sum((1 for i in range(len(expected)) if i < len(result) and ' '.join(result[i].split()) == ' '.join(expected[i].split())))
    return m / len(expected)

def check_top_product__d5176e3393b8d015238266eeb7e27fa3(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the summary table and top product are correct.

    Scoring:
    - 0.5 for correct summary table with all products and correct sales totals
    - 0.5 for correctly identifying the top product

    Args:
        result: Dict with 'product_sales', 'top_product', 'has_table_structure'
        expected: Dict with 'product_name' and 'product_sales' (expected sales for all products)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, dict):
        return 0.0
    score = 0.0
    expected_product = expected.get('product_name', '')
    expected_sales = expected.get('product_sales', {})
    result_sales = result.get('product_sales', {})
    if result_sales:
        all_products_present = all((product in result_sales for product in expected_sales.keys()))
        if all_products_present:
            all_sales_correct = True
            for (product, expected_total) in expected_sales.items():
                result_total = result_sales.get(product, 0)
                if abs(result_total - expected_total) > 0.01:
                    all_sales_correct = False
                    break
            if all_sales_correct:
                score += 0.5
    top_product = result.get('top_product')
    if top_product and expected_product:
        if top_product.strip().lower() == expected_product.strip().lower():
            score += 0.5
    return score

def check_recreation_title__f88125582538c20ef428c4af5979c4e3(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """
    Check if the recreation.gov page title contains expected text.

    Args:
        result: Dictionary with 'title' and 'url' keys
        expected: Expected configuration with title_contains field
        **options: Additional options

    Returns:
        float: 1.0 if title contains expected text, 0.0 otherwise
    """
    logger.info(f'[CHECK_RECREATION_TITLE] Result: {result}')
    logger.info(f'[CHECK_RECREATION_TITLE] Expected: {expected}')
    if not result or 'title' not in result:
        logger.info('[CHECK_RECREATION_TITLE] Result is empty or missing title, returning 0.0')
        return 0.0
    actual_title = result['title'].lower()
    expected_text = expected.get('title_contains', '').lower()
    if expected_text in actual_title:
        logger.info(f"[CHECK_RECREATION_TITLE] Title contains expected text: '{expected_text}' found in '{actual_title}'")
        return 1.0
    else:
        logger.info(f"[CHECK_RECREATION_TITLE] Title mismatch: expected text '{expected_text}' not found in '{actual_title}'")
        return 0.0

def check_screenshot_exists__57d2d1f6(result, expected, **options):
    """Check if a screenshot file exists with the correct extension.

    Args:
        result: dict from getter with file info
        expected: dict with 'required_extension' key
        **options: Additional options

    Returns:
        float: 1.0 if file exists with correct extension, 0.0 otherwise
    """
    if not isinstance(result, dict):
        logger.error(f'Expected dict result, got {type(result)}')
