def check_window_dimensions__da6ccce5(actual_files, expected, **options):
    """Check if window dimensions are set to target values.

    Args:
        actual_files: List of file paths from vm_file getter
        expected: Expected rules dict with target width and height
        **options: Additional options

    Returns:
        float: 1.0 if both dimensions are correct, 0.5 if one is correct, 0.0 if none correct
    """
    if not actual_files or not isinstance(actual_files, list) or len(actual_files) == 0:
        return 0.0
    file_paths = [fp for fp in actual_files if fp and isinstance(fp, str)]
    if not file_paths:
        return 0.0
    settings_file_path = None
    for file_path in file_paths:
        filename = os.path.basename(file_path)
        if file_path and filename == 'settings.py':
            settings_file_path = file_path
            break
    if not settings_file_path or not os.path.exists(settings_file_path):
        return 0.0
    try:
        with open(settings_file_path, 'r', encoding='utf-8') as f:
            file_content = f.read()
        tree = ast.parse(file_content)
        found_width = None
        found_height = None
        for node in ast.walk(tree):
            if isinstance(node, ast.Assign):
                if len(node.targets) == 1 and isinstance(node.targets[0], ast.Tuple):
                    target_tuple = node.targets[0]
                    if len(target_tuple.elts) == 2:
                        names = []
                        for elt in target_tuple.elts:
                            if isinstance(elt, ast.Name):
                                names.append(elt.id)
                        if 'WIDTH' in names and 'HEIGHT' in names:
                            width_idx = names.index('WIDTH')
                            height_idx = names.index('HEIGHT')
                            if isinstance(node.value, ast.Tuple) and len(node.value.elts) == 2:
                                if isinstance(node.value.elts[width_idx], ast.Constant):
                                    found_width = node.value.elts[width_idx].value
                                if isinstance(node.value.elts[height_idx], ast.Constant):
                                    found_height = node.value.elts[height_idx].value
                elif len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                    var_name = node.targets[0].id
                    if var_name == 'WIDTH' and isinstance(node.value, ast.Constant):
                        found_width = node.value.value
                    elif var_name == 'HEIGHT' and isinstance(node.value, ast.Constant):
                        found_height = node.value.value
        expected_width = expected.get('width', 800)
        expected_height = expected.get('height', 600)
        score = 0.0
        if found_width == expected_width:
            score += 0.5
        if found_height == expected_height:
            score += 0.5
        return score
    except Exception as e:
        return 0.0

