def check_function_defs__380297fe(result_file_path, expected, **options):
    """Check if function definitions are correctly extracted from code.

    Args:
        result_file_path: Path to file containing extracted function definitions
        expected: Dict with 'required_functions' (list) and 'min_functions' (int)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file_path:
        return 0.0
    try:
        with open(result_file_path, 'r', encoding='utf-8') as f:
            content = f.read()
        lines = [line.strip() for line in content.splitlines() if line.strip()]
        def_lines = [line for line in lines if line.startswith('def ')]
        required_functions = expected.get('required_functions', [])
        min_functions = expected.get('min_functions', 0)
        score = 0.0
        if required_functions:
            found_count = sum((1 for func in required_functions if f'def {func}(' in content or f'def {func} (' in content))
            required_score = found_count / len(required_functions)
            score += required_score * 0.6
        if len(def_lines) >= min_functions:
            score += 0.4
        return min(score, 1.0)
    except Exception as e:
        print(f'Error checking function definitions: {e}')
        return 0.0

