def check_function_signatures__6082ba78(result, expected, **options):
    """
    Validate extracted function signatures.

    Args:
        result: List of signature lines from getter
        expected: Dict with 'min_signatures', 'pattern', 'expected_names' keys
        **options: Additional options (partial_credit)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, list):
        return 0.0
    min_signatures = expected.get('min_signatures', 1)
    pattern = expected.get('pattern', 'def ')
    expected_names = expected.get('expected_names', [])
    partial_credit = options.get('partial_credit', False)
    score = 0.0
    if len(result) >= min_signatures:
        score += 0.4
    if any((pattern in sig for sig in result)):
        score += 0.2
    if expected_names:
        all_content = ' '.join(result)
        names_found = sum((1 for name in expected_names if name in all_content))
        if partial_credit:
            score += 0.4 * (names_found / len(expected_names))
        elif names_found == len(expected_names):
            score += 0.4
    else:
        score += 0.4
    return min(1.0, score)

def check_note_and_bg__85b37592(result, expected, **options):
    """Check slide note text and background color.

    Args:
        result: dict with 'note_text' and 'bg_rgb' from getter
        expected: dict with 'note_text' (str) and 'bg_rgb' (tuple)
        **options: 'color_tolerance' for RGB distance threshold (default: 20)

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_text = expected.get('note_text', '')
    result_text = result.get('note_text', '')
    if result_text == expected_text:
        score += 0.5
    expected_rgb = expected.get('bg_rgb')
    result_rgb = result.get('bg_rgb')
    if expected_rgb and result_rgb:
        (r1, g1, b1) = result_rgb
        (r2, g2, b2) = expected_rgb
        color_tolerance = options.get('color_tolerance', 20)
        distance = sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2)
        if distance <= color_tolerance:
            score += 0.5
    elif expected_rgb is None and result_rgb is None:
        score += 0.5
    return score

