def check_bib_venues__7e57116f(result: List[str], expected: dict, **options) -> float:
    """
    Check if specific venues are present in the BibTeX file.

    Args:
        result: List of venue names from getter
        expected: Expected rules dict with 'required_venues' key
        **options: Additional options

    Returns:
        float: Proportion of required venues found (0.0-1.0)
    """
    required_venues = expected.get('required_venues', [])
    if not required_venues:
        return 0.0
    required_normalized = [v.lower() for v in required_venues]
    found_count = 0
    for req_venue in required_normalized:
        for res_venue in result:
            if req_venue in res_venue or res_venue in req_venue:
                found_count += 1
                break
    return found_count / len(required_venues)

def check_address_filled_b3__d58db47f(result, expected, **options):
    """Check if cell(s) are filled with valid data

    Args:
        result: Data from getter function
        expected: Expected rules dict
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    if isinstance(result, list):
        min_length = expected.get('min_length', 1)
        cells = expected.get('cells', [])
        if len(result) != len(cells):
            return 0.0
        score = 0.0
        for value in result:
            if value and len(value) >= min_length:
                score += 1.0 / len(result)
        return score
    elif isinstance(result, dict):
        name = result.get('name', '')
        address = result.get('address', '')
        min_name_length = expected.get('min_name_length', 1)
        min_address_length = expected.get('min_address_length', 1)
        score = 0.0
        if name and len(name) >= min_name_length:
            score += 0.5
        if address and len(address) >= min_address_length:
            score += 0.5
        return score
    elif isinstance(result, int):
        min_count = expected.get('min_count', 1)
        if result >= min_count:
            return 1.0
        else:
            return result / min_count if min_count > 0 else 0.0
    elif 'must_contain' in expected:
        if expected['must_contain'].lower() in result.lower():
            return 1.0
        else:
            return 0.0
    else:
        min_length = expected.get('min_length', 1)
        if result and len(result) >= min_length:
            return 1.0
        else:
            return 0.0

