def check_grayscale_conversion__13141e42(result_path, expected, **options):
    """
    Check if the image has been converted to grayscale.

    Args:
        result_path: Path to the result image
        expected: Not used (placeholder for consistency)
        **options: Additional options

    Returns:
        float: Score (1.0 if grayscale, 0.0 otherwise)
    """
    if result_path is None:
        logger.error('Result path is None')
        return 0.0
    try:
        img = Image.open(result_path)
        if img.mode == 'L':
            logger.info('Image is in grayscale mode (L)')
            return 1.0
        elif img.mode == 'LA':
            logger.info('Image is in grayscale with alpha mode (LA)')
            return 1.0
        elif img.mode in ('RGB', 'RGBA'):
            img_rgb = img.convert('RGB')
            img_array = np.array(img_rgb)
            r = img_array[:, :, 0]
            g = img_array[:, :, 1]
            b = img_array[:, :, 2]
            is_grayscale = np.allclose(r, g, atol=2) and np.allclose(g, b, atol=2)
            logger.info(f'Image mode: {img.mode}, is_grayscale: {is_grayscale}')
            return 1.0 if is_grayscale else 0.0
        else:
            logger.warning(f'Unexpected image mode: {img.mode}')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking grayscale: {e}')
        import traceback
        logger.error(traceback.format_exc())
        return 0.0

def check_autofilter_applied__7f7184ff(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if AutoFilter is enabled and configured correctly.

    Args:
        result: AutoFilter state from getter with keys:
            - enabled: bool
            - filtered_column: str or None
            - filter_criteria: dict or None
            - visible_row_count: int
        expected: Dict with:
            - enabled: bool (required)
            - filtered_column: str (optional) - name of column that should be filtered
            - filter_operator: str (optional) - expected operator (e.g., 'greaterThanOrEqual')
            - filter_value: str/int (optional) - expected filter value
            - exact_visible_rows: int (optional) - exact number of visible rows expected
            - min_visible_rows: int (optional) - minimum number of visible rows (fallback)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result.get('enabled'):
        return 0.0
    expected_enabled = expected.get('enabled', True)
    if not expected_enabled:
        return 0.0
    expected_column = expected.get('filtered_column')
    if expected_column is not None:
        actual_column = result.get('filtered_column')
        if actual_column != expected_column:
            return 0.3
    expected_operator = expected.get('filter_operator')
    expected_value = expected.get('filter_value')
    if expected_operator is not None or expected_value is not None:
        filter_criteria = result.get('filter_criteria')
        if filter_criteria is None:
            return 0.3
        if 'custom_filters' in filter_criteria:
            custom_filters = filter_criteria['custom_filters']
            criteria_match = False
            for cf in custom_filters:
                operator_match = expected_operator is None or cf.get('operator') == expected_operator
                value_match = True
                if expected_value is not None:
                    actual_val = cf.get('value')
                    try:
                        if isinstance(expected_value, (int, float)):
                            value_match = float(actual_val) == float(expected_value)
                        else:
                            value_match = str(actual_val) == str(expected_value)
                    except (ValueError, TypeError):
                        value_match = str(actual_val) == str(expected_value)
                if operator_match and value_match:
                    criteria_match = True
                    break
            if not criteria_match:
                return 0.5
    exact_visible = expected.get('exact_visible_rows')
    if exact_visible is not None:
        actual_count = result.get('visible_row_count', len(result.get('visible_rows', [])))
        if actual_count != exact_visible:
            return 0.7
    else:
        min_visible = expected.get('min_visible_rows')
        if min_visible is not None:
            actual_count = result.get('visible_row_count', len(result.get('visible_rows', [])))
            if actual_count < min_visible:
                return 0.7
    return 1.0

def check_memory_termination__2bbcb06d2bf4873e3a09c6cce62c02ec(result, expected, **options):
    """Check if memory was checked before termination.

    Args:
        result: Command output string
        expected: Expected patterns (dict with include/exclude lists)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, str):
        return 0.0
    include_patterns = expected.get('include', [])
    exclude_patterns = expected.get('exclude', [])
    score = 0.0
    terminated = True
    for pattern in ['no libreoffice is running']:
        if pattern not in result:
            terminated = False
            break
    if terminated:
        score += 0.5
    memory_checked = True
    for pattern in ['ps used in terminal']:
        if pattern not in result:
            memory_checked = False
            break
    if memory_checked:
        score += 0.5
    for pattern in exclude_patterns:
        if pattern in result:
            return 0.0
    return score

