def check_unique_pairs__836f6892615cef23855bbcfb4fe991c6(result: List[Dict[str, str]], expected: Dict[str, Any], **options) -> float:
    """
    Check if all train-station pairs in the document are unique (no duplicates).

    Args:
        result: List of dicts with train_id and station_id from getter
        expected: Dict with 'expected_count' key (number of unique pairs expected)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list):
        logger.error(f'Result is not a list: {type(result)}')
        return 0.0
    expected_count = expected.get('expected_count')
    if expected_count is None:
        logger.error('Missing expected_count in expected config')
        return 0.0
    if len(result) != expected_count:
        logger.info(f'Record count mismatch: got {len(result)}, expected {expected_count}')
        return 0.0
    seen_pairs = set()
    for record in result:
        if not isinstance(record, dict):
            logger.error(f'Invalid record type: {type(record)}')
            return 0.0
        train_id = record.get('train_id')
        station_id = record.get('station_id')
        if not train_id or not station_id:
            logger.error(f'Missing train_id or station_id in record: {record}')
            return 0.0
        pair = (train_id, station_id)
        if pair in seen_pairs:
            logger.info(f'Found duplicate train-station pair: {pair}')
            return 0.0
        seen_pairs.add(pair)
    return 1.0

def check_words_colored_by_length__3d9f327a(file_path1, file_path2, **kwargs):
    """
    Check if words are colored by length: green for 1-3 letters, yellow for 4+ letters.

    Args:
        file_path1: Path to result file
        file_path2: Path to expected file (unused)
        **kwargs: threshold for color tolerance (default: 20.0)

    Returns:
        float: 1.0 if coloring is correct, 0.0 otherwise
    """
    if not file_path1:
        return 0.0
    try:
        document = Document(file_path1)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    threshold = kwargs.get('threshold', 20.0)

    def _calculate_color_difference(rgb1, rgb2):
        """Calculate color difference using CIEDE2000"""
        srgb1 = [rgb1[0] / 255.0, rgb1[1] / 255.0, rgb1[2] / 255.0]
        srgb2 = [rgb2[0] / 255.0, rgb2[1] / 255.0, rgb2[2] / 255.0]
        (lab1, lab2) = (rgb2lab(srgb1), rgb2lab(srgb2))
        delta_e = deltaE_ciede2000(lab1, lab2)
        return delta_e
    green_color = RGBColor(0, 128, 0)
    yellow_color = RGBColor(255, 255, 0)
    for table in document.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        word = run.text.strip()
                        if word and run.font.color and run.font.color.rgb:
                            word_length = len(word)
                            if word_length <= 3:
                                if _calculate_color_difference(run.font.color.rgb, green_color) > threshold:
                                    logger.info(f"Short word '{word}' is not green")
                                    return 0.0
                            elif _calculate_color_difference(run.font.color.rgb, yellow_color) > threshold:
                                logger.info(f"Long word '{word}' is not yellow")
                                return 0.0
    return 1.0

def check_ext_both__9baceeed6f794b327257ca3ebfd3fa75(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if extension name, path, enabled state, and developer mode all match expectations.

    Args:
        result: Dict with 'names', 'paths', 'enabled_states', and 'dev_mode_states' lists from getter
        expected: Dict with 'expected_name' and 'expected_path'

    Returns:
        0.25 for name match, 0.25 for path match, 0.25 for enabled, 0.25 for developer mode (1.0 total)
    """
    if not result:
        logger.info('No extension info found')
        return 0.0
    score = 0.0
    expected_name = expected.get('expected_name', '')
    names = result.get('names', [])
    logger.info(f'Checking for extension name: {expected_name}')
    logger.info(f'Installed extension names: {names}')
    name_index = -1
    if expected_name in names:
        name_index = names.index(expected_name)
        logger.info(f"Extension name '{expected_name}' found at index {name_index}")
        score += 0.25
    else:
        logger.info(f"Extension name '{expected_name}' not found")
    expected_path = expected.get('expected_path', '')
    paths = result.get('paths', [])
    logger.info(f'Checking for extension path: {expected_path}')
    logger.info(f'Installed extension paths: {paths}')
    path_index = -1
    if expected_path in paths:
        path_index = paths.index(expected_path)
        logger.info(f"Extension path '{expected_path}' found at index {path_index}")
        score += 0.25
    else:
        logger.info(f"Extension path '{expected_path}' not found")
    enabled_states = result.get('enabled_states', [])
    if name_index >= 0 and name_index < len(enabled_states):
        is_enabled = enabled_states[name_index]
        logger.info(f'Extension enabled state: {is_enabled}')
        if is_enabled:
            logger.info('Extension is enabled')
            score += 0.25
        else:
            logger.info('Extension is NOT enabled')
    else:
        logger.info('Cannot check enabled state - extension not found or index out of range')
    dev_mode_states = result.get('dev_mode_states', [])
    if name_index >= 0 and name_index < len(dev_mode_states):
        is_dev_mode = dev_mode_states[name_index]
        logger.info(f'Extension developer mode state: {is_dev_mode}')
        if is_dev_mode:
            logger.info('Extension is in developer mode (unpacked)')
            score += 0.25
        else:
            logger.info('Extension is NOT in developer mode')
    else:
        logger.info('Cannot check developer mode - extension not found or index out of range')
    logger.info(f'Final score: {score}')
    return score

def check_master_view_toolbar__8fdab3ded691e7a89e79c06ac105c316(accessibility_tree, expected, **options):
    """
    Check if Master View toolbar is visible in LibreOffice Impress.

    Args:
        accessibility_tree: XML string of accessibility tree
        expected: Expected rules dict containing toolbar_items
        **options: Additional options

    Returns:
        float: 1.0 if Master View toolbar is visible, 0.0 otherwise
    """
    toolbar_keywords = expected.get('toolbar_keywords', ['Master', 'Close Master'])
    try:
        root = ET.fromstring(accessibility_tree)
        for toolbar in root.iter('tool-bar'):
            toolbar_name = toolbar.attrib.get('name', '')
            if any((keyword in toolbar_name for keyword in toolbar_keywords)):
                return 1.0
        master_button_found = False
        for button in root.iter('push-button'):
            button_name = button.attrib.get('name', '')
            if 'Close Master' in button_name or 'Master View' in button_name:
                master_button_found = True
                break
        if master_button_found:
            return 1.0
        return 0.0
    except Exception:
        return 0.0

def check_contains_values__9cefe3d0(result, expected, **options):
    """Check if text contains all expected values.
    
    Args:
        result: Text content from file
        expected: Dict with 'values' key (list of strings to find)
        
    Returns:
        float: Ratio of found values to total expected values
    """
    if result is None:
        return 0.0
    values = expected.get('values', [])
    if not values:
        return 0.0
    found = sum((1 for val in values if str(val) in result))
    return found / len(values)

def check_contains_keyword__dfc9794a(result, expected, **options):
    """Check if the output contains specific keywords and sorted numbers.

    Args:
        result: List of lines from file
        expected: Dict with 'keywords' and 'contains_numbers' keys

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    score = 0.0
    keywords = expected.get('keywords', [])
    contains_numbers = expected.get('contains_numbers', [])
    text = ' '.join(result)
    keyword_score = 0.0
    if keywords:
        found_keywords = sum((1 for kw in keywords if kw.lower() in text.lower()))
        keyword_score = found_keywords / len(keywords)
        score += 0.5 * keyword_score
    if contains_numbers:
        import re
        numbers = re.findall('\\d+', text)
        numbers = [int(n) for n in numbers]
        found_numbers = sum((1 for num in contains_numbers if num in numbers))
        number_score = found_numbers / len(contains_numbers)
        score += 0.5 * number_score
    return score

def check_phone_numbers_valid__7f5f8a0f(result, expected, **options):
    """Check if phone numbers are filled and contain digits.

    Args:
        result: List of phone numbers from Excel
        expected: Dict with 'min_digits' key (minimum digits required)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, list):
        return 0.0
    min_digits = expected.get('min_digits', 8)
    valid_count = 0
    for phone in result:
        if phone and phone.strip():
            digits = re.findall('\\d', phone)
            if len(digits) >= min_digits:
                valid_count += 1
    return valid_count / len(result)

