def check_placeholder_replaced__22c06cde(result, expected, **options):
    """Check if placeholder text was replaced with correct citation.

    Args:
        result: Path to the result DOCX file
        expected: Dict with 'search_text', 'should_not_contain', 'should_contain' keys

    Returns:
        float: Score based on placeholder removal and citation addition
    """
    if not result or not isinstance(result, str):
        return 0.0
    try:
        doc = Document(result)
        search_text = expected.get('search_text', '')
        should_not_contain = expected.get('should_not_contain', '')
        should_contain = expected.get('should_contain', '')
        target_para = None
        for para in doc.paragraphs:
            if search_text in para.text:
                target_para = para.text
                break
        if not target_para:
            return 0.0
        score = 0.0
        if should_not_contain not in target_para:
            score += 0.5
        if should_contain in target_para:
            score += 0.5
        return score
    except Exception as e:
        print(f'Error in check_placeholder_replaced__22c06cde: {e}')
        return 0.0

def check_column_order__13e320f3(result: Any, expected: Any, **options) -> float:
    """Check if column values are in expected order.

    Args:
        result: List of values from getter
        expected: Expected list of values in order, or dict with 'order' key
        **options: Additional options (ignore_case)

    Returns:
        1.0 if order matches, 0.0 otherwise
    """
    if not result or not isinstance(result, list):
        return 0.0
    if isinstance(expected, dict):
        expected = expected.get('order', [])
    if not expected or not isinstance(expected, list):
        return 0.0
    if len(result) != len(expected):
        return 0.0
    ignore_case = options.get('ignore_case', False)
    if ignore_case:
        result = [str(v).lower() if v else '' for v in result]
        expected = [str(v).lower() if v else '' for v in expected]
    else:
        result = [str(v) if v else '' for v in result]
        expected = [str(v) if v else '' for v in expected]
    return 1.0 if result == expected else 0.0

def check_sentence_count__025e38f5(result: int, rules: int, **options) -> float:
    """
    Check if the sentence count matches the expected value within tolerance.

    This metric compares the actual sentence count from the document with the
    expected count. It supports a tolerance parameter to allow for minor
    variations in sentence counting.

    Args:
        result (int): Actual sentence count from the getter
        rules (int): Expected sentence count
        **options: Additional options including:
            - tolerance (int): Allowed difference from expected count (default: 0)

    Returns:
        float: 1.0 if count is within tolerance, 0.0 otherwise
    """
    tolerance = options.get('tolerance', 0)
    if result is None:
        return 0.0
    if abs(result - rules) <= tolerance:
        return 1.0
    else:
        return 0.0

