def check_pid_found__40af35fe598121c8777817c94b7aadfb(result, expected, **options):
    """Check if the PID was found successfully.

    Args:
        result: Output string from the command
        expected: Dict containing 'include' and 'exclude' patterns
        **options: Additional options

    Returns:
        float: 1.0 if all include patterns are found and all exclude patterns are not found, 0.0 otherwise
    """
    if result is None:
        return 0.0
    include = expected.get('include', [])
    exclude = expected.get('exclude', [])
    logger.info(f'Checking result: {result}')
    logger.info(f'Include patterns: {include}')
    logger.info(f'Exclude patterns: {exclude}')
    for pattern in include:
        if pattern not in result:
            logger.info(f'Missing required pattern: {pattern}')
            return 0.0
    for pattern in exclude:
        if pattern in result:
            logger.info(f'Found excluded pattern: {pattern}')
            return 0.0
    return 1.0

def check_autosave_interval__86350d0e(config_file, rules):
    """Check if auto-save interval is set to 2 minutes.

    Args:
        config_file: Path to registrymodifications.xcu file
        rules: Dict with "minutes" key - expected interval

    Returns:
        1.0 if interval matches, 0.0 otherwise
    """
    expected_minutes = rules['minutes']
    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
        autosave_time = None
        for item in root.findall('.//item'):
            path = item.get('{http://openoffice.org/2001/registry}path')
            if path == '/org.openoffice.Office.Common/Save/Document':
                for prop in item.findall('.//prop'):
                    name = prop.get('{http://openoffice.org/2001/registry}name')
                    if name == 'AutoSaveTimeIntervall':
                        value_elem = prop.find('.//value')
                        if value_elem is not None:
                            autosave_time = int(value_elem.text)
                        break
        if autosave_time is None:
            return 0.0
        return 1.0 if autosave_time == expected_minutes else 0.0
    except (ET.ParseError, FileNotFoundError, ValueError) as e:
        logger.error(f'Error checking autosave interval: {e}')
        return 0.0

def check_document_structure__a53ef9d4(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if document structure meets requirements with partial credit.

    Args:
        result: Actual structure dict from getter (includes text_content)
        expected: Rules dict with min_paragraphs, min_words keys
        **options: Additional options

    Returns:
        Score from 0.0 to 1.0 based on requirements met
    """
    if result is None or not result.get('has_content'):
        return 0.0
    score = 0.0
    if result.get('has_content'):
        score += 0.2
    min_paragraphs = expected.get('min_paragraphs', 1)
    if result.get('paragraph_count', 0) >= min_paragraphs:
        score += 0.2
    min_words = expected.get('min_words', 10)
    if result.get('word_count', 0) >= min_words:
        score += 0.2
    text_content = result.get('text_content', '').lower()
    keyword_groups = [['grid', 'layout', 'column', 'margin', 'spacing', 'alignment'], ['apple', 'ios', 'macos', 'human interface', 'hig', 'guideline', 'design']]
    groups_matched = 0
    for group in keyword_groups:
        if any((keyword in text_content for keyword in group)):
            groups_matched += 1
    if groups_matched == 2:
        score += 0.4
    elif groups_matched == 1:
        score += 0.2
    return score

def check_uppercase__0990d8ae(result, expected, **options):
    """Check if all alphabetic characters in the text are uppercase.

    Args:
        result: Text content from getter
        expected: Expected value (not used, just needs uppercase check)
        **options: Additional options

    Returns:
        float: 1.0 if all text is uppercase, 0.0 otherwise
    """
    if not result:
        return 0.0
    letters = [c for c in result if c.isalpha()]
    if not letters:
        return 0.0
    uppercase_count = sum((1 for c in letters if c.isupper()))
    if uppercase_count == len(letters):
        return 1.0
    else:
        return 0.0

def check_background_and_frame__005bc54f(result_state: dict, expected_state: dict, **options) -> float:
    """
    Check if a slide has a background image AND the extracted frame file exists.

    This metric validates both requirements:
    1. The slide has a background image applied
    2. The extracted frame file exists at the specified path

    This provides stronger evidence that the user actually extracted a video frame
    rather than using any random image.

    Args:
        result_state: Dictionary from getter with 'has_background' and 'frame_file_exists' keys (bool)
        expected_state: Dictionary with expected rules, containing 'has_background' and 'frame_file_exists' keys (bool)
        **options: Additional options (unused)

    Returns:
        float: Score 1.0 if both conditions match expected, 0.0 otherwise
    """
    if result_state is None:
        logger.info('Result state is None, returning 0.0')
        return 0.0
    if not isinstance(result_state, dict):
        logger.info(f'Result state is not a dict (got {type(result_state)}), returning 0.0')
        return 0.0
    if expected_state is None or not isinstance(expected_state, dict):
        logger.info('Expected state is None or not a dict, returning 0.0')
        return 0.0
    has_background_actual = result_state.get('has_background', False)
    frame_file_exists_actual = result_state.get('frame_file_exists', False)
    has_background_expected = expected_state.get('has_background', False)
    frame_file_exists_expected = expected_state.get('frame_file_exists', False)
    logger.info(f'Checking background and frame: background_actual={has_background_actual}, background_expected={has_background_expected}, frame_actual={frame_file_exists_actual}, frame_expected={frame_file_exists_expected}')
    if has_background_actual == has_background_expected and frame_file_exists_actual == frame_file_exists_expected:
        logger.info('Both background and frame file conditions match expected, returning 1.0')
        return 1.0
    else:
        logger.info('Background or frame file condition does NOT match expected, returning 0.0')
        return 0.0

def check_notes_unchanged__67735967(result_file, expected, **options):
    """
    Check that notes are added to slides missing them while preserving existing notes.

    This metric verifies two requirements:
    1. Notes are added to all slides except those with existing notes to preserve
    2. Existing notes on slide 4 remain unchanged

    Args:
        result_file: Path to the PPTX file
        expected: Dict with rules containing:
            - 'slide_index': Index of slide with existing notes to preserve (3 for slide 4)
            - 'original_notes': The original notes text that should be preserved
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 based on partial credit:
               - 0.5 for preserving slide 4 notes
               - 0.5 for adding notes to other slides
    """
    try:
        prs = Presentation(result_file)
        slide_index = expected.get('slide_index', 0)
        original_notes = expected.get('original_notes', '').strip()
        score = 0.0
        if slide_index < len(prs.slides):
            slide = prs.slides[slide_index]
            notes_slide = slide.notes_slide
            if notes_slide and notes_slide.notes_text_frame:
                actual_notes = notes_slide.notes_text_frame.text.strip()
            else:
                actual_notes = ''
            if actual_notes == original_notes:
                score += 0.5
        other_slides_with_notes = 0
        total_other_slides = 0
        for idx in range(len(prs.slides)):
            if idx == slide_index:
                continue
            total_other_slides += 1
            slide = prs.slides[idx]
            notes_slide = slide.notes_slide
            if notes_slide and notes_slide.notes_text_frame:
                slide_notes = notes_slide.notes_text_frame.text.strip()
            else:
                slide_notes = ''
            if slide_notes:
                other_slides_with_notes += 1
        if total_other_slides > 0:
            score += 0.5 * (other_slides_with_notes / total_other_slides)
        return score
    except Exception as e:
        return 0.0

def check_sorted_with_count__03d4ebf8db116d0dd3db06d0b1b6415c(result, expected, **options):
    """
    Check if output contains sorted values and swap count.

    Args:
        result: List of lines from the file
        expected: Dict with 'sorted_values' and 'swap_count' keys
        **options: Additional options

    Returns:
        float: Partial score - 0.6 for sorted values, 0.4 for correct swap count
    """
    if not isinstance(result, list) or not result:
        return 0.0
    expected_values = expected.get('sorted_values', [])
    expected_count = expected.get('swap_count', None)
    if not expected_values:
        return 0.0
    score = 0.0
    try:
        numeric_lines = []
        count_line = None
        for line in result:
            try:
                numeric_lines.append(int(line))
            except ValueError:
                if 'swap' in line.lower() or 'number' in line.lower():
                    count_line = line
        if len(numeric_lines) >= len(expected_values):
            if numeric_lines[:len(expected_values)] == expected_values:
                score += 0.6
        if expected_count is not None and count_line:
            import re
            numbers = re.findall('\\d+', count_line)
            if numbers and int(numbers[-1]) == expected_count:
                score += 0.4
    except Exception as e:
        print(f'Error parsing result: {e}')
        return score
    return score

def check_task_completion__b5ea50259ef22390cfce3df1c7f68cea(result, expected, **options):
    """Check all task steps with partial credit scoring.

    Verifies:
    1. CSV file exported (0.33 points)
    2. Python script created (0.33 points)
    3. Correct result (0.34 points)

    Args:
        result: dict with keys 'csv_exists', 'python_script_exists', 'result_content'
        expected: dict with expected company name (from rules dict)
        **options: Additional options (case_sensitive)

    Returns:
        float: Score from 0.0 to 1.0 based on completion
    """
    score = 0.0
    case_sensitive = options.get('case_sensitive', False)
    if result.get('csv_exists', False):
        score += 0.33
    if result.get('python_script_exists', False):
        score += 0.33
    result_content = result.get('result_content', '')
    expected_name = expected.get('company_name')
    if result_content and expected_name:
        result_content = result_content.strip()
        expected_name = expected_name.strip()
        if case_sensitive:
            if result_content == expected_name:
                score += 0.34
            elif expected_name in result_content:
                score += 0.17
        elif result_content.lower() == expected_name.lower():
            score += 0.34
        elif expected_name.lower() in result_content.lower():
            score += 0.17
    return score

def check_sort_and_chart__7ae37a60(result_state: Dict[str, Any], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if data is sorted correctly by Product column and a line chart is created with correct axes.

    This metric verifies two aspects:
    1. Sorting: Checks if Product names are sorted in alphabetical order (A to Z) (50% weight)
    2. Chart: Checks if a line chart exists with correct axis mappings (50% weight)
       - Chart type verification (25% weight)
       - Axis mapping verification (25% weight): Web Site on X-axis, Quantity on Y-axis

    Args:
        result_state: Dict from getter with keys:
            - product_names (list): Product names from Product column (C, index 2)
            - charts (list): List of chart info dicts with:
                - type (str): Chart class name
                - series_data (dict): Data series information with x_column, y_column, x_values, y_values
        expected_state: Rules dict directly (when type='rule') containing:
            - order (str): 'asc' or 'desc' for sorting order
            - chart_type (str): Expected chart type (e.g., 'LineChart')
            - x_column (int): Expected column number (1-based) for X-axis
            - y_column (int): Expected column number (1-based) for Y-axis
        **options: Additional options (not used currently)

    Returns:
        float: Score between 0.0 and 1.0
            - 0.5 for correct sorting
            - 0.25 for correct chart type
            - 0.25 for correct axis mappings
            - Total: 1.0 for all correct
    """
    if not result_state or not expected_state:
        return 0.0
    expected_order = expected_state.get('order', 'asc')
    expected_chart_type = expected_state.get('chart_type', 'LineChart')
    expected_x_column = expected_state.get('x_column', 1)
    expected_y_column = expected_state.get('y_column', 6)
    product_names = result_state.get('product_names', [])
    charts = result_state.get('charts', [])
    score = 0.0
    if len(product_names) >= 2:
        is_sorted_asc = all((product_names[i].lower() <= product_names[i + 1].lower() for i in range(len(product_names) - 1)))
        is_sorted_desc = all((product_names[i].lower() >= product_names[i + 1].lower() for i in range(len(product_names) - 1)))
        if expected_order.lower() == 'asc' and is_sorted_asc:
            score += 0.5
        elif expected_order.lower() == 'desc' and is_sorted_desc:
            score += 0.5
    expected_chart_lower = expected_chart_type.lower()
    chart_found = False
    axis_mapping_correct = False
    for chart_info in charts:
        chart_type = chart_info.get('type', '')
        if chart_type.lower() == expected_chart_lower:
            chart_found = True
            series_data = chart_info.get('series_data', {})
            x_column = series_data.get('x_column')
            y_column = series_data.get('y_column')
            if x_column == expected_x_column and y_column == expected_y_column:
                axis_mapping_correct = True
                break
    if chart_found:
        score += 0.25
    if axis_mapping_correct:
        score += 0.25
    return score

