def check_nba_store_filters__9f3f70fc(result_state, expected_state, **options):
    """
    Check if the NBA store filters match the expected state.

    Args:
        result_state: dict from get_nba_store_filters__9f3f70fc with filter states
        expected_state: dict with expected filter states
            - expected: dict with filter names as keys and True as values
            - is_other_exist: False (no unexpected filters)
            - has_products: True (optional, if we want to verify products are shown)

    Returns:
        float: 1.0 if all expected filters are applied and no unexpected ones exist,
               0.0 otherwise
    """
    logger.info(f'[CHECK_NBA_FILTERS] Checking filters')
    logger.info(f'[CHECK_NBA_FILTERS] Result state: {result_state}')
    logger.info(f'[CHECK_NBA_FILTERS] Expected state: {expected_state}')
    if result_state is None or not isinstance(result_state, dict):
        logger.error(f'[CHECK_NBA_FILTERS] Invalid result_state: {result_state}')
        return 0.0
    expected = expected_state.get('expected', {})
    if not expected:
        logger.error(f'[CHECK_NBA_FILTERS] No expected filters provided')
        return 0.0
    all_filters_found = True
    for (filter_name, expected_value) in expected.items():
        if filter_name == 'is_other_exist':
            result_value = result_state.get('is_other_exist', True)
            if result_value != expected_value:
                logger.warning(f'[CHECK_NBA_FILTERS] is_other_exist mismatch: expected {expected_value}, got {result_value}')
                all_filters_found = False
        elif filter_name == 'has_products':
            result_value = result_state.get('has_products', False)
            if expected_value and (not result_value):
                logger.warning(f'[CHECK_NBA_FILTERS] No products displayed on page (required for browsing task)')
                all_filters_found = False
            elif result_value:
                logger.info(f'[CHECK_NBA_FILTERS] Products are displayed on page')
        else:
            filter_lower = filter_name.lower()
            result_value = result_state.get(filter_lower, False)
            if expected_value and (not result_value):
                logger.warning(f"[CHECK_NBA_FILTERS] Expected filter '{filter_name}' not found")
                all_filters_found = False
            elif not expected_value and result_value:
                logger.warning(f"[CHECK_NBA_FILTERS] Filter '{filter_name}' found but not expected")
                all_filters_found = False
            else:
                logger.info(f"[CHECK_NBA_FILTERS] Filter '{filter_name}' status correct: {result_value}")
    if 'is_other_exist' in expected:
        result_other = result_state.get('is_other_exist', True)
        expected_other = expected.get('is_other_exist', False)
        if result_other != expected_other:
            logger.warning(f'[CHECK_NBA_FILTERS] Unexpected filters exist: expected {expected_other}, got {result_other}')
            all_filters_found = False
    if all_filters_found:
        logger.info('[CHECK_NBA_FILTERS] All filters match expected state')
        return 1.0
    else:
        logger.warning('[CHECK_NBA_FILTERS] Filters do not match expected state')
        return 0.0

