def check_first_word_red__86dadaf17d168f26f262a4e9de54fa47(result: Dict[int, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the first word of each paragraph has red color.

    Args:
        result: Dict from getter with paragraph indices mapped to RGB colors
        expected: Expected configuration with 'target_color' (RGB tuple)
        **options: Additional options (e.g., 'tolerance' for color matching)

    Returns:
        Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    target_color = expected.get('target_color', (255, 0, 0))
    tolerance = options.get('tolerance', 10)
    total_paras = len(result)
    if total_paras == 0:
        return 0.0
    correct_count = 0
    for (para_idx, color) in result.items():
        if color is None:
            continue
        if isinstance(color, RGBColor):
            r = color >> 16 & 255
            g = color >> 8 & 255
            b = color & 255
        elif hasattr(color, '__iter__') and len(color) == 3:
            (r, g, b) = color
        else:
            continue
        (target_r, target_g, target_b) = target_color
        if abs(r - target_r) <= tolerance and abs(g - target_g) <= tolerance and (abs(b - target_b) <= tolerance):
            correct_count += 1
    return correct_count / total_paras

