def check_properties_panel__1d99b576a155ae90bea88d4622546fb1(accessibility_tree, expected, **options):
    """
    Check if the Properties panel is visible in LibreOffice Impress.
    The Properties panel is typically on the right side and shows properties of selected objects.

    Args:
        accessibility_tree: XML string of the accessibility tree
        expected: Expected rules dict (not used, but required by framework)
        **options: Additional options

    Returns:
        float: 1.0 if Properties panel is visible, 0.0 otherwise
    """
    namespaces = {'st': 'uri:deskat:state.at-spi.gnome.org', 'cp': 'uri:deskat:component.at-spi.gnome.org'}
    try:
        root = ET.fromstring(accessibility_tree)
        properties_panel_element = None
        for panel in root.iter('panel'):
            name = panel.attrib.get('name', '')
            if 'properties' in name.lower():
                properties_panel_element = panel
                break
        if properties_panel_element is None:
            return 0.0
        property_indicators = ['position and size', 'fill', 'line', 'area', 'shadow', 'transparency', 'gradient', 'bitmap', 'pattern', 'hatch', 'character', 'paragraph', 'animation', 'slide transition']
        for element in properties_panel_element.iter():
            element_name = element.attrib.get('name', '').lower()
            for indicator in property_indicators:
                if indicator in element_name:
                    return 1.0
        return 0.0
    except Exception as e:
        logger.error(f'Error checking properties panel: {e}')
        return 0.0

