def check_rating_categories__43260c3c(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if the rating_categories sheet has correct structure and contains movies with ratings >= 8.0,
    properly categorized/grouped by rating tier.

    Scoring breakdown (from metadata):
    - has_headers: 0.2 - Sheet has header row matching original sheet
    - min_movies_present: 0.3 - At least 150 movies are present (min_total_movies)
    - valid_rating_data: 0.3 - Rating column exists and has valid numeric data >= 8.0
    - rating_variety: 0.2 - Data shows variety in rating ranges (not all same value)

    Args:
        result: Dict with 'headers', 'rows', and optionally 'original_headers' from getter
                Or dict with 'error' key if sheet not found
        expected: Dict (rules dict) containing:
            - has_headers: True/False - whether headers should be present
            - min_total_movies: Minimum number of movies (150)
            - original_file_path: Path to original file (for reference)
            - original_sheet_name: Name of original sheet (for header comparison)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    rules = expected
    has_headers_required = rules.get('has_headers', True)
    min_total_movies = rules.get('min_total_movies', 150)
    score = 0.0
    actual_headers = result.get('headers', [])
    actual_rows = result.get('rows', [])
    original_headers = result.get('original_headers', [])
    if has_headers_required:
        if len(actual_headers) >= 3 and len(original_headers) >= 3:
            headers_match = True
            if len(actual_headers) >= len(original_headers):
                for (i, orig_header) in enumerate(original_headers):
                    if i >= len(actual_headers) or actual_headers[i] != orig_header:
                        headers_match = False
                        break
            else:
                headers_match = False
            if headers_match:
                score += 0.2
        elif len(actual_headers) >= 3 and len(original_headers) == 0:
            score += 0.2
    if len(actual_rows) >= min_total_movies:
        score += 0.3
    rating_column_idx = -1
    for (i, header) in enumerate(actual_headers):
        if 'rating' in header or 'score' in header:
            rating_column_idx = i
            break
    if rating_column_idx == -1 and len(actual_headers) >= 3:
        rating_column_idx = 2
    if len(actual_rows) > 0 and rating_column_idx >= 0:
        all_ratings_valid = True
        valid_rating_count = 0
        ratings_list = []
        for row in actual_rows:
            if len(row) > rating_column_idx:
                rating_value = row[rating_column_idx]
                try:
                    rating_float = float(rating_value)
                    if rating_float >= 8.0:
                        valid_rating_count += 1
                        ratings_list.append(rating_float)
                    else:
                        all_ratings_valid = False
                        break
                except (ValueError, TypeError):
                    all_ratings_valid = False
                    break
            else:
                all_ratings_valid = False
                break
        if all_ratings_valid and valid_rating_count > 0:
            score += 0.3
    if len(actual_rows) > 1 and rating_column_idx >= 0:
        ratings = []
        for row in actual_rows:
            if len(row) > rating_column_idx:
                try:
                    rating_float = float(row[rating_column_idx])
                    ratings.append(rating_float)
                except (ValueError, TypeError):
                    continue
        if len(ratings) > 1:
            unique_ratings = set(ratings)
            has_variety = len(unique_ratings) >= 2
            is_sorted_desc = all((ratings[i] >= ratings[i + 1] for i in range(len(ratings) - 1)))
            is_sorted_asc = all((ratings[i] <= ratings[i + 1] for i in range(len(ratings) - 1)))
            is_organized = is_sorted_desc or is_sorted_asc
            if not is_organized and len(ratings) >= 10:
                consecutive_similar = 0
                for i in range(len(ratings) - 1):
                    if abs(ratings[i] - ratings[i + 1]) <= 0.5:
                        consecutive_similar += 1
                if consecutive_similar / (len(ratings) - 1) > 0.7:
                    is_organized = True
            if has_variety and is_organized:
                score += 0.2
            elif has_variety:
                score += 0.1
    return score

