def check_sales_by_rep__32acaefd505ff4fbca4f947d667569b3(result: Dict[str, float], expected: Dict[str, float], **options) -> float:
    """Check if sales by rep matches expected values.

    Args:
        result: Dict mapping rep names to their calculated sales totals
        expected: Dict with expected sales totals per rep
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    expected_totals = expected.get('rep_totals', {})
    if not expected_totals:
        return 0.0
    total_reps = len(expected_totals)
    if total_reps == 0:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    correct_count = 0
    for (rep, expected_value) in expected_totals.items():
        if rep in result:
            actual_value = result[rep]
            if abs(actual_value - expected_value) <= tolerance:
                correct_count += 1
    return correct_count / total_reps

