def check_restaurant_names_match__75d20d5b(result: Dict[str, List[str]], expected: Dict[str, Any], **options) -> float:
    """Check if restaurant names in XLSX match the source file.

    Args:
        result: Dict with 'xlsx_names' and 'source_names' lists
        expected: Dict with matching criteria (e.g., 'min_matches')
        **options: Additional options (e.g., case_sensitive)

    Returns:
        Score between 0.0 and 1.0
    """
    xlsx_names = result.get('xlsx_names', [])
    source_names = result.get('source_names', [])
    if not source_names:
        return 0.0
    case_sensitive = options.get('case_sensitive', False)
    if not case_sensitive:
        xlsx_normalized = [name.lower() for name in xlsx_names]
        source_normalized = [name.lower() for name in source_names]
    else:
        xlsx_normalized = xlsx_names
        source_normalized = source_names
    matches = 0
    for source_name in source_normalized:
        if source_name in xlsx_normalized:
            matches += 1
    return matches / len(source_names)

