def check_filled_row_count__20778792(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the number of filled rows matches the expected count AND all columns are filled.

    Args:
        result: Dict from getter with 'count', 'all_columns_filled', 'complete_rows', etc.
        expected: Dict with 'count' key for expected number of rows and optional column requirements
        **options: Additional options (e.g., allow_extra for partial credit)

    Returns:
        Score between 0.0 and 1.0
    """
    expected_count = expected.get('count', 0)
    allow_extra = options.get('allow_extra', False)
    actual_count = result.get('count', 0)
    all_columns_filled = result.get('all_columns_filled', False)
    complete_rows = result.get('complete_rows', 0)
    row_count_match = False
    if actual_count == expected_count:
        row_count_match = True
    elif allow_extra and actual_count >= expected_count:
        row_count_match = True
    if row_count_match and all_columns_filled and (complete_rows == expected_count):
        return 1.0
    if not row_count_match:
        row_score = min(1.0, actual_count / expected_count) if expected_count > 0 else 0.0
    else:
        row_score = 1.0
    if not all_columns_filled:
        completeness_score = complete_rows / expected_count if expected_count > 0 else 0.0
        return max(0.0, row_score * 0.5 + completeness_score * 0.5)
    return row_score

