def check_txt_conversion__f5eea4d48349a222e7a85e09c99bbeae(result, expected, **options):
    """
    Check if .doc files were correctly converted to .txt format.

    Args:
        result: Tuple of (command_output, archive_bytes) from getter
        expected: Dictionary with 'command_match' key from config['rules']
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, tuple) or len(result) != 2:
        return 0.0
    (command_output, archive_bytes) = result
    if not isinstance(expected, dict):
        return 0.0
    expected_command = expected.get('command_match', 'catch the desired command')
    score = 0.0
    if isinstance(command_output, str) and expected_command in command_output:
        score += 0.5
    if archive_bytes and len(archive_bytes) > 0:
        try:
            with tarfile.open(fileobj=io.BytesIO(archive_bytes), mode='r:gz') as tar:
                txt_files = [m for m in tar.getmembers() if m.name.endswith('.txt') and m.isfile()]
                if len(txt_files) >= 14:
                    has_content = True
                    for member in txt_files[:3]:
                        f = tar.extractfile(member)
                        if f:
                            content = f.read()
                            if len(content) == 0:
                                has_content = False
                                break
                    if has_content:
                        score += 0.5
                    else:
                        score += 0.3
                elif len(txt_files) > 0:
                    score += 0.3
        except Exception:
            pass
    return score

