def check_docstrings__408a9212(result_file_path, expected, **options):
    """Check if docstrings are correctly extracted from code.

    Args:
        result_file_path: Path to file containing extracted docstrings
        expected: Dict with 'min_docstrings' (int) and 'contains_triple_quotes' (bool)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file_path:
        return 0.0
    try:
        with open(result_file_path, 'r', encoding='utf-8') as f:
            content = f.read()
        min_docstrings = expected.get('min_docstrings', 0)
        contains_triple_quotes = expected.get('contains_triple_quotes', False)
        score = 0.0
        if contains_triple_quotes:
            has_triple_double = '"""' in content
            has_triple_single = "'''" in content
            if not (has_triple_double or has_triple_single):
                return 0.0
        triple_double_count = content.count('"""')
        triple_single_count = content.count("'''")
        docstring_count = triple_double_count // 2 + triple_single_count // 2
        blocks = [block.strip() for block in content.split('\n\n') if block.strip()]
        valid_blocks = 0
        for block in blocks:
            if ('"""' in block or "'''" in block) and len(block) > 10:
                valid_blocks += 1
        effective_count = max(docstring_count, valid_blocks)
        if effective_count >= min_docstrings:
            score += 0.5
        content_valid = False
        has_triple_quotes = '"""' in content or "'''" in content
        lines = content.strip().split('\n')
        has_multiple_lines = len(lines) >= 2
        docstring_patterns = ['\\bArgs:\\b', '\\bReturns:\\b', '\\bParameters:\\b', '\\bRaises:\\b', '\\bExamples:\\b', '\\bNote:\\b', '\\bAttributes:\\b', '\\bYields:\\b']
        has_docstring_keywords = any((re.search(pattern, content, re.IGNORECASE) for pattern in docstring_patterns))
        if has_triple_quotes and has_multiple_lines and (len(content.strip()) > 20):
            content_valid = True
        if has_triple_quotes and has_docstring_keywords:
            content_valid = True
        if has_triple_quotes and effective_count >= min_docstrings and (len(content.strip()) > 30):
            content_valid = True
        if content_valid:
            score += 0.5
        return min(score, 1.0)
    except Exception as e:
        print(f'Error checking docstrings: {e}')
        return 0.0

def check_brightness_decreased__2f4c8c94976cda4c41de6383a6a66dec(result, expected, **options):
    """
    Check if image brightness is lower than the original.

    Args:
        result: Dict with 'brightness' from getter (current image)
        expected: Dict with 'original_brightness' value to compare against

    Returns:
        float: 1.0 if brightness decreased, 0.5 if same, 0.0 if increased
    """
    if result is None:
        logger.error('Result is None')
        return 0.0
    original_brightness = expected.get('original_brightness')
    if original_brightness is None:
        logger.error('Expected original_brightness not specified')
        return 0.0
    result_brightness = result.get('brightness')
    if result_brightness is None:
        logger.error('Result brightness is None')
        return 0.0
    logger.info(f'Brightness: {result_brightness} vs original {original_brightness}')
    tolerance = options.get('tolerance', 5.0)
    if result_brightness < original_brightness - tolerance:
        return 1.0
    elif abs(result_brightness - original_brightness) <= tolerance:
        return 0.5
    else:
        return 0.0

def check_all_present__b0201acf(result: Dict[str, Any], expected: Any, **options) -> float:
    """
    Check if all required texts are present and content is comprehensive.

    Verifies:
    1. All specified texts are present in the document
    2. Word count is substantial (>= 50 words for comprehensive extraction)
    3. Character count is substantial (>= 250 chars for meaningful content)

    Args:
        result: Dict with 'text_presence', 'char_count', and 'word_count'
        expected: Dict with 'all_required' flag
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if not result or not isinstance(result, dict):
        logger.error('Invalid result format')
        return 0.0
    text_presence = result.get('text_presence', [])
    char_count = result.get('char_count', 0)
    word_count = result.get('word_count', 0)
    if not text_presence:
        logger.error('No text presence data')
        return 0.0
    all_present = all(text_presence)
    present_count = sum(text_presence)
    word_count_sufficient = word_count >= 50
    char_count_sufficient = char_count >= 250
    logger.info(f'{present_count}/{len(text_presence)} required texts present, {word_count} words (>= 50: {word_count_sufficient}), {char_count} chars (>= 250: {char_count_sufficient})')
    if all_present and word_count_sufficient and char_count_sufficient:
        return 1.0
    if all_present:
        logger.warning('All texts present but content not comprehensive enough')
        return 0.5
    return 0.0

def check_total_column__3ec2bf07088f1f4956f72735bf4f2f86(result, expected, **options):
    """Check that Total Crops column exists with correct calculations for all Gotheye market rows.

    Args:
        result: Dict with column data including all Gotheye rows
        expected: Dict with 'expected_value' for first row total (for backward compatibility)
        **options: Additional options including 'tolerance'

    Returns:
        float: Score between 0.0 and 1.0 with partial credit
    """
    if not isinstance(result, dict):
        return 0.0
    score = 0.0
    if not result.get('exists', False):
        return 0.0
    score += 0.2
    header = result.get('header', '')
    if header and isinstance(header, str) and ('total' in header.lower()):
        score += 0.2
    gotheye_rows = result.get('gotheye_rows', [])
    if not gotheye_rows:
        return score
    tolerance = options.get('tolerance', 0.5)
    has_formula = False
    for row_data in gotheye_rows:
        formula = row_data.get('total_formula', '')
        if formula and isinstance(formula, str) and formula.startswith('='):
            has_formula = True
            break
    if has_formula:
        score += 0.2
    total_rows = len(gotheye_rows)
    correct_rows = 0
    for row_data in gotheye_rows:
        total_value = row_data.get('total_value')
        expected_sum = row_data.get('expected_sum')
        if total_value is not None and expected_sum is not None:
            try:
                total_float = float(total_value)
                expected_float = float(expected_sum)
                if abs(total_float - expected_float) <= tolerance:
                    correct_rows += 1
            except (ValueError, TypeError):
                pass
    if total_rows > 0:
        correctness_ratio = correct_rows / total_rows
        score += 0.4 * correctness_ratio
    return min(score, 1.0)

