def check_invoice_quantity_sum__3ae73d48883e179c149bcb7c19ff6986(result, expected, **options):
    """Verify complete invoice data extraction with all required fields.

    Args:
        result: Invoice data dict from getter (with headers, items, item_count, quantity_sum)
        expected: Expected values (from rules dict)
        **options: Additional comparison options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None:
        return 0.0
    expected_sum = expected.get('quantity_sum', 0)
    if result.get('quantity_sum') != expected_sum:
        return 0.0
    headers = result.get('headers', [])
    if len(headers) < 2:
        return 0.0
    items = result.get('items', [])
    if len(items) == 0:
        return 0.0
    for item in items:
        if not item.get('item_name'):
            return 0.0
        if item.get('quantity') is None:
            return 0.0
    item_count = result.get('item_count', 0)
    if item_count < 2:
        return 0.0
    return 1.0

