def check_note_not_empty__be6ff3d08942861835ef265a21d9b63a(result_state, expected_state, **options):
    """
    Check if the note meets the required criteria.

    The scoring is progressive:
    - 0.5: Note is not empty (has any text)
    - 0.75: Note has at least 20 characters
    - 1.0: Note contains all required keywords

    Args:
        result_state: The note text from the getter (str)
        expected_state: Expected rules dict with:
            - min_length: Minimum length for the note (default: 20)
            - keywords: List of keywords that should be in the note
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result_state is None:
        result_state = ''
    note_text = str(result_state).strip()
    min_length = expected_state.get('min_length', 20) if isinstance(expected_state, dict) else 20
    keywords = expected_state.get('keywords', []) if isinstance(expected_state, dict) else []
    if not note_text:
        logger.info('Note is empty, score: 0.0')
        return 0.0
    score = 0.5
    logger.info(f'Note has text (length: {len(note_text)}), score: 0.5')
    if len(note_text) >= min_length:
        score = 0.75
        logger.info(f'Note has {len(note_text)} characters (>= {min_length}), score: 0.75')
    else:
        logger.info(f'Note has only {len(note_text)} characters (< {min_length}), score remains: 0.5')
        return score
    if keywords:
        note_lower = note_text.lower()
        missing_keywords = []
        found_keywords = []
        for keyword in keywords:
            if keyword.lower() in note_lower:
                found_keywords.append(keyword)
            else:
                missing_keywords.append(keyword)
        if not missing_keywords:
            score = 1.0
            logger.info(f'Note contains all keywords {keywords}, score: 1.0')
        else:
            logger.info(f'Note missing keywords {missing_keywords} (found: {found_keywords}), score remains: 0.75')
    else:
        score = 1.0
        logger.info('No keywords required, score: 1.0')
    return score

def check_recreation_zion_result__03a5b0d3(result: Dict[str, Any], rules: Dict[str, Any], **options) -> float:
    """
    Check recreation.gov Zion search results.

    Validates that:
    1. The search term "Zion" was verified on the page
    2. At least the minimum number of availability dates were found

    Args:
        result: Dict from getter containing:
            - expected.search_term_verified: bool indicating if Zion was found
            - expected.availability_dates: list of date strings
        rules: Dict containing:
            - search_term_verified: expected bool value (should be true)
            - min_dates: minimum number of dates required

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    logger.info(f'[CHECK_RECREATION_ZION] Checking result: {result}')
    logger.info(f'[CHECK_RECREATION_ZION] Rules: {rules}')
    if result is None:
        logger.warning('[CHECK_RECREATION_ZION] Result is None')
        return 0.0
    if 'expected' not in result:
        logger.warning("[CHECK_RECREATION_ZION] No 'expected' key in result")
        return 0.0
    expected = result['expected']
    if expected.get('error') == '__EVALUATION_FAILED__':
        logger.error('[CHECK_RECREATION_ZION] Evaluation failed')
        return 0.0
    search_term_verified = expected.get('search_term_verified', False)
    expected_verified = rules.get('search_term_verified', True)
    if search_term_verified != expected_verified:
        logger.warning(f'[CHECK_RECREATION_ZION] Search term verification failed: expected={expected_verified}, actual={search_term_verified}')
        return 0.0
    logger.info(f'[CHECK_RECREATION_ZION] Search term verification passed: {search_term_verified}')
    availability_dates = expected.get('availability_dates', [])
    min_dates = rules.get('min_dates', 1)
    if not isinstance(availability_dates, list):
        logger.warning(f'[CHECK_RECREATION_ZION] availability_dates is not a list: {type(availability_dates)}')
        return 0.0
    if len(availability_dates) < min_dates:
        logger.warning(f'[CHECK_RECREATION_ZION] Insufficient dates found: expected at least {min_dates}, got {len(availability_dates)}')
        return 0.0
    logger.info(f'[CHECK_RECREATION_ZION] Date check passed: found {len(availability_dates)} dates (minimum required: {min_dates})')
    logger.info(f'[CHECK_RECREATION_ZION] Dates: {availability_dates}')
    logger.info('[CHECK_RECREATION_ZION] All checks passed')
    return 1.0

def check_restaurant_names__4139e133(result, expected, **options):
    """Check if all expected restaurant names are filled in.

    Args:
        result: List of restaurant names extracted from Excel
        expected: Dict with 'expected_names' key containing list of expected names
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, list):
        return 0.0
    expected_names = expected.get('expected_names', [])
    if not expected_names:
        return 0.0
    result_normalized = [name.lower().strip() for name in result if name]
    expected_normalized = [name.lower().strip() for name in expected_names]
    matches = 0
    for exp_name in expected_normalized:
        if exp_name in result_normalized:
            matches += 1
    return matches / len(expected_normalized)

