def check_all_complete__9b7afbb9(result, expected, **options):
    """Check if all entries have complete information and meet semantic requirements.

    Args:
        result: Dict with completeness info from getter
        expected: Rules dict (when type="rule")
        **options: Additional options

    Returns:
        float: 1.0 if all requirements met, partial score otherwise
    """
    total_rows = result.get('total_rows', 0)
    complete_rows = result.get('complete_rows', 0)
    rows_with_arxiv = result.get('rows_with_arxiv', 0)
    rows_with_correct_date = result.get('rows_with_correct_date', 0)
    rows_with_topic = result.get('rows_with_topic', 0)
    rows_with_all_valid = result.get('rows_with_all_valid', 0)
    if total_rows == 0:
        return 0.0
    rules = expected if isinstance(expected, dict) else {}
    require_complete = rules.get('require_complete', True)
    require_arxiv = rules.get('require_arxiv', True)
    require_correct_date = rules.get('require_correct_date', True)
    require_topic = rules.get('require_topic', True)
    if require_complete and require_arxiv and require_correct_date and require_topic:
        if rows_with_all_valid == total_rows:
            return 1.0
        return rows_with_all_valid / total_rows
    if require_complete and require_arxiv and require_correct_date and (not require_topic):
        valid_count = 0
        if complete_rows == total_rows and rows_with_arxiv == total_rows and (rows_with_correct_date == total_rows):
            return 1.0
        completeness_score = complete_rows / total_rows
        arxiv_score = rows_with_arxiv / total_rows
        date_score = rows_with_correct_date / total_rows
        return (completeness_score + arxiv_score + date_score) / 3
    if require_complete and (not require_arxiv) and (not require_correct_date) and (not require_topic):
        if complete_rows == total_rows:
            return 1.0
        return complete_rows / total_rows
    if require_complete and require_arxiv and (not require_correct_date) and (not require_topic):
        if complete_rows == total_rows and rows_with_arxiv == total_rows:
            return 1.0
        completeness_score = complete_rows / total_rows
        arxiv_score = rows_with_arxiv / total_rows
        return (completeness_score + arxiv_score) / 2
    if require_complete and require_correct_date and (not require_arxiv) and (not require_topic):
        if complete_rows == total_rows and rows_with_correct_date == total_rows:
            return 1.0
        completeness_score = complete_rows / total_rows
        date_score = rows_with_correct_date / total_rows
        return (completeness_score + date_score) / 2
    if require_complete and require_topic and (not require_arxiv) and (not require_correct_date):
        if complete_rows == total_rows and rows_with_topic == total_rows:
            return 1.0
        completeness_score = complete_rows / total_rows
        topic_score = rows_with_topic / total_rows
        return (completeness_score + topic_score) / 2
    return rows_with_all_valid / total_rows

