def check_order__b8aa5550(result, expected, **options):
    """Check if values appear in correct order in text.
    
    Args:
        result: Text content from file
        expected: Dict with 'first_value' and 'last_value' keys
        
    Returns:
        float: 1.0 if first_value appears before last_value, else 0.0
    """
    if result is None:
        return 0.0
    first_val = str(expected.get('first_value', ''))
    last_val = str(expected.get('last_value', ''))
    first_pos = result.find(first_val)
