def check_word_count__ae24f181(result, expected, **options):
    """Check if word count matches expected value.

    Args:
        result: Word count from getter (int)
        expected: Expected word count (int or dict with 'count' key)
        **options: Additional options (min_match: float threshold, default 0.95)

    Returns:
        float: 1.0 if exact match or within threshold, 0.0 otherwise
    """
    if isinstance(expected, dict):
        expected_count = expected.get('count', 0)
    else:
        expected_count = expected
    min_match = options.get('min_match', 0.95)
    if result == expected_count:
        return 1.0
    if expected_count > 0:
        ratio = result / expected_count
        if ratio >= min_match:
            return 1.0
    return 0.0

def verify_selective_plugin_installation(result_state: Dict[str, Any], expected_state: Dict[str, Any], **options) -> float:
    """
    Verify that:
    1. Required extensions (developer tools and productivity) are installed (positive verification)
    2. Excluded extensions (video conferencing and language tools) are NOT installed (negative verification)

    This addresses the LLM judge concerns:
    - Dynamically determines expected extensions from document content
    - Verifies both installation (positive) and exclusion (negative) requirements
    - Handles semantic ambiguity by categorizing based on actual document structure

    Args:
        result_state: Dict containing:
            - expected: Dict with categorized extension lists from document
                - developer_tools: List[str]
                - productivity: List[str]
                - video_conferencing: List[str]
                - language_tools: List[str]
            - installed: List[str] - Actually installed extension names

        expected_state: Dict containing configuration (can be empty, we use document data)

        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
            - 1.0: All required extensions installed, no excluded extensions installed
            - 0.5-0.99: Partial success
            - 0.0: Failed verification
    """
    if not result_state:
        logger.error('[VERIFY_PLUGIN] No result state provided')
        return 0.0
    expected = result_state.get('expected', {})
    installed = result_state.get('installed', [])
    if not expected:
        logger.error('[VERIFY_PLUGIN] No expected data from document')
        return 0.0
    logger.info('[VERIFY_PLUGIN] Starting verification')
    logger.info(f'[VERIFY_PLUGIN] Installed extensions: {installed}')
    developer_tools = expected.get('developer_tools', [])
    productivity = expected.get('productivity', [])
    video_conferencing = expected.get('video_conferencing', [])
    language_tools = expected.get('language_tools', [])
    logger.info(f'[VERIFY_PLUGIN] Required - Developer tools: {developer_tools}')
    logger.info(f'[VERIFY_PLUGIN] Required - Productivity: {productivity}')
    logger.info(f'[VERIFY_PLUGIN] Excluded - Video conferencing: {video_conferencing}')
    logger.info(f'[VERIFY_PLUGIN] Excluded - Language tools: {language_tools}')
    required_extensions = developer_tools + productivity
    excluded_extensions = video_conferencing + language_tools
    if not required_extensions:
        logger.error('[VERIFY_PLUGIN] No required extensions found in document')
        return 0.0
    installed_lower = {name.lower() for name in installed}
    required_installed = []
    required_missing = []
    for required in required_extensions:
        if required.lower() in installed_lower:
            required_installed.append(required)
            logger.info(f'[VERIFY_PLUGIN] ✓ Required extension installed: {required}')
        else:
            required_missing.append(required)
            logger.warning(f'[VERIFY_PLUGIN] ✗ Required extension MISSING: {required}')
    excluded_found = []
    excluded_correctly_skipped = []
    for excluded in excluded_extensions:
        if excluded.lower() in installed_lower:
            excluded_found.append(excluded)
            logger.warning(f'[VERIFY_PLUGIN] ✗ Excluded extension INCORRECTLY INSTALLED: {excluded}')
        else:
            excluded_correctly_skipped.append(excluded)
            logger.info(f'[VERIFY_PLUGIN] ✓ Excluded extension correctly skipped: {excluded}')
    total_required = len(required_extensions)
    total_excluded = len(excluded_extensions)
    if total_required == 0:
        logger.error('[VERIFY_PLUGIN] No required extensions to verify')
        return 0.0
    positive_score = len(required_installed) / total_required
    if total_excluded > 0:
        negative_score = len(excluded_correctly_skipped) / total_excluded
    else:
        negative_score = 1.0
    combined_score = (positive_score + negative_score) / 2.0
    logger.info(f'[VERIFY_PLUGIN] === VERIFICATION RESULTS ===')
    logger.info(f'[VERIFY_PLUGIN] Required extensions: {len(required_installed)}/{total_required} installed')
    logger.info(f'[VERIFY_PLUGIN] Excluded extensions: {len(excluded_correctly_skipped)}/{total_excluded} correctly skipped')
    logger.info(f'[VERIFY_PLUGIN] Positive score: {positive_score:.2f}')
    logger.info(f'[VERIFY_PLUGIN] Negative score: {negative_score:.2f}')
    logger.info(f'[VERIFY_PLUGIN] Combined score: {combined_score:.2f}')
    if required_missing:
        logger.warning(f'[VERIFY_PLUGIN] Missing required extensions: {required_missing}')
    if excluded_found:
        logger.warning(f'[VERIFY_PLUGIN] Incorrectly installed excluded extensions: {excluded_found}')
    if combined_score >= 1.0:
        logger.info('[VERIFY_PLUGIN] ✓ VERIFICATION PASSED: All requirements met')
    else:
        logger.warning('[VERIFY_PLUGIN] ✗ VERIFICATION FAILED: Some requirements not met')
    return combined_score

def check_row_values__6c7293c6(result: List[Any], expected: Dict[str, Any], **options) -> float:
    """Check if row values match expected values.

    Args:
        result: List of cell values from getter
        expected: Dict with 'values' (list of expected values)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    expected_values = expected.get('values', [])
    if not result or not expected_values:
        return 0.0
    if len(result) != len(expected_values):
        return 0.0
    matches = 0
    for (r, e) in zip(result, expected_values):
        r_str = str(r) if r is not None else ''
        e_str = str(e) if e is not None else ''
        if r_str == e_str:
            matches += 1
    return matches / len(expected_values)

def check_sorted_descending__61bebdcf(result: List[Any], expected: Any, **options) -> float:
    """Check if a list of values is sorted in descending order.

    Args:
        result: List of values from getter
        expected: Dict with 'rules' (not used, just for structure compatibility)
        **options: Additional options

    Returns:
        1.0 if sorted descending, partial score based on sortedness
    """
    if not result or len(result) < 2:
        return 0.0
    numeric_values = []
    for val in result:
        if val is not None:
            try:
                numeric_values.append(float(val))
            except (ValueError, TypeError):
                pass
    if len(numeric_values) < 2:
        return 0.0
    inversions = 0
    comparisons = 0
    for i in range(len(numeric_values) - 1):
        if numeric_values[i] < numeric_values[i + 1]:
            inversions += 1
        comparisons += 1
    if inversions == 0:
        return 1.0
    else:
        sortedness = 1.0 - inversions / comparisons
        return max(0.0, sortedness)

def check_grammar_test_answers__43a335d91c51ff36a8389c8dbf9afa4e(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if grammar test answers match expected values.

    Args:
        result: Dict of test sections and their answers from getter
        expected: Dict with 'test_sections' key containing expected test:answer pairs
        **options: Additional options (e.g., 'ignore_case', 'ignore_spaces')

    Returns:
        float: Score between 0.0 and 1.0 based on partial credit
    """
    ignore_case = options.get('ignore_case', True)
    ignore_spaces = options.get('ignore_spaces', True)
    expected_sections = expected.get('test_sections', {})
    if not expected_sections:
        logger.error('No expected test sections provided')
        return 0.0
    score = 0.0
    total_tests = len(expected_sections)
    for (test_name, expected_answer) in expected_sections.items():
        if test_name not in result:
            logger.warning(f"Test section '{test_name}' not found in result")
            continue
        result_answer = result[test_name]
        if ignore_case:
            result_answer = result_answer.lower()
            expected_answer = expected_answer.lower()
        if ignore_spaces:
            result_answer = result_answer.replace(' ', '').replace('\t', '')
            expected_answer = expected_answer.replace(' ', '').replace('\t', '')
        if result_answer == expected_answer:
            score += 1.0 / total_tests
            logger.info(f"✓ Test section '{test_name}' matches: {result[test_name]}")
        else:
            logger.warning(f"✗ Test section '{test_name}' mismatch:")
            logger.warning(f'  Expected: {expected_answer}')
            logger.warning(f'  Got: {result_answer}')
    return score

def check_row_range__1fd6bc02(result, expected, **options):
    """Check if new rows were added and meet content requirements.

    Args:
        result: Dict from getter with 'new_rows_count', 'total_rows', and 'rows'
        expected: Rules dict with 'min_rows', 'max_rows', and optional content validation
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    min_rows = expected.get('min_rows', 0)
    max_rows = expected.get('max_rows', float('inf'))
    if isinstance(result, dict):
        new_rows_count = result.get('new_rows_count', 0)
        total_rows = result.get('total_rows', 0)
        rows = result.get('rows', [])
        baseline_rows = result.get('baseline_rows', 0)
    else:
        new_rows_count = result
        total_rows = result
        rows = []
        baseline_rows = 0
    if not min_rows <= new_rows_count <= max_rows:
        return 0.0
    if new_rows_count > 0 and rows:
        new_rows = rows[baseline_rows:] if baseline_rows < len(rows) else []
        if len(new_rows) < min_rows:
            return 0.0
        valid_papers = 0
        for row_data in new_rows:
            row_text = ' '.join(row_data.get('values', [])).lower()
            has_date = bool(re.search('(october\\s+11|oct\\s+11|10[/-]11|11\\s+oct)', row_text, re.IGNORECASE))
            has_2023 = '2023' in row_text
            has_arxiv = 'arxiv' in row_text
            lm_keywords = ['language model', 'llm', 'gpt', 'bert', 'transformer', 'nlp', 'natural language']
            has_lm_topic = any((keyword in row_text for keyword in lm_keywords))
            if (has_arxiv or (has_date and has_2023)) and has_lm_topic:
                valid_papers += 1
        if valid_papers < min_rows:
            return 0.0
    return 1.0

def check_doi_added__9c8bbac2(result, expected, **options):
    """Check if DOI was added to specific reference.

    Args:
        result: Path to the result DOCX file
        expected: Dict with 'author', 'year', 'doi' keys

    Returns:
        float: 1.0 if DOI found in reference, 0.0 otherwise
    """
