def check_word_replacement__375458ac(result, expected, **options):
    """Check if specific word was replaced in text.

    Args:
        result: Actual paragraph text from getter
        expected: Expected configuration with old_word, new_word (from rules dict)
        **options: Additional options

    Returns:
        1.0 if word replacement successful, 0.0 otherwise
    """
    old_word = expected.get('old_word', '')
    new_word = expected.get('new_word', '')
    if result is None:
        return 0.0
    old_word_pattern = '\\b' + re.escape(old_word) + '\\b'
    new_word_pattern = '\\b' + re.escape(new_word) + '\\b'
    has_new_word = re.search(new_word_pattern, result, re.IGNORECASE) is not None
    has_old_word = re.search(old_word_pattern, result, re.IGNORECASE) is not None
    if has_new_word and (not has_old_word):
        return 1.0
    return 0.0

def check_acl_papers__3467ffef(result: List[Dict[str, Any]], expected: Any, **options) -> float:
    """
    Check if ACL papers data is valid and complete.

    Args:
        result: List of paper dicts from getter
        expected: Expected configuration dict with:
            - exact_count: Expected number of papers (default: 4)
            - year_range: Valid year range [min, max] (default: [2019, 2022])

    Returns:
        Score between 0.0 and 1.0
    """
    if isinstance(expected, dict):
        exact_count = expected.get('exact_count', 4)
        year_range = expected.get('year_range', [2019, 2022])
    else:
        exact_count = 4
        year_range = [2019, 2022]
    if len(result) != exact_count:
        return 0.0
    for (idx, paper) in enumerate(result):
        title = paper.get('title', '').strip()
        year = paper.get('year', '').strip()
        authors = paper.get('authors', '').strip()
        pdf_link = paper.get('pdf_link', '').strip()
        if not title or not year or (not authors) or (not pdf_link):
            return 0.0
        try:
            year_int = int(year)
            if year_int < year_range[0] or year_int > year_range[1]:
                return 0.0
        except (ValueError, TypeError):
            return 0.0
        if 'aclanthology.org' not in pdf_link.lower():
            return 0.0
        if ',' not in authors and len(authors.split()) < 2:
            return 0.0
    return 1.0

def check_spacing__16ba0b83959e280f878d10718f9a129f(result, expected, **options):
    """Check if line spacing and font size match expected values.

    Args:
        result: Dictionary with 'spacing' and 'font_sizes' keys containing paragraph data
        expected: Dictionary with expected spacing and font sizes for each paragraph (from rules)
        **options: Additional comparison options

    Returns:
        float: 1.0 if all spacing and font sizes match, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    expected_spacings = expected.get('paragraph_spacings', {})
    expected_font_sizes = expected.get('paragraph_font_sizes', {})
    actual_spacings = result.get('spacing', {})
    actual_font_sizes = result.get('font_sizes', {})
    for (para_idx, expected_spacing) in expected_spacings.items():
        para_idx_int = int(para_idx)
        actual_spacing = actual_spacings.get(para_idx_int)
        if actual_spacing is None:
            return 0.0
        if abs(actual_spacing - expected_spacing) > 0.01:
            return 0.0
    for (para_idx, expected_font_size) in expected_font_sizes.items():
        para_idx_int = int(para_idx)
        actual_font_size = actual_font_sizes.get(para_idx_int)
        if actual_font_size is None:
            return 0.0
        if abs(actual_font_size - expected_font_size) > 0.01:
            return 0.0
    return 1.0

def check_initials__e71d60e6(result: Dict, expected: Dict, **opts) -> float:
    s = 0.0
    en = expected.get('expected_names', [])
    rn = result.get('names', [])
    ei = expected.get('expected_initials', [])
    ri = result.get('initials', [])
    if len(rn) == len(en):
        s += 0.4 * sum((1 for i in range(len(en)) if i < len(rn) and rn[i].lower().strip() == en[i].lower().strip())) / len(en)
    if len(ri) == len(ei):
        s += 0.6 * sum((1 for i in range(len(ei)) if i < len(ri) and ri[i].upper() == ei[i].upper())) / len(ei)
