def check_autosave_and_backup__743b0091(config_file, rules):
    """Check if both auto-save and backup copy are enabled.

    Args:
        config_file: Path to registrymodifications.xcu file
        rules: Dict with "autosave_enabled" and "backup_enabled" keys

    Returns:
        1.0 if both settings match expected, 0.5 if one matches, 0.0 if neither
    """
    expected_autosave = rules['autosave_enabled']
    expected_backup = rules['backup_enabled']
    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
        autosave_enabled = None
        backup_enabled = None
        for item in root.findall('.//item'):
            path = item.get('{http://openoffice.org/2001/registry}path')
            if path == '/org.openoffice.Office.Common/Save/Document':
                for prop in item.findall('.//prop'):
                    name = prop.get('{http://openoffice.org/2001/registry}name')
                    value_elem = prop.find('.//value')
                    if name == 'AutoSave' and value_elem is not None:
                        autosave_enabled = value_elem.text.lower() == 'true'
                    elif name == 'CreateBackup' and value_elem is not None:
                        backup_enabled = value_elem.text.lower() == 'true'
        score = 0.0
        if autosave_enabled == expected_autosave:
            score += 0.5
        if backup_enabled == expected_backup:
            score += 0.5
        return score
    except (ET.ParseError, FileNotFoundError) as e:
        logger.error(f'Error checking autosave and backup settings: {e}')
        return 0.0

def check_mbox_backup__1701225e2d2da95122de9fd6941c3c6f(result, expected, **options):
    """Check if mbox backup contains expected emails.

    Args:
        result: List of email subjects extracted from mbox file
        expected: Dict with 'min_emails' and 'expected_subjects' keys
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass)
    """
    if not result:
        return 0.0
    min_emails = expected.get('min_emails', 1)
    expected_subjects = expected.get('expected_subjects', [])
    if len(result) < min_emails:
        return 0.0
    score = 0.0
    for exp_subj in expected_subjects:
        for res_subj in result:
            if exp_subj in res_subj or res_subj in exp_subj:
                score += 1.0 / len(expected_subjects)
                break
    return min(1.0, score)

