def check_filtered_rows__e6dd308b0cb59f24a41ac5c58e5e6ff5(result, expected, **options):
    """Check if DOCX table contains filtered rows meeting criteria.

    Args:
        result: Table data as list of lists from getter
        expected: Dict with 'min_first_col_value' and 'expected_quantities'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, list):
        return 0.0
    min_value = expected.get('min_first_col_value', 0)
    expected_quantities = expected.get('expected_quantities', [])
    first_col_values = []
    for row in result:
        if len(row) > 0:
            try:
                val = row[0]
                if isinstance(val, str):
                    try:
                        val = int(val)
                    except ValueError:
                        continue
                first_col_values.append(val)
            except (ValueError, TypeError):
                pass
    if not first_col_values:
        return 0.0
    all_meet_threshold = all((v >= min_value for v in first_col_values))
    if not all_meet_threshold:
        return 0.0
    score = 0.5
    if expected_quantities:
        matches = sum((1 for v in first_col_values if v in expected_quantities))
        if matches == len(expected_quantities) and len(first_col_values) == len(expected_quantities):
            score = 1.0
        elif matches >= len(expected_quantities) * 0.8:
            score = 0.8
        else:
            score = 0.5
    return score

