def check_readme_section__6ee0182d(actual: str, rules: dict, **options) -> float:
    """
    Check if README.md contains a specific section.

    Args:
        actual (str): path to README.md file
        rules (dict): expected configuration rules with section_name

    Returns:
        float: score between 0.0 and 1.0
    """
    if not actual:
        return 0.0
    try:
        with open(actual, 'r') as f:
            content = f.read()
    except Exception as e:
        logger.error(f'Failed to read README.md: {e}')
        return 0.0
    section_name = rules.get('section_name', 'Getting Started')
    score = 0.0
    import re
    atx_pattern = re.compile('^#{1,6}\\s+' + re.escape(section_name), re.MULTILINE | re.IGNORECASE)
    setext_pattern = re.compile('^' + re.escape(section_name) + '\\s*\\n[=\\-]+', re.MULTILINE | re.IGNORECASE)
    if atx_pattern.search(content) or setext_pattern.search(content):
        score = 1.0
    return score

