def check_concat_values__834eee89(result, expected, **options):
    """Check if concatenated values match expected strings and formulas are used.

    Args:
        result: Dict with 'values' and 'formulas' lists
        expected: Dict with 'values' list to match
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('values', [])
    if not isinstance(result, dict):
        return 0.0
    actual_values = result.get('values', [])
    actual_formulas = result.get('formulas', [])
    if len(actual_values) != len(expected_values):
        return 0.0
    if len(actual_values) < 4:
        return 0.0
    total_score = 0.0
    max_score = len(expected_values)
    for (i, (actual, exp)) in enumerate(zip(actual_values, expected_values)):
        if i == 0:
            if actual == exp or (isinstance(actual, str) and isinstance(exp, str) and (actual.strip() == exp.strip())):
                total_score += 1.0
        else:
            formula = actual_formulas[i] if i < len(actual_formulas) else None
            value_matches = False
            if actual == exp:
                value_matches = True
            elif isinstance(actual, str) and isinstance(exp, str):
                if actual.strip() == exp.strip():
                    value_matches = True
            has_formula = False
            if formula and isinstance(formula, str):
                formula_upper = formula.upper()
                if 'CONCATENATE' in formula_upper or '&' in formula:
                    has_formula = True
            if value_matches and has_formula:
                total_score += 1.0
            elif value_matches:
                total_score += 0.5
    return total_score / max_score if max_score > 0 else 0.0

