def check_snake_speed_variable__09ff2d15(vm_file_result: List[Optional[str]], rules: Dict, **options) -> float:
    """
    Check if the FPS variable in settings.py is set to the expected value.

    This function parses the Python code using AST to find variable assignments
    and checks if the FPS variable matches the expected value.

    Args:
        vm_file_result (List[Optional[str]]): List of file paths returned by get_vm_file with multi=true
                                               Order matches dest array: ['food.py', 'main.py', 'settings.py', 'snake.py']
        rules (Dict): Dictionary containing expected values
                      Expected key: 'fps_value' with the expected FPS value
        **options: Additional options (unused)

    Returns:
        float: 1.0 if FPS variable matches expected value, 0.0 otherwise
    """
    expected_fps = rules.get('fps_value')
    if expected_fps is None:
        return 0.0
    dest_names = ['food.py', 'main.py', 'settings.py', 'snake.py']
    if not vm_file_result or len(vm_file_result) < len(dest_names):
        return 0.0
    file_dict = dict(zip(dest_names, vm_file_result))
    settings_file_path = file_dict.get('settings.py')
    if not settings_file_path:
        return 0.0
    if not os.path.exists(settings_file_path):
        return 0.0
    try:
        with open(settings_file_path, 'r') as f:
            source_code = f.read()
        tree = ast.parse(source_code)
        for node in ast.walk(tree):
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name):
                        if target.id == 'FPS':
                            if isinstance(node.value, ast.Constant):
                                actual_fps = node.value.value
                                if actual_fps == expected_fps:
                                    return 1.0
                            elif isinstance(node.value, ast.Num):
                                actual_fps = node.value.n
                                if actual_fps == expected_fps:
                                    return 1.0
        return 0.0
    except SyntaxError:
        return 0.0
    except Exception:
        return 0.0

