def check_type_hints_added__5df57914(result_content, expected, **options):
    """Check if type hints were added to a function.

    Args:
        result_content: String (full file content)
        expected: Dict with 'function_name', 'has_param_hints', 'has_return_hint'

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_content:
        return 0.0
    function_name = expected.get('function_name', 'bubble_sort')
    has_param_hints = expected.get('has_param_hints', True)
    has_return_hint = expected.get('has_return_hint', False)
    import re
    func_pattern = 'def\\s+' + re.escape(function_name) + '\\s*\\([^)]*\\)[^:]*:'
    match = re.search(func_pattern, result_content)
    if not match:
        return 0.0
    func_def = match.group(0)
    score = 0.0
    param_match = re.search('\\(([^)]*)\\)', func_def)
    if not param_match:
        return 0.0
    param_part = param_match.group(1)
    has_colon_in_params = ':' in param_part
    if has_param_hints:
        if has_colon_in_params:
            score += 0.5
    elif not has_colon_in_params:
        score += 0.5
    has_return_arrow = '->' in func_def
    if has_return_hint:
        if has_return_arrow:
            score += 0.5
    else:
        score += 0.5
    return score

def check_sort_and_chart__4ca9a538(result_state: Dict[str, Any], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if data is sorted correctly and a bar chart is created with correct axes.

    This metric verifies two aspects:
    1. Sorting: Checks if the column values are sorted in the expected order (50% weight)
    2. Chart: Checks if a bar chart of the expected type exists with correct axis mappings (50% weight)
       - Chart type verification (25% weight)
       - Axis mapping verification (25% weight): Product names on X-axis, Quantity on Y-axis

    Args:
        result_state: Dict from getter with keys:
            - column_values (list): Values from the column to check (Quantity)
            - product_names (list): Product names from column 2
            - charts (list): List of chart info dicts with:
                - type (str): Chart class name
                - series_data (dict): Data series information with x_column, y_column, x_values, y_values
        expected_state: Rules dict directly (when type='rule') containing:
            - order (str): 'asc' or 'desc' for sorting order
            - chart_type (str): Expected chart type (e.g., 'BarChart')
            - x_column (int, optional): Expected X-axis column (1-based), defaults to 2 for Product
            - y_column (int, optional): Expected Y-axis column (1-based), defaults to 6 for Quantity
        **options: Additional options (not used currently)

    Returns:
        float: Score between 0.0 and 1.0
            - 0.5 for correct sorting
            - 0.25 for correct chart type
            - 0.25 for correct axis mappings
            - Total: 1.0 for all correct
    """
    if not result_state or not expected_state:
        return 0.0
    expected_order = expected_state.get('order', 'desc')
    expected_chart_type = expected_state.get('chart_type', 'BarChart')
    expected_x_column = expected_state.get('x_column', 2)
    expected_y_column = expected_state.get('y_column', 6)
    column_values = result_state.get('column_values', [])
    charts = result_state.get('charts', [])
    score = 0.0
    if len(column_values) >= 2:
        is_sorted_desc = all((column_values[i] >= column_values[i + 1] for i in range(len(column_values) - 1)))
        is_sorted_asc = all((column_values[i] <= column_values[i + 1] for i in range(len(column_values) - 1)))
        if expected_order.lower() == 'desc' and is_sorted_desc:
            score += 0.5
        elif expected_order.lower() == 'asc' and is_sorted_asc:
            score += 0.5
    expected_chart_lower = expected_chart_type.lower()
    chart_found = False
    axis_mapping_correct = False
    for chart_info in charts:
        chart_type = chart_info.get('type', '')
        if chart_type.lower() == expected_chart_lower:
            chart_found = True
            series_data = chart_info.get('series_data', {})
            x_column = series_data.get('x_column')
            y_column = series_data.get('y_column')
            if x_column == expected_x_column and y_column == expected_y_column:
                axis_mapping_correct = True
                break
    if chart_found:
        score += 0.25
    if axis_mapping_correct:
        score += 0.25
    return score

def check_rtf_conversion__f393332492ba7a6a3c15ae872f7e3aae(result, expected, **options):
    """
    Check if .doc files were correctly converted to .rtf format.

    Args:
        result: Tuple of (command_output, actual_command, archive_bytes) from getter
        expected: Rules dictionary directly (when type='rule', framework returns config['rules'])
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, tuple) or len(result) != 3:
        return 0.0
    (command_output, actual_command, archive_bytes) = result
    if not isinstance(expected, dict):
        return 0.0
    expected_command = expected.get('command_match', 'catch the desired command')
    score = 0.0
    if isinstance(command_output, str) and expected_command in command_output:
        if actual_command and isinstance(actual_command, str):
            has_soffice = 'soffice' in actual_command.lower() or 'libreoffice' in actual_command.lower()
            has_convert = '--convert-to' in actual_command and 'rtf' in actual_command.lower()
            has_doc = '.doc' in actual_command or '*.doc' in actual_command
            if has_soffice and has_convert and has_doc:
                score += 0.5
        elif isinstance(command_output, str) and expected_command in command_output:
            score += 0.5
    if archive_bytes and len(archive_bytes) > 0:
        try:
            tar_stream = io.BytesIO(archive_bytes)
            with tarfile.open(fileobj=tar_stream, mode='r:gz') as tar:
                rtf_files = [member for member in tar.getmembers() if member.name.endswith('.rtf')]
                if len(rtf_files) == 14:
                    score += 0.5
                elif len(rtf_files) > 0:
                    score += 0.25
        except Exception:
            pass
    return score

def check_multiple_values__8467ab0e(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if multiple cell values match expected values, formulas are COUNTIFS, and labels are correct.

    Args:
        result: Dict with 'values', 'formulas', and 'labels' keys
        expected: Dict with 'values' (label: expected_value), optional 'tolerance',
                  'expected_labels' (label: expected_text), and 'formula_type' (e.g., 'COUNTIFS')
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (average of all checks)
    """
    expected_values = expected.get('values', {})
    tolerance = expected.get('tolerance', 0.01)
    expected_labels = expected.get('expected_labels', {})
    formula_type = expected.get('formula_type', 'COUNTIFS')
    if not expected_values:
        return 0.0
    actual_values = result.get('values', {})
    actual_formulas = result.get('formulas', {})
    actual_labels = result.get('labels', {})
    total_checks = 0
    passed_checks = 0
    for (label, expected_val) in expected_values.items():
        total_checks += 1
        actual_val = actual_values.get(label)
        if actual_val is None:
            continue
        try:
            actual = float(actual_val)
            expected_float = float(expected_val)
            if abs(actual - expected_float) <= tolerance:
                passed_checks += 1
        except (ValueError, TypeError):
            if actual_val == expected_val:
                passed_checks += 1
    for label in expected_values.keys():
        total_checks += 1
        formula = actual_formulas.get(label)
        if formula and formula_type.upper() in str(formula).upper():
            passed_checks += 1
    for (label_key, expected_text) in expected_labels.items():
        total_checks += 1
        actual_text = actual_labels.get(label_key)
        if actual_text == expected_text:
            passed_checks += 1
    return passed_checks / total_checks if total_checks > 0 else 0.0

