def check_grayscale__ade1ce93(result, expected, **options):
    """
    Check if the image has been converted to grayscale.

    Args:
        result: Path to the result image file
        expected: Not used (can be None)
        **options: Additional options

    Returns:
        float: 1.0 if image is grayscale, 0.0 otherwise
    """
    if result is None:
        logger.error('Result is None')
        return 0.0
    try:
        result_img = Image.open(result)
        if result_img.mode == 'L' or result_img.mode == 'LA':
            logger.debug(f'Image is in grayscale mode: {result_img.mode}')
            return 1.0
        elif result_img.mode == 'RGB' or result_img.mode == 'RGBA':
            img_array = np.array(result_img.convert('RGB'))
            r = img_array[:, :, 0]
            g = img_array[:, :, 1]
            b = img_array[:, :, 2]
            r_g_equal = np.allclose(r, g, atol=5)
            g_b_equal = np.allclose(g, b, atol=5)
            if r_g_equal and g_b_equal:
                logger.debug('Image is grayscale (RGB channels equal)')
                return 1.0
            else:
                logger.debug('Image is not grayscale (RGB channels differ)')
                return 0.0
        else:
            logger.debug(f'Unexpected image mode: {result_img.mode}')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking grayscale: {e}')
        return 0.0

