def check_acl_awards_complete__9e9727414c1d3a0cde148c7bac2e3c38(result, expected, **options):
    """Check if ACL awards data is complete and correct.

    Verifies:
    1. All 4 rows are present (2019-2022)
    2. Years are 2022, 2021, 2020, 2019 in descending order
    3. All rows have non-empty title, year, authors, and PDF URL
    4. Authors are comma-separated (contain at least one comma)
    5. PDF URLs contain 'aclanthology.org' or similar ACL domain

    Args:
        result: Dictionary with 'rows' and 'years' keys
        expected: Expected values from rules (contains 'expected_years')
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on completeness
    """
    if not result or not isinstance(result, dict):
        return 0.0
    rows = result.get('rows', [])
    years = result.get('years', [])
    expected_years = expected.get('expected_years', [2022, 2021, 2020, 2019])
    score = 0.0
    max_score = 5.0
    if len(rows) == len(expected_years):
        score += 1.0
    else:
        return 0.0
    if years == expected_years:
        score += 1.0
    else:
        is_descending = all((years[i] >= years[i + 1] for i in range(len(years) - 1))) if len(years) > 1 else True
        if is_descending and set(years) == set(expected_years):
            score += 0.5
        else:
            return 0.0
    all_fields_present = True
    for row in rows:
        if not row.get('title') or not row.get('year') or (not row.get('authors')) or (not row.get('pdf_url')):
            all_fields_present = False
            break
    if all_fields_present:
        score += 1.0
    else:
        return 0.0
    authors_valid = True
    for row in rows:
        authors = str(row.get('authors', ''))
        if ',' not in authors:
            authors_valid = False
            break
    if authors_valid:
        score += 1.0
    else:
        score += 0.5
    urls_valid = True
    for row in rows:
        pdf_url = str(row.get('pdf_url', '')).lower()
        if not ('aclanthology.org' in pdf_url or 'acl' in pdf_url or '.pdf' in pdf_url):
            urls_valid = False
            break
    if urls_valid:
        score += 1.0
    else:
        score += 0.5
    return score / max_score

def check_author_formatting__48531793(result: List[Dict[str, str]], expected: Any, **options) -> float:
    """
    Check if paper information is complete and properly formatted.

    Args:
        result: List of paper dicts from getter with keys: 'title', 'year', 'authors', 'pdf_link'
        expected: Dict with:
            - separator: Required separator for authors (e.g., ",")
            - min_entries: Minimum number of paper entries required (2 for years 2020 and 2021)
            - min_authors_per_entry: Minimum authors per entry (default: 1)

    Returns:
        Score between 0.0 and 1.0
    """
    separator = expected.get('separator', ',')
    min_entries = expected.get('min_entries', 1)
    min_authors_per_entry = expected.get('min_authors_per_entry', 1)
    if len(result) < min_entries:
        return 0.0
    valid_count = 0
    years_found = set()
    required_years = {'2020', '2021'}
    for paper in result:
        title = paper.get('title', '')
        year = paper.get('year', '')
        authors = paper.get('authors', '')
        pdf_link = paper.get('pdf_link', '')
        checks_passed = 0
        total_checks = 4
        if title and len(title) > 5:
            checks_passed += 1
        if year in required_years:
            checks_passed += 1
            years_found.add(year)
        if authors:
            if ' and ' not in authors.lower() and ';' not in authors:
                if separator in authors:
                    author_list = [a.strip() for a in authors.split(separator)]
                    if len(author_list) >= min_authors_per_entry:
                        checks_passed += 1
                elif authors.strip() and min_authors_per_entry == 1:
                    checks_passed += 1
        if pdf_link and 'aclanthology.org' in pdf_link.lower():
            checks_passed += 1
        if checks_passed == total_checks:
            valid_count += 1
    year_coverage_penalty = 0.0
    if len(years_found) < 2:
        year_coverage_penalty = 0.3
    if len(result) == 0:
        return 0.0
    base_score = valid_count / len(result)
    final_score = max(0.0, base_score - year_coverage_penalty)
    return final_score

def check_spacing__9c612fede8141550419e9174fb604127(result, expected, **options):
    """Check if line spacing and font size match expected values.

    Args:
        result: Dictionary with paragraph index and dict of spacing/font info
                Example: {0: {'line_spacing': 1.0, 'font_size': 12.0}, 1: {'line_spacing': 1.5, 'font_size': 12.0}}
        expected: Dictionary with expected spacing and font sizes for each paragraph (from rules)
        **options: Additional comparison options

    Returns:
        float: 1.0 if all spacing and font sizes match, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    expected_spacings = expected.get('paragraph_spacings', {})
    expected_font_size = expected.get('font_size', 12.0)
    for (para_idx, expected_spacing) in expected_spacings.items():
        para_idx_int = int(para_idx)
        para_info = result.get(para_idx_int)
        if para_info is None or not isinstance(para_info, dict):
            return 0.0
        actual_spacing = para_info.get('line_spacing')
        actual_font_size = para_info.get('font_size')
        if actual_spacing is None or not isinstance(actual_spacing, (int, float)):
            return 0.0
        if actual_font_size is None or not isinstance(actual_font_size, (int, float)):
            return 0.0
        if abs(actual_spacing - expected_spacing) > 0.01:
            return 0.0
        if abs(actual_font_size - expected_font_size) > 0.5:
            return 0.0
    return 1.0

def check_tetris_rotate_fix__72c9bc74(result, expected, **options):
    """Verify rotate() method contains collision-revert logic and test boundary behavior.

    Args:
        result: dict of filename -> file content
        expected: dict with test scenario

    Returns:
        float: Score 0.0-1.0
    """
    import tempfile
    import os
    import sys
    import importlib.util
    import re
    files = {'tetris.py': result.get('tetris.py'), 'block.py': result.get('block.py'), 'settings.py': result.get('settings.py')}
    for (name, content) in files.items():
        if not content:
            return 0.0
    tetris_content = files['tetris.py']
    rotate_pattern = 'def\\s+rotate\\s*\\([^)]*\\)\\s*:(.*?)(?=\\n    def\\s|\\nclass\\s|\\Z)'
    rotate_match = re.search(rotate_pattern, tetris_content, re.DOTALL)
    if not rotate_match:
        return 0.0
    rotate_body = rotate_match.group(1)
    has_save_rotation = bool(re.search('old_rotation\\s*=\\s*self\\.block\\.rotation', rotate_body))
    has_intersect_check = bool(re.search('if\\s+self\\.intersect\\(\\)', rotate_body))
    has_restore_rotation = bool(re.search('self\\.block\\.rotation\\s*=\\s*old_rotation', rotate_body))
    if not (has_save_rotation and has_intersect_check and has_restore_rotation):
        return 0.0
    with tempfile.TemporaryDirectory() as tmpdir:
        for (name, content) in files.items():
            with open(os.path.join(tmpdir, name), 'w') as f:
                f.write(content)
        sys.path.insert(0, tmpdir)
        try:
            spec = importlib.util.spec_from_file_location('tetris', os.path.join(tmpdir, 'tetris.py'))
            tetris_module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(tetris_module)
            spec2 = importlib.util.spec_from_file_location('settings', os.path.join(tmpdir, 'settings.py'))
            settings_module = importlib.util.module_from_spec(spec2)
            spec2.loader.exec_module(settings_module)
            Tetris = tetris_module.Tetris
            BOARD_HEIGHT = settings_module.BOARD_HEIGHT
            BOARD_WIDTH = settings_module.BOARD_WIDTH
            test_scenario = expected.get('test_scenario', 'full_game_flow')
            game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
            game.new_block()
            initial_x = game.block.x
            while game.block.x > 0:
                game.move(-1, 0)
            rotation_before = game.block.rotation
            game.rotate()
            if game.intersect():
                return 0.0
            game.new_block()
            while game.block.x + len(game.block.shape[0]) < game.width:
                game.move(1, 0)
            rotation_before = game.block.rotation
            game.rotate()
            if game.intersect():
                return 0.0
            game.new_block()
            for _ in range(4):
                game.rotate()
                if game.intersect():
                    return 0.0
            game.new_block()
            game.move(-1, 0)
            game.rotate()
            if game.intersect():
                return 0.0
            game.move(1, 0)
            game.rotate()
            if game.intersect():
                return 0.0
            return 1.0
        except Exception as e:
            print(f'Test execution error: {e}')
            return 0.0
        finally:
            sys.path.remove(tmpdir)

