def check_network_stats_format__26660ad1(result_state, expected_state, **options):
    """
    Check if the network stats file has the correct format:
    - Each measurement on a separate line
    - Name and value separated by tab character
    - All three metrics (Ping, Download, Upload) present with numeric values

    Args:
        result_state: File content as string
        expected_state: Not used (rule-based validation)
        **options: Additional options

    Returns:
        float: Score (1.0 if all checks pass, 0.0 otherwise)
    """
    if not result_state or not isinstance(result_state, str):
        return 0.0
    lines = [line for line in result_state.split('\n') if line.strip()]
    required_metrics = {'Ping', 'Download', 'Upload'}
    found_metrics = set()
    pattern = '^(Ping|Download|Upload)\\t(.+)$'
    for line in lines:
        match = re.match(pattern, line)
        if match:
            label = match.group(1)
            value = match.group(2).strip()
            if re.search('\\d', value):
                found_metrics.add(label)
    if found_metrics == required_metrics:
        return 1.0
    return 0.0

def check_tetris_rotate_fix__b3b822fe(result, expected, **options):
    """Functional test for rotate() method fix.

    Args:
        result: dict of filename -> file content
        expected: dict with test scenario

    Returns:
        float: Score 0.0-1.0
    """
    import tempfile
    import os
    import sys
    import importlib.util
    files = {'tetris.py': result.get('tetris.py'), 'block.py': result.get('block.py'), 'settings.py': result.get('settings.py')}
    for (name, content) in files.items():
        if not content:
            return 0.0
    with tempfile.TemporaryDirectory() as tmpdir:
        for (name, content) in files.items():
            with open(os.path.join(tmpdir, name), 'w') as f:
                f.write(content)
        sys.path.insert(0, tmpdir)
        try:
            spec = importlib.util.spec_from_file_location('tetris', os.path.join(tmpdir, 'tetris.py'))
            tetris_module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(tetris_module)
            spec2 = importlib.util.spec_from_file_location('settings', os.path.join(tmpdir, 'settings.py'))
            settings_module = importlib.util.module_from_spec(spec2)
            spec2.loader.exec_module(settings_module)
            Tetris = tetris_module.Tetris
            BOARD_HEIGHT = settings_module.BOARD_HEIGHT
            BOARD_WIDTH = settings_module.BOARD_WIDTH
            test_scenario = expected.get('test_scenario', 'left_boundary')
            if test_scenario == 'left_boundary':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                while game.block.x > 0:
                    game.move(-1, 0)
                game.rotate()
                if game.intersect():
                    return 0.0
                return 1.0
            elif test_scenario == 'right_boundary':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                while game.block.x + len(game.block.shape[0]) < game.width:
                    game.move(1, 0)
                game.rotate()
                if game.intersect():
                    return 0.0
                return 1.0
            elif test_scenario == 'complete_rotation_cycle':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                for _ in range(4):
                    game.rotate()
                    if game.intersect():
                        return 0.0
                return 1.0
            elif test_scenario == 'comprehensive':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                while game.block.x > 0:
                    game.move(-1, 0)
                game.rotate()
                if game.intersect():
                    return 0.0
                game.new_block()
                while game.block.x + len(game.block.shape[0]) < game.width:
                    game.move(1, 0)
                game.rotate()
                if game.intersect():
                    return 0.0
                return 1.0
            elif test_scenario == 'full_game_flow':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                game.move(-1, 0)
                game.rotate()
                game.move(1, 0)
                game.rotate()
                game.go_down()
                if game.intersect():
                    return 0.0
                return 1.0
            return 0.0
        except Exception as e:
            print(f'Test execution error: {e}')
            return 0.0
        finally:
            sys.path.remove(tmpdir)

