def check_platform_filter__b86f13327ea809fbd5f8fe969c9d2d45(result: List[str], expected: Dict[str, Any], **options) -> float:
    """
    Check if the docx file contains only records for the specified platform.

    Args:
        result: List of train record lines from getter
        expected: Dict with 'platform_no' and 'expected_count' keys
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list):
        logger.error(f'Result is not a list: {type(result)}')
        return 0.0
    target_platform = expected.get('platform_no')
    expected_count = expected.get('expected_count')
    if not target_platform or expected_count is None:
        logger.error('Missing platform_no or expected_count in expected config')
        return 0.0
    valid_count = 0
    for line in result:
        parts = line.split(',')
        if len(parts) == 4:
            platform_no = parts[3].strip()
            if platform_no == target_platform:
                valid_count += 1
            else:
                logger.info(f'Found record for wrong platform: {platform_no} (expected {target_platform})')
                return 0.0
    if valid_count == expected_count:
        return 1.0
    else:
        logger.info(f'Record count mismatch: got {valid_count}, expected {expected_count}')
        return 0.0

def check_tetris_rotate_fix__cb4dc6e5(result, expected, **options):
    """Check structural elements of rotate() method using AST parsing.

    Args:
        result: dict of filename -> file content
        expected: dict with required elements and rules

    Returns:
        float: Score 0.0-1.0
    """
    tetris_content = result.get('tetris.py')
    if not tetris_content:
        return 0.0
    try:
        tree = ast.parse(tetris_content)
    except SyntaxError:
        return 0.0
    rotate_method = None
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name == 'rotate':
            rotate_method = node
            break
    if not rotate_method:
        return 0.0
    found_old_rotation_assignment = False
    found_rotate_call = False
    found_if_intersect = False
    found_restoration_in_if = False
    old_rotation_index = -1
    rotate_call_index = -1
    intersect_if_index = -1
    statements = rotate_method.body
    for (idx, stmt) in enumerate(statements):
        if isinstance(stmt, ast.Assign):
            for target in stmt.targets:
                if isinstance(target, ast.Name) and target.id == 'old_rotation':
                    if isinstance(stmt.value, ast.Attribute):
                        if isinstance(stmt.value.value, ast.Attribute) and isinstance(stmt.value.value.value, ast.Name) and (stmt.value.value.value.id == 'self') and (stmt.value.value.attr == 'block') and (stmt.value.attr == 'rotation'):
                            found_old_rotation_assignment = True
                            old_rotation_index = idx
        if isinstance(stmt, ast.Expr):
            if isinstance(stmt.value, ast.Call):
                if isinstance(stmt.value.func, ast.Attribute):
                    if isinstance(stmt.value.func.value, ast.Attribute) and isinstance(stmt.value.func.value.value, ast.Name) and (stmt.value.func.value.value.id == 'self') and (stmt.value.func.value.attr == 'block') and (stmt.value.func.func.attr == 'rotate'):
                        found_rotate_call = True
                        rotate_call_index = idx
        if isinstance(stmt, ast.If):
            test = stmt.test
            if isinstance(test, ast.Call):
                if isinstance(test.func, ast.Attribute):
                    if isinstance(test.func.value, ast.Name) and test.func.value.id == 'self' and (test.func.attr == 'intersect'):
                        found_if_intersect = True
                        intersect_if_index = idx
                        for if_stmt in stmt.body:
                            if isinstance(if_stmt, ast.Assign):
                                for target in if_stmt.targets:
                                    if isinstance(target, ast.Attribute):
                                        if isinstance(target.value, ast.Attribute) and isinstance(target.value.value, ast.Name) and (target.value.value.id == 'self') and (target.value.attr == 'block') and (target.attr == 'rotation'):
                                            if isinstance(if_stmt.value, ast.Name) and if_stmt.value.id == 'old_rotation':
                                                found_restoration_in_if = True
    correct_sequence = True
    if found_old_rotation_assignment and found_rotate_call:
        if old_rotation_index >= rotate_call_index:
            correct_sequence = False
    if found_rotate_call and found_if_intersect:
        if rotate_call_index >= intersect_if_index:
            correct_sequence = False
    expected_rules = expected.get('rules', {})
    required_elements = expected_rules.get('required_elements', ['old_rotation variable assignment', 'self.block.rotate() call', 'if self.intersect() check', 'rotation restoration'])
    checks = {'old_rotation variable assignment': found_old_rotation_assignment, 'self.block.rotate() call': found_rotate_call, 'if self.intersect() check': found_if_intersect, 'rotation restoration': found_restoration_in_if}
    passed_checks = sum((1 for elem in required_elements if checks.get(elem, False)))
    if passed_checks == len(required_elements) and correct_sequence:
        return 1.0
    return passed_checks / len(required_elements)

def check_author_mentioned__f9fa7b925a8af809c4d7a02e0264dd76(result, expected, **options):
    """
    Check if the text file contains EXACTLY the expected author name and not the full author list.

    Args:
        result: str content from getter
        expected: str expected author name (e.g., "Jacob Devlin")

    Returns:
        float: 1.0 if only the first author name is present, 0.0 otherwise
    """
    if not isinstance(result, str) or not isinstance(expected, str):
        return 0.0
    result_normalized = result.strip().lower()
    expected_normalized = expected.strip().lower()
    if result_normalized == expected_normalized:
        return 1.0
    other_authors = ['ming-wei chang', 'kenton lee', 'kristina toutanova']
    for other_author in other_authors:
        if other_author in result_normalized:
            return 0.0
    if expected_normalized in result_normalized:
        if ',' in result:
            return 0.0
        result_tokens = result_normalized.split()
        if len(result_tokens) > 4:
            return 0.0
        return 1.0
    else:
        return 0.0

def check_paper_structure__aa99bafa(result, expected, **options):
    """Check if paper structure meets requirements (count and metadata completeness).

    Args:
        result: Paper structure from getter (dict with paper_count, papers_complete, etc.)
        expected: Expected rules dict with:
            - total_papers: Expected total number of papers
            - min_complete_papers: Minimum number of papers with all metadata fields
        **options: Additional comparison options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None:
        logger.error('Result is None, cannot compare')
        return 0.0
    try:
        expected_total = expected.get('total_papers', 5)
        expected_complete = expected.get('min_complete_papers', 5)
        actual_paper_count = result.get('paper_count', 0)
        actual_complete = result.get('papers_complete', 0)
        logger.info(f'Paper count: {actual_paper_count} (expected: {expected_total})')
        logger.info(f'Complete papers: {actual_complete} (expected: >= {expected_complete})')
        if actual_paper_count < expected_total:
            logger.error(f'Paper count check failed: {actual_paper_count} < {expected_total}')
            return 0.0
        if actual_complete < expected_complete:
            logger.error(f'Complete papers check failed: {actual_complete} < {expected_complete}')
            return 0.0
        papers_with_title = result.get('papers_with_title', 0)
        papers_with_authors = result.get('papers_with_authors', 0)
        papers_with_abstract = result.get('papers_with_abstract', 0)
        papers_with_arxiv = result.get('papers_with_arxiv', 0)
        if papers_with_title < expected_total or papers_with_authors < expected_total or papers_with_abstract < expected_total or (papers_with_arxiv < expected_total):
            logger.error(f'Metadata coverage insufficient - Title:{papers_with_title}, Authors:{papers_with_authors}, Abstract:{papers_with_abstract}, Arxiv:{papers_with_arxiv}')
            return 0.0
        logger.info('All paper structure checks passed')
        return 1.0
    except (ValueError, TypeError) as e:
        logger.error(f'Error comparing paper structure: {e}')
        return 0.0

