def check_bib_authors__7d0fecc9(result: Dict[str, Any], expected: dict, **options) -> float:
    """
    Check if specific authors are present in the BibTeX file and verify no truncation.

    Args:
        result: Dictionary from getter containing 'authors', 'has_truncation', 'entry_count'
        expected: Expected rules dict with 'required_authors' key
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 based on:
            - Presence of required authors (70% weight)
            - No author truncation (30% weight)
    """
    required_authors = expected.get('required_authors', [])
    if not required_authors:
        return 0.0
    authors = result.get('authors', [])
    has_truncation = result.get('has_truncation', False)
    entry_count = result.get('entry_count', 0)
    if entry_count == 0:
        return 0.0
    result_normalized = [a.lower() for a in authors]
    found_count = 0
    for req_author in required_authors:
        req_lower = req_author.lower()
        for res_author in result_normalized:
            if req_lower in res_author or res_author in req_lower:
                found_count += 1
                break
    author_score = found_count / len(required_authors) * 0.7
    truncation_score = 0.3 if not has_truncation else 0.0
    return author_score + truncation_score

