def check_last_rows__9453c274a20969d63590381e37c06d85(result, expected, **options):
    """Check if DOCX table contains the expected last rows with all columns and formatting.

    Args:
        result: Dict with 'rows', 'num_rows', 'num_cols', 'formatting' from getter
        expected: Dict with 'exact_rows', 'exact_cols', 'expected_first_col', 'expected_all_data', 'check_formatting'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, dict):
        return 0.0
    rows = result.get('rows', [])
    num_rows = result.get('num_rows', 0)
    num_cols = result.get('num_cols', 0)
    formatting = result.get('formatting', [])
    exact_rows = expected.get('exact_rows', 0)
    exact_cols = expected.get('exact_cols', None)
    min_cols = expected.get('min_cols', 1)
    expected_first_col = expected.get('expected_first_col', [])
    expected_all_data = expected.get('expected_all_data', None)
    check_formatting = expected.get('check_formatting', False)
    score = 0.0
    if num_rows != exact_rows:
        if abs(num_rows - exact_rows) <= 1:
            score += 0.1
        else:
            return 0.0
    else:
        score += 0.25
    if exact_cols is not None:
        if num_cols == exact_cols:
            score += 0.25
        elif num_cols >= min_cols:
            score += 0.1
    elif num_cols >= min_cols:
        score += 0.25
    else:
        score += 0.05
    if expected_first_col:
        first_col_values = []
        for row in rows:
            if len(row) > 0:
                try:
                    val = row[0]
                    if isinstance(val, str):
                        try:
                            val = int(val)
                        except ValueError:
                            continue
                    first_col_values.append(val)
                except (ValueError, TypeError):
                    pass
        matches = 0
        for (i, expected_val) in enumerate(expected_first_col):
            if i < len(first_col_values):
                if first_col_values[i] == expected_val:
                    matches += 1
        if matches == len(expected_first_col) and len(first_col_values) == len(expected_first_col):
            score += 0.2
        elif matches >= len(expected_first_col) * 0.8:
            score += 0.15
        else:
            score += 0.05
    if expected_all_data and isinstance(expected_all_data, list):
        data_match_score = 0.0
        total_cells = 0
        matching_cells = 0
        for (i, expected_row) in enumerate(expected_all_data):
            if i < len(rows):
                actual_row = rows[i]
                for (j, expected_val) in enumerate(expected_row):
                    if j < len(actual_row):
                        total_cells += 1
                        actual_val = actual_row[j]
                        if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
                            if expected_val == actual_val:
                                matching_cells += 1
                        elif str(expected_val).strip() == str(actual_val).strip():
                            matching_cells += 1
        if total_cells > 0:
            data_match_score = matching_cells / total_cells * 0.2
            score += data_match_score
    else:
        score += 0.2
    if check_formatting and formatting:
        has_formatting = False
        for row_fmt in formatting:
            for cell_fmt in row_fmt:
                if cell_fmt and len(cell_fmt) > 0:
                    has_formatting = True
                    break
            if has_formatting:
                break
        if has_formatting:
            score += 0.1
        else:
            score += 0.03
    else:
        score += 0.1
    return min(1.0, score)

