def check_numbered_chapters__a26911b7babb666234e16a8cd9e0ff40(result: List[str], expected: Dict[str, Any], **options) -> float:
    """
    Check if numbered chapter PDFs exist with correct count and sequential numbering.

    Args:
        result: List of numbered chapter PDF filenames from getter
        expected: Dict with 'min_chapters' (minimum expected chapters)

    Returns:
        Score between 0.0 and 1.0
        - 0.5 if at least min_chapters exist
        - 1.0 if sequential numbering from 1 to N exists
    """
    min_chapters = expected.get('min_chapters', 8)
    if not result:
        logger.warning('No numbered chapter PDFs found')
        return 0.0
    chapter_numbers = []
    for filename in result:
        try:
            parts = filename.split('. ', 1)
            if len(parts) == 2 and parts[0].isdigit():
                chapter_numbers.append(int(parts[0]))
        except (ValueError, IndexError):
            logger.warning(f'Failed to extract chapter number from: {filename}')
            continue
    if not chapter_numbers:
        logger.warning('No valid chapter numbers found')
        return 0.0
    chapter_numbers.sort()
    if len(chapter_numbers) < min_chapters:
        logger.warning(f'Found {len(chapter_numbers)} chapters, expected at least {min_chapters}')
        return 0.0
    score = 0.5
    expected_sequence = list(range(1, len(chapter_numbers) + 1))
    if chapter_numbers == expected_sequence:
        score = 1.0
        logger.info(f'Found {len(chapter_numbers)} sequential chapters (1-{len(chapter_numbers)})')
    else:
        logger.warning(f'Chapter numbering not sequential: {chapter_numbers}')
    return score

def check_returns__66609e41(result_file_path, expected, **options):
    """Check if return statements are correctly extracted from code.

    Args:
        result_file_path: Path to file containing extracted return statements
        expected: Dict with 'min_returns' (int) and 'all_contain_return' (bool)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result_file_path:
        return 0.0
    try:
        with open(result_file_path, 'r', encoding='utf-8') as f:
            content = f.read()
        lines = [line.strip() for line in content.splitlines() if line.strip()]
        min_returns = expected.get('min_returns', 0)
        all_contain_return = expected.get('all_contain_return', False)
        score = 0.0
        if len(lines) >= min_returns:
            score += 0.5
        if lines:
            non_comment_lines = [l for l in lines if not l.startswith('#')]
            if non_comment_lines:
                valid_returns = 0
                for line in non_comment_lines:
                    if re.search('\\breturn\\b', line, re.IGNORECASE):
                        valid_returns += 1
                return_ratio = valid_returns / len(non_comment_lines)
                if all_contain_return:
                    if return_ratio >= 1.0:
                        score += 0.5
                else:
                    score += 0.5 * return_ratio
        return min(score, 1.0)
    except Exception as e:
        print(f'Error checking return statements: {e}')
        return 0.0

