def check_tetris_rotate_fix__65e60eeb(result, expected, **options):
    """Check if rotate() method has proper collision checking using AST.

    Args:
        result: dict of filename -> file content
        expected: dict with validation requirements

    Returns:
        float: Score 0.0-1.0
    """
    tetris_content = result.get('tetris.py')
    if not tetris_content:
        return 0.0
    try:
        tree = ast.parse(tetris_content)
    except SyntaxError:
        return 0.0
    rotate_method = None
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == 'Tetris':
            for item in node.body:
                if isinstance(item, ast.FunctionDef) and item.name == 'rotate':
                    rotate_method = item
                    break
    if not rotate_method:
        return 0.0
    score = 0.0
    checks_passed = 0
    total_checks = 3
    has_old_rotation = False
    for node in ast.walk(rotate_method):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and 'old_rotation' in target.id:
                    has_old_rotation = True
                    break
    if has_old_rotation:
        checks_passed += 1
    calls_intersect = False
    for node in ast.walk(rotate_method):
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Attribute) and node.func.attr == 'intersect':
                calls_intersect = True
                break
    if calls_intersect:
        checks_passed += 1
    has_if = False
    for node in ast.walk(rotate_method):
        if isinstance(node, ast.If):
            has_if = True
            break
    if has_if:
        checks_passed += 1
    return checks_passed / total_checks

