def check_cs_max_year__a0de86bd3e0a331a83b39cd8c4fb9536(result, expected, **options):
    """Compare table data for all years and verify max year identification

    Args:
        result: Extracted data {
            'all_years': {year: {'applications': int, 'supported': int}, ...},
            'max_year': int,
            'max_applications': int,
            'max_supported': int
        }
        expected: Expected values containing all_years data and max year info
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None or expected is None:
        return 0.0
    score = 0.0
    expected_all_years = expected.get('all_years', {})
    expected_max_year = expected.get('year')
    expected_max_apps = expected.get('applications')
    expected_max_supported = expected.get('supported')
    result_all_years = result.get('all_years', {})
    result_max_year = result.get('max_year')
    result_max_apps = result.get('max_applications')
    result_max_supported = result.get('max_supported')
    required_years = {2019, 2020, 2021, 2022, 2023}
    present_years = set(result_all_years.keys())
    if required_years.issubset(present_years):
        score += 0.3
    else:
        score += 0.3 * (len(required_years & present_years) / len(required_years))
    if result_max_year == expected_max_year:
        score += 0.3
    if result_max_apps == expected_max_apps:
        score += 0.2
    if result_max_supported == expected_max_supported:
        score += 0.1
    if expected_all_years:
        matching_years = 0
        total_years = len(expected_all_years)
        for (year, expected_data) in expected_all_years.items():
            year_int = int(year) if isinstance(year, str) else year
            if year_int in result_all_years:
                result_data = result_all_years[year_int]
                apps_match = result_data.get('applications') == expected_data.get('applications')
                if 'supported' in expected_data:
                    supported_match = result_data.get('supported') == expected_data.get('supported')
                    if apps_match and supported_match:
                        matching_years += 1
                elif apps_match:
                    matching_years += 1
        if total_years > 0:
            score += 0.1 * (matching_years / total_years)
    else:
        score += 0.1
    return score

def check_row_complete__cc29f13b(result: Optional[Tuple], expected: dict, **options) -> float:
    """Check if row 3 has Alpaca paper from arXiv published in 2023.

    Args:
        result: Tuple containing (col_a, col_b, col_c) where:
                - col_a: Paper title (should contain 'Alpaca')
                - col_b: arXiv link (should contain 'arxiv.org')
                - col_c: Publication date (should contain '2023')
        expected: Expected rules dict (not used, but required by framework)
        **options: Additional comparison options

    Returns:
        Float score: 0.33 per correct column, 1.0 if all requirements met
    """
    if result is None:
        return 0.0
    if len(result) < 3 or any((cell is None for cell in result[:3])):
        return 0.0
    (title, arxiv_link, pub_date) = result[:3]
    score = 0.0
    title_str = str(title).strip() if title else ''
    link_str = str(arxiv_link).strip() if arxiv_link else ''
    date_str = str(pub_date).strip() if pub_date else ''
    if 'alpaca' in title_str.lower():
        score += 0.33
    if 'arxiv.org' in link_str.lower():
        if re.search('arxiv\\.org/(abs|pdf)/', link_str, re.IGNORECASE):
            score += 0.34
        else:
            score += 0.34
    if '2023' in date_str:
        score += 0.33
    return round(score, 2)

def check_paper_counts__4add7e04(actual_file_path, expected):
    """Check if paper submission counts are filled in correctly for conferences.

    This function verifies that column C (cells C2:C22) contains the expected
    paper submission counts for ML conferences (ICLR, ICML, Neurips) from 2013-2019.
    Note: Column C may be labeled 'City' in the spreadsheet, but should contain
    numeric paper counts as per the task instruction.

    Args:
        actual_file_path: Path to the Excel file with filled paper count data
        expected: Expected configuration with paper count values

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('expected_values', [])
    wb = openpyxl.load_workbook(actual_file_path, data_only=True)
    sheet = wb.active
    column_c_header = sheet['C1'].value
    logger.info(f'Column C header: {column_c_header}')
    logger.info(f'Checking column C (cells C2:C22) for paper submission counts')
    actual_values = []
    for row in sheet['C2:C22']:
        for cell in row:
            actual_values.append(cell.value)
    score = 0.0
    total_checks = len(expected_values)
    if total_checks == 0:
        return 0.0
    for i in range(total_checks):
        try:
            expected_val = expected_values[i]
            actual_val = actual_values[i]
            if isinstance(expected_val, (int, float)) and actual_val is not None:
                try:
                    actual_num = float(actual_val)
                    if abs(actual_num - expected_val) / expected_val <= 0.15:
                        score += 1.0 / total_checks
                except (ValueError, TypeError):
                    pass
            elif expected_val == actual_val:
                score += 1.0 / total_checks
        except (IndexError, KeyError, TypeError) as e:
            logger.debug(f'Error checking index {i}: {e}')
            continue
    return round(score, 3)

