def check_word_count_reduced__4129d6f6(result, expected, **options):
    """Check if word count is within expected range (reduced by removing content).

    Args:
        result: Word count from getter (int)
        expected: Expected word count or range dict
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if isinstance(expected, dict):
        min_words = expected.get('min', 0)
        max_words = expected.get('max', float('inf'))
    else:
        min_words = expected * 0.95
        max_words = expected * 1.05
    if min_words <= result <= max_words:
        logger.info(f'✓ Word count check passed: {result} is within [{min_words}, {max_words}]')
        return 1.0
    else:
        logger.warning(f'✗ Word count check failed: {result} is not within [{min_words}, {max_words}]')
        if result < min_words:
            ratio = result / min_words
        else:
            ratio = max_words / result
        return max(0.0, ratio)

