def check_measurement_unit__0512abb6ecb330fe633a46620638ec23(config_file, rules):
    """
    Check if the measurement unit is set to the specified unit.

    Args:
        config_file: Path to registrymodifications.xcu file
        rules: Dict with 'unit' key specifying the expected unit (e.g., 6 for cm, 3 for mm)

    Returns:
        1.0 if measurement unit matches expected value, 0.0 otherwise
    """
    expected_unit = rules['unit']
    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
        for item in root.findall('.//item'):
            path = item.get('{http://openoffice.org/2001/registry}path')
            if path == '/org.openoffice.Office.Impress/Layout/Other':
                for prop in item.findall('.//prop'):
                    name = prop.get('{http://openoffice.org/2001/registry}name')
                    if name == 'MeasureUnit':
                        unit_value = prop.find('.//value').text
                        if unit_value is not None and int(unit_value) == expected_unit:
                            return 1.0
                        else:
                            return 0.0
        return 0.0
    except ET.ParseError as e:
        logger.error(f'Error parsing XML: {e}')
        return 0.0
    except FileNotFoundError:
        logger.error(f'File not found: {config_file}')
        return 0.0
    except Exception as e:
        logger.error(f'Unexpected error: {e}')
        return 0.0

def check_normal_view__be7f4bd7(accessibility_tree, expected, **options):
    """
    Check if Normal view is active in LibreOffice Impress (not Master view, not Sorter view).

    Args:
        accessibility_tree: XML accessibility tree from the environment
        expected: Expected rules (not used for this check)
        **options: Additional options

    Returns:
        float: 1.0 if in Normal view, 0.0 otherwise
    """
    try:
        namespaces = {'st': 'uri:deskat:state.at-spi.gnome.org', 'cp': 'uri:deskat:component.at-spi.gnome.org'}
        root = ET.fromstring(accessibility_tree)
        for menu_item in root.iter('menu-item'):
            name = menu_item.attrib.get('name', '')
            if 'Close Master View' in name:
                return 0.0
        for doc_frame in root.iter('document-frame'):
            if doc_frame.attrib.get('name') == 'Slides View':
                return 1.0
        return 0.0
    except Exception as e:
        logger.error(f'Error checking Normal view: {e}')
        return 0.0

