def check_average_value__d55a5eb921ae3bc93858d924939bcf21(result, expected, **options):
    """Check if average value is within tolerance and uses AVERAGE formula.

    Args:
        result: Dictionary with 'value' (float) and 'formula' (str or None)
        expected: Dictionary with 'value' key containing expected average
        **options: Additional options including 'tolerance' (default 0.01)

    Returns:
        float: 1.0 if both formula and value are correct, 0.0 otherwise
    """
    expected_value = expected.get('value', 0.0)
    tolerance = options.get('tolerance', 0.01)
    formula = result.get('formula')
    if not formula or not isinstance(formula, str) or (not formula.startswith('=')):
        return 0.0
    formula_upper = formula.upper()
    if 'AVERAGE' not in formula_upper:
        return 0.0
    actual_value = result.get('value', 0.0)
    diff = abs(actual_value - expected_value)
    return 1.0 if diff <= tolerance else 0.0

def check_grammar_test_count__9476f460e57fa1aae3cff7718f6a60d8(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the correct number of grammar test sections exist with actual answer content.

    Args:
        result: Dict with 'test_count', 'test_sections', and 'test_sections_with_answers' from getter
        expected: Dict with 'expected_count' and optionally 'expected_sections'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_count = expected.get('expected_count', 0)
    expected_sections = expected.get('expected_sections', [])
    result_count = result.get('test_count', 0)
    result_sections = result.get('test_sections', [])
    result_sections_with_answers = result.get('test_sections_with_answers', [])
    logger.info(f'Expected {expected_count} test sections, found {result_count}')
    logger.info(f'Found {len(result_sections_with_answers)} sections with actual answer content')
    if result_count != expected_count:
        logger.warning(f'Test count mismatch: expected {expected_count}, got {result_count}')
        return 0.0
    if expected_sections:
        score = 0.0
        for expected_section in expected_sections:
            expected_normalized = expected_section.lower().replace('grammar', '').replace('grammer', '').strip()
            found_with_answers = False
            for section_with_answers in result_sections_with_answers:
                section_normalized = section_with_answers.lower().replace('grammar', '').replace('grammer', '').strip()
                if expected_normalized == section_normalized:
                    found_with_answers = True
                    logger.info(f'✓ Found expected section with answers: {expected_section}')
                    break
            if found_with_answers:
                score += 1.0 / len(expected_sections)
            else:
                found_without_answers = False
                for section in result_sections:
                    section_normalized = section.lower().replace('grammar', '').replace('grammer', '').strip()
                    if expected_normalized == section_normalized:
                        found_without_answers = True
                        break
                if found_without_answers:
                    logger.warning(f'⚠ Found section header but no answer content: {expected_section}')
                else:
                    logger.warning(f'✗ Missing expected section: {expected_section}')
        return score
    elif len(result_sections_with_answers) == expected_count:
        return 1.0
    else:
        logger.warning(f'Not all sections have answer content: {len(result_sections_with_answers)}/{expected_count}')
        return 0.0

