def check_multi_step_task__45f05906(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Multi-step evaluator with partial credit for email extraction and upload task

    Args:
        result: Dict from getters with results from each step:
            - email_check: Result from email verification
            - docx_check: Result from docx download verification
            - drive_check: Result from Google Drive file count verification
        expected: Dict with expected values for each step:
            - email_expected: Expected values for email check
            - docx_expected: Expected values for docx check
            - drive_expected: Expected values for drive check

    Returns:
        Weighted score between 0.0 and 1.0:
        - Email found: 0.2
        - Docx downloaded with images: 0.2
        - PNG files uploaded to Drive: 0.6 (folder exists 0.3 + correct file count 0.3)
    """
    if result is None or not isinstance(result, dict):
        logger.error('Invalid result format - expected dict')
        return 0.0
    total_score = 0.0
    email_result = result.get('email_check', {})
    if email_result.get('email_found', False) and email_result.get('has_attachment', False):
        total_score += 0.2
        logger.info('Email step passed: +0.2')
    else:
        logger.info('Email step failed: +0.0')
    docx_result = result.get('docx_check', {})
    if docx_result.get('file_found', False) and docx_result.get('has_images', False):
        total_score += 0.2
        logger.info('Docx download step passed: +0.2')
    else:
        logger.info('Docx download step failed: +0.0')
    drive_result = result.get('drive_check', {})
    drive_expected = expected.get('drive_expected', {})
    if drive_result.get('folder_exists', False):
        folder_created_time = drive_result.get('folder_created_time')
        if folder_created_time:
            try:
                from datetime import datetime, timezone
                created_dt = datetime.fromisoformat(folder_created_time.replace('Z', '+00:00'))
                current_dt = datetime.now(timezone.utc)
                age_minutes = (current_dt - created_dt).total_seconds() / 60
                if age_minutes <= 15:
                    total_score += 0.3
                    logger.info('Drive folder step passed (recent creation): +0.3')
                else:
                    logger.info(f'Drive folder too old ({age_minutes:.1f} min): +0.0')
            except Exception as e:
                logger.warning(f'Could not verify folder timestamp: {e}')
        else:
            logger.info('No folder creation timestamp: +0.0')
    else:
        logger.info('Drive folder not found: +0.0')
    count = drive_result.get('count', 0)
    min_count = drive_expected.get('min_count', 3)
    if count >= min_count:
        total_score += 0.3
        logger.info(f'File count step passed ({count} >= {min_count}): +0.3')
    else:
        logger.info(f'File count insufficient ({count} < {min_count}): +0.0')
    logger.info(f'Multi-step task total score: {total_score}')
    return total_score

def check_archive_contents__ccef1fda30d9645300e2b2b1c657b52f(result, expected, **options):
    """Check if archive exists and contains expected files.

    Args:
        result: dict from getter {'exists': bool, 'files': list}
        expected: dict with 'required_files' list

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result.get('exists', False):
        logger.info('Archive does not exist')
        return 0.0
    result_files = result.get('files', [])
    required_files = expected.get('required_files', [])
    if not required_files:
        logger.warning('No required files specified in expected config')
        return 0.0
    score = 0.0
    matched = 0
    for req_file in required_files:
        if req_file in result_files:
            matched += 1
    score = matched / len(required_files) if required_files else 0.0
    logger.info(f'Archive check: {matched}/{len(required_files)} required files found. Score: {score}')
    return score

