def check_bullet_added__52d5df60(result_file, expected, **options):
    """
    Check if a bullet point was added to the content paragraph by verifying the paragraph level changed.

    Args:
        result_file: Path to the PPTX file
        expected: Expected values with 'slide_idx', 'shape_idx', 'para_idx', 'expected_level'
        **options: Additional options

    Returns:
        float: 1.0 if paragraph level matches expected, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_idx = expected.get('slide_idx', 0)
        shape_idx = expected.get('shape_idx', 1)
        para_idx = expected.get('para_idx', 0)
        expected_level = expected.get('expected_level', 1)
        if slide_idx >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return 0.0
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return 0.0
        paragraphs = shape.text_frame.paragraphs
        if para_idx >= len(paragraphs):
            return 0.0
        paragraph = paragraphs[para_idx]
        if paragraph.level == expected_level:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        return 0.0

def check_row_count__58df2e60(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if CSV file meets all requirements for the task.

    Verifies:
    1. File exists at the correct location
    2. Row count matches (10 data rows for employees)
    3. Column count is exactly 3 (columns B-D)
    4. Headers are present and reasonable

    Args:
        result: Dict with file_exists, path, row_count, column_count, headers, data
        expected: Dict with 'count' (expected number of rows)
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    if not result.get('file_exists', False):
        return 0.0
    expected_path = '/home/user/attendance_subset.csv'
    if result.get('path') != expected_path:
        return 0.0
    expected_count = expected.get('count', 0)
    if result.get('row_count', 0) != expected_count:
        return 0.0
    if result.get('column_count', 0) != 3:
        return 0.0
    headers = result.get('headers', [])
    if len(headers) != 3:
        return 0.0
    data = result.get('data', [])
    for row in data:
        if len(row) != 3:
            return 0.0
    return 1.0

def check_notes_content__30abfdbb(result, expected, **options):
    """Check if notes contain expected content.

    Args:
        result: List of actual note values
        expected: Dict with 'notes' list to match
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_notes = expected.get('notes', [])
    if not isinstance(result, list):
        return 0.0
    if len(result) != len(expected_notes):
        return 0.0
    matches = 0
    for (actual, exp) in zip(result, expected_notes):
        if actual == exp:
            matches += 1
        elif isinstance(actual, str) and isinstance(exp, str):
            if actual.strip().lower() == exp.strip().lower():
                matches += 1
    return matches / len(expected_notes) if expected_notes else 0.0

def check_conference_duration__bd7b9326(actual_file_path, expected):
    """Check if conference duration (in days) is filled in correctly.

    Args:
        actual_file_path: Path to the Excel file with filled duration data
        expected: Expected configuration with duration values

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('expected_values', [])
    wb = openpyxl.load_workbook(actual_file_path, data_only=True)
    sheet = wb.active
    actual_values = []
    for row in sheet['C2:C22']:
        for cell in row:
            actual_values.append(cell.value)
    score = 0.0
    total_checks = len(expected_values)
    if total_checks == 0:
        return 0.0
    for i in range(total_checks):
        try:
            expected_val = expected_values[i]
            actual_val = actual_values[i]
            if actual_val is None:
                continue
            actual_num = None
            if isinstance(actual_val, str):
                import re
                match = re.search('(\\d+)', actual_val)
                if match:
                    actual_num = int(match.group(1))
            elif isinstance(actual_val, (int, float)):
                actual_num = int(actual_val)
            if actual_num is not None and actual_num == expected_val:
                score += 1.0 / total_checks
        except (IndexError, KeyError, TypeError, ValueError) as e:
            logger.debug(f'Error checking index {i}: {e}')
            continue
    return round(score, 3)

def check_discrepancy_report__1e60aa55(result, expected, **options):
    """
    Check if the discrepancy report contains the expected invoice ID and difference amount.

    Args:
        result: Path to the report file or file content
        expected: Dict with 'rules' containing 'invoice_id' and 'difference'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_invoice_id = str(expected.get('invoice_id', ''))
    expected_difference = float(expected.get('difference', 0))
    if isinstance(result, str) and result.endswith('.txt'):
        try:
            with open(result, 'r') as f:
                content = f.read()
        except:
            return 0.0
    else:
        content = str(result)
    content = content.lower()
    score = 0.0
    if expected_invoice_id.lower() in content:
        score += 0.5
    numbers_in_content = re.findall('[\\$]?\\s*(\\d+\\.?\\d*)', content)
    numbers_in_content = [float(n) for n in numbers_in_content if n]
    if expected_difference in numbers_in_content or int(expected_difference) in [int(n) for n in numbers_in_content]:
        score += 0.5
    return score

def check_reverse_output__e61a4956be8def6a9771e817f7846dd9(result: str, expected: Any, **options) -> float:
    """
    Check if text output contains expected values in reverse order.

    Args:
        result: Actual text output from file
        expected: Dict with 'values' key containing list of expected values
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    expected_values = expected.get('values', [])
    if not expected_values:
        logger.warning('No expected values specified')
        return 0.0
    lines = [line.strip() for line in result.strip().split('\n') if line.strip()]
    if len(lines) != len(expected_values):
        return 0.0
    matched = 0
    for (i, (line, exp_val)) in enumerate(zip(lines, expected_values)):
        try:
            result_val = int(line)
            if result_val == exp_val:
                matched += 1
        except ValueError:
            continue
    return matched / len(expected_values)

