def check_notes_min_length__1286a751(result_file, expected, **options):
    """
    Check if slide notes meet minimum character length requirement and contain
    expected content about course grading requirements.

    Args:
        result_file: Path to the PPTX file
        expected: Dict with rules containing 'slide_index', 'min_length', and optionally 'expected_content'
        **options: Additional options

    Returns:
        float: 1.0 if notes length >= min_length and content matches, 0.0 otherwise
    """
    try:
        prs = Presentation(result_file)
        slide_index = expected.get('slide_index', 0)
        min_length = expected.get('min_length', 0)
        expected_content = expected.get('expected_content', None)
        if slide_index >= len(prs.slides):
            return 0.0
        slide = prs.slides[slide_index]
        notes_slide = slide.notes_slide
        if notes_slide and notes_slide.notes_text_frame:
            notes_text = notes_slide.notes_text_frame.text.strip()
            notes_length = len(notes_text)
        else:
            notes_length = 0
            notes_text = ''
        if notes_length < min_length:
            return 0.0
        if expected_content:
            notes_normalized = notes_text.lower().strip()
            expected_normalized = expected_content.lower().strip()
            similarity = difflib.SequenceMatcher(None, notes_normalized, expected_normalized).ratio()
            key_terms = ['pass', '50%', 'overall grade', 'final exam grade']
            key_terms_present = sum((1 for term in key_terms if term.lower() in notes_normalized))
            if similarity >= 0.8 or key_terms_present >= 3:
                return 1.0
            else:
                return 0.0
        return 1.0
    except Exception as e:
        return 0.0

