def check_zoom_level__d32e355a(zoom_data, rule):
    """Check if Chrome zoom level matches expected value.

    Args:
        zoom_data: Dict with 'default_zoom_level' key from getter
        rule: Dict with comparison rules

    Returns:
        float: 1.0 if matches, 0.0 otherwise
    """
    actual_zoom = zoom_data.get('default_zoom_level', 0.0)
    if rule['type'] == 'value':
        expected = rule['value']
        return 1.0 if actual_zoom == expected else 0.0
    elif rule['type'] == 'range':
        min_val = rule['min']
        max_val = rule['max']
        return 1.0 if min_val <= actual_zoom <= max_val else 0.0
    else:
        logger.error(f"Unknown rule type: {rule['type']}")
        return 0.0

def check_acl_award_papers__6438f12d4b538ab3a43f23196d8c2df2(result, expected, **options):
    """Verify ACL Best Long Paper Award winners are correctly recorded.

    Args:
        result: List of paper dicts from getter
        expected: Dict with 'papers' list containing expected award winners
        **options: Additional options

    Returns:
        float: Score based on correctness of recorded papers (0.0-1.0)
    """
    if not result:
        return 0.0
    expected_papers = expected.get('papers', [])
    if not expected_papers:
        return 0.0
    if len(result) != len(expected_papers):
        count_score = min(len(result), len(expected_papers)) / len(expected_papers) * 0.2
    else:
        count_score = 0.25
    year_score = 0.0
    title_score = 0.0
    author_score = 0.0
    pdf_score = 0.0
    total_expected = len(expected_papers)
    for exp_paper in expected_papers:
        exp_year = str(exp_paper.get('year', '')).strip()
        matched = None
        for res_paper in result:
            if str(res_paper.get('year', '')).strip() == exp_year:
                matched = res_paper
                break
        if matched:
            year_score += 1.0 / total_expected
            exp_title = exp_paper.get('title', '').strip().lower()
            res_title = matched.get('title', '').strip().lower()
            if exp_title and res_title:
                if exp_title in res_title or res_title in exp_title:
                    title_score += 1.0 / total_expected
            exp_authors = exp_paper.get('authors', '').strip().lower()
            res_authors = matched.get('authors', '').strip().lower()
            if res_authors:
                has_comma = ',' in res_authors
                exp_author_list = [a.strip() for a in exp_authors.split(',')]
                author_match_count = 0
                for exp_author in exp_author_list:
                    if exp_author and exp_author in res_authors:
                        author_match_count += 1
                if has_comma:
                    author_partial = 0.5 / total_expected
                    if author_match_count >= len(exp_author_list) * 0.5:
                        author_partial += 0.5 / total_expected
                    author_score += author_partial
            exp_pdf = exp_paper.get('pdf', '').strip()
            res_pdf = matched.get('pdf', '').strip()
            if exp_pdf and res_pdf and (exp_pdf in res_pdf):
                pdf_score += 1.0 / total_expected
    final_score = count_score + year_score * 0.2 + title_score * 0.25 + author_score * 0.2 + pdf_score * 0.1
    return min(final_score, 1.0)

def check_tetris_rotate_fix__d0091276(result, expected, **options):
    """Check if rotate() method contains required code patterns with proper control flow.

    Args:
        result: dict of filename -> file content
        expected: dict with required patterns

    Returns:
        float: Score 0.0-1.0
    """
    tetris_content = result.get('tetris.py')
    if not tetris_content:
        return 0.0
    lines = tetris_content.split('\n')
    in_rotate = False
    rotate_code = []
    indent_level = None
    for line in lines:
        if 'def rotate(self):' in line:
            in_rotate = True
            indent_level = len(line) - len(line.lstrip())
            rotate_code.append(line)
        elif in_rotate:
            current_indent = len(line) - len(line.lstrip())
            if line.strip() and current_indent <= indent_level:
                break
            rotate_code.append(line)
    if not rotate_code:
        return 0.0
    rotate_text = '\n'.join(rotate_code)
    code_lines = []
    for line in rotate_code:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        code_part = line.split('#')[0]
        code_lines.append(code_part)
    code_text = '\n'.join(code_lines)
    old_rotation_pattern = 'old_rotation\\s*=\\s*self\\.block\\.rotation'
    has_old_rotation = bool(re.search(old_rotation_pattern, code_text))
    has_intersect_call = 'self.intersect()' in code_text
    restore_pattern = 'self\\.block\\.rotation\\s*=\\s*old_rotation'
    has_restoration = bool(re.search(restore_pattern, code_text))
    if not (has_old_rotation and has_intersect_call and has_restoration):
        return 0.0
    old_rotation_pos = code_text.find('old_rotation')
    rotation_change_pos = code_text.find('self.block.rotation', old_rotation_pos + len('old_rotation'))
    if rotation_change_pos == -1 or old_rotation_pos >= rotation_change_pos:
        return 0.4
    intersect_pos = code_text.find('self.intersect()')
    if intersect_pos == -1 or intersect_pos <= rotation_change_pos:
        return 0.5
    if_intersect_pattern = 'if\\s+self\\.intersect\\(\\)\\s*:\\s*[^\\n]*self\\.block\\.rotation\\s*=\\s*old_rotation'
    if_intersect_multiline = 'if\\s+self\\.intersect\\(\\)\\s*:'
    if re.search(if_intersect_pattern, code_text):
        return 1.0
    elif re.search(if_intersect_multiline, code_text):
        if_match = re.search(if_intersect_multiline, code_text)
        if if_match:
            text_after_if = code_text[if_match.end():]
            restoration_after_if = re.search(restore_pattern, text_after_if[:500])
            if restoration_after_if:
                return 1.0
    return 0.7

def check_background_present__23bfac54(result_state, expected_state, **options):
    """
    Check if the background image matches the reference frame from the video.

    Args:
        result_state: Dictionary from getter with keys:
            - 'background_image_path': Path to extracted background image
            - 'reference_frame_path': Path to extracted reference frame
        expected_state: Dictionary with key 'similarity_threshold' (float, default 0.8)
        **options: Additional options

    Returns:
        float: Score (1.0 if images are similar enough, 0.0 otherwise)
    """
    background_image_path = result_state.get('background_image_path')
    reference_frame_path = result_state.get('reference_frame_path')
    if not background_image_path or not reference_frame_path:
        return 0.0
    threshold = expected_state.get('similarity_threshold', 0.8)
    try:
        image1 = Image.open(background_image_path).convert('L')
        image2 = Image.open(reference_frame_path).convert('L')
        image1_size = image1.size
        image2_size = image2.size
        new_size = min(image1_size, image2_size)
        image1 = image1.resize(new_size, Image.Resampling.LANCZOS)
        image2 = image2.resize(new_size, Image.Resampling.LANCZOS)
        image1_array = np.array(image1)
        image2_array = np.array(image2)
        similarity_index = ssim(image1_array, image2_array)
        if similarity_index >= threshold:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        return 0.0

