def check_words_starting_whs_strike__36a8bf68(file_path1, file_path2, **kwargs):
    """
    Check if words starting with 'w', 'h', or 's' have strikethrough formatting.

    Args:
        file_path1: Path to result file
        file_path2: Path to expected file (unused)
        **kwargs: Additional options

    Returns:
        float: 1.0 if strikethrough is correctly applied, 0.0 otherwise
    """
    if not file_path1:
        return 0.0
    try:
        document = Document(file_path1)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    target_starts = ['w', 'h', 's']
    for table in document.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        word = run.text.strip()
                        if word:
                            starts_with_target = word[0].lower() in target_starts
                            if starts_with_target:
                                if not run.font.strike:
                                    logger.info(f"Word starting with w/h/s: '{word}' does not have strikethrough")
                                    return 0.0
                            elif run.font.strike:
                                logger.info(f"Word not starting with w/h/s: '{word}' should not have strikethrough")
                                return 0.0
    return 1.0

