def check_chart_exists__dee656f9(result_state: Dict[str, Any], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if a bar chart with correct data source exists.

    Verifies:
    1. Chart type is bar/barChart/col (bar charts)
    2. Data range includes column G, rows 20-31 (G20:G31)
    3. Categories show months (12 values expected)

    Args:
        result_state: Dict from getter with 'has_chart' and 'charts' (list of chart properties)
        expected_state: Expected dict with 'has_chart' key (bool)
        **options: Additional options

    Returns:
        float: Score (1.0 if valid bar chart found with correct data, 0.0 otherwise)
    """
    result_has_chart = result_state.get('has_chart', False)
    expected_has_chart = expected_state.get('has_chart', False)
    logger.info(f'Checking chart: result={result_has_chart}, expected={expected_has_chart}')
    if not expected_has_chart:
        return 1.0 if not result_has_chart else 0.0
    if not result_has_chart:
        logger.info('No chart found, but chart was expected')
        return 0.0
    charts = result_state.get('charts', [])
    if not charts:
        logger.info('No chart data extracted')
        return 0.0
    for chart in charts:
        chart_type = chart.get('type', '').lower()
        data_ranges = chart.get('data_ranges', [])
        category_ranges = chart.get('category_ranges', [])
        logger.info(f'Evaluating chart - Type: {chart_type}, Data ranges: {data_ranges}, Category ranges: {category_ranges}')
        is_bar_chart = any((keyword in chart_type for keyword in ['bar', 'col']))
        if not is_bar_chart:
            logger.info(f"Chart type '{chart_type}' is not a bar/column chart")
            continue
        valid_data_range = False
        for data_range in data_ranges:
            if 'G' in data_range.upper():
                if re.search('[G]\\$?2[0-9]', data_range.upper()) and re.search('[G]\\$?3[0-1]', data_range.upper()):
                    valid_data_range = True
                    logger.info(f'Valid data range found: {data_range}')
                    break
        if not valid_data_range:
            logger.info(f'Data ranges {data_ranges} do not include G20:G31')
            continue
        valid_categories = False
        for cat_range in category_ranges:
            if re.search('2[0-9]', cat_range) and re.search('3[0-1]', cat_range):
                valid_categories = True
                logger.info(f'Valid category range found: {cat_range}')
                break
        if not valid_categories:
            logger.info(f'Category ranges {category_ranges} do not match expected monthly data (rows 20-31)')
            logger.info('Accepting chart despite category range uncertainty')
        logger.info('Valid bar chart with correct data range found!')
        return 1.0
    logger.info('No valid bar chart with correct data range (G20:G31) found')
    return 0.0

def check_delimiter_format_75ba68b3(vm_file, expected, **options):
    """Check if file uses correct delimiter and has minimum rows.

    Args:
        vm_file: File path string from vm_file getter
        expected: Expected rules dict with 'delimiter' and 'min_rows'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if vm_file is None:
        return 0.0
    try:
        with open(vm_file, 'rb') as f:
            content = f.read().decode('utf-8')
        delimiter = expected.get('delimiter', '|')
        min_rows = expected.get('min_rows', 0)
        lines = content.strip().split('\n')
        if not lines:
            return 0.0
        score = 0.0
        if len(lines) >= min_rows:
            score += 0.4
        lines_with_delimiter = sum((1 for line in lines if delimiter in line))
        delimiter_ratio = lines_with_delimiter / len(lines)
        if delimiter_ratio >= 0.95:
            score += 0.4
        if len(lines) >= 2:
            first_line_delimiters = lines[0].count(delimiter)
            last_line_delimiters = lines[-1].count(delimiter)
            middle_idx = len(lines) // 2
            middle_line_delimiters = lines[middle_idx].count(delimiter)
            if first_line_delimiters == last_line_delimiters == middle_line_delimiters:
                score += 0.2
        return score
    except Exception as e:
        return 0.0

