def check_function_renamed__6e2d60633a06e0b46134679da45f671c(result: Dict[str, int], expected: Dict[str, Any], **options) -> float:
    """Check if function was renamed correctly.

    Args:
        result: Dict with function definition counts from getter
        expected: Dict with expected rules:
            - old_function: Name of function that should be replaced (count should be 0)
            - new_function: Name of new function (count should be 1)

    Returns:
        float: 1.0 if both conditions met (old func = 0, new func = 1), 0.5 if only one met, 0.0 if neither
    """
    if not result:
        return 0.0
    old_func = expected.get('old_function', '')
    new_func = expected.get('new_function', '')
    old_count = result.get(old_func, -1)
    new_count = result.get(new_func, -1)
    score = 0.0
    if old_count == 0:
        score += 0.5
    if new_count == 1:
        score += 0.5
    return score

