def check_bib_has_dblp_keys__7b4ca847(result, expected, **options):
    """Check if bibtex contains the required SQL papers from DBLP conference versions.

    Args:
        result: Dict with 'entries' (list of entry dicts) and 'raw_content' (str)
        expected: Dict with 'min_keys' for minimum DBLP entries
        **options: Additional options

    Returns:
        float: 1.0 if all requirements met, 0.0 otherwise
    """
    import re
    entries = result.get('entries', [])
    raw_content = result.get('raw_content', '')
    min_keys = expected.get('min_keys', 3)
    if len(entries) < min_keys:
        return 0.0
    required_papers = ['spider', 'sparc', 'cosql']
    found_papers = set()
    for entry in entries:
        key = entry.get('key', '').lower()
        content = entry.get('content', '').lower()
        for paper in required_papers:
            if paper in key or paper in content:
                found_papers.add(paper)
    if len(found_papers) < 3:
        return 0.0
    has_arxiv = False
    has_conference = False
    for entry in entries:
        key = entry.get('key', '')
        is_required_paper = any((paper in key.lower() or paper in entry.get('content', '').lower() for paper in required_papers))
        if is_required_paper:
            if 'journals/corr/abs-' in key or 'arxiv' in key.lower():
                has_arxiv = True
            if 'conf/' in key:
                has_conference = True
    if has_arxiv and (not has_conference):
        return 0.0
    entry_pattern = '\\}[\\s]*\\n[\\s]*\\n[\\s]*@'
    has_blank_lines = bool(re.search(entry_pattern, raw_content))
    if len(entries) > 1 and (not has_blank_lines):
        return 0.0
    return 1.0

def check_alphabetically_sorted__a135a28c(result, expected, **options):
    """Check if data is sorted alphabetically by First Name with row integrity maintained.

    Args:
        result: Dict with 'first_names', 'order_ids', and 'full_rows'
        expected: Not used (we only check sorting, not specific values)
        **options: 'case_sensitive' (default False)

    Returns:
        float: 1.0 if sorted alphabetically with row integrity, 0.0 otherwise
    """
    if not result or not isinstance(result, dict):
        return 0.0
    first_names = result.get('first_names', [])
    order_ids = result.get('order_ids', [])
    full_rows = result.get('full_rows', [])
    if not first_names or len(first_names) < 2:
        return 0.0
    if len(first_names) != len(order_ids) or len(first_names) != len(full_rows):
        return 0.0
    case_sensitive = options.get('case_sensitive', False)
    if not case_sensitive:
        compare_list = [str(s).lower() for s in first_names]
    else:
        compare_list = [str(s) for s in first_names]
    for i in range(len(compare_list) - 1):
        if compare_list[i] > compare_list[i + 1]:
            return 0.0
    name_to_order_ids = expected.get('name_to_order_ids', {})
    if not name_to_order_ids:
        return 0.0
    for (i, (name, order_id)) in enumerate(zip(first_names, order_ids)):
        name_key = name.lower() if not case_sensitive else name
        expected_order_ids = name_to_order_ids.get(name_key, [])
        if order_id not in expected_order_ids:
            return 0.0
    return 1.0

def check_rotation_reversal__306eee0f03cac16a10ee876f2eb69043(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if rotate() properly implements rotation reversal on collision.

    Args:
        result: Dict from getter containing rotation reversal analysis
        expected: Dict with expected properties (from rules)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
            - 0.20: Valid syntax and method exists
            - 0.40: Method is longer than original (indicating fix attempt)
            - 0.60: Has rotation backup mechanism
            - 0.80: Has collision detection after rotation
            - 1.00: Rotation restoration is conditional (inside if statement)
    """
    score = 0.0
    if not result.get('valid_syntax', False):
        return 0.0
    score += 0.2
    if result.get('rotate_method_length', 0) > 2:
        score += 0.2
    if result.get('has_rotation_backup', False):
        score += 0.2
    if result.get('has_collision_check', False):
        score += 0.2
    if result.get('conditional_revert', False):
        score += 0.2
    return min(1.0, score)

def check_word_count_and_note__f3c1df34(result, expected, **options):
    """Check if word count meets minimum requirement AND note was added (conditional).

    This metric enforces the conditional instruction:
    "If word count >= 8000, THEN add note and save file"

    Scoring logic:
    - If word_count < 8000: score = 0.0 (requirement not met, no action needed)
    - If word_count >= 8000 AND note exists: score = 1.0 (full completion)
    - If word_count >= 8000 BUT no note: score = 0.3 (partial - found requirement but didn't complete conditional action)

    Args:
        result: Dict with 'word_count' (int) and 'last_paragraph' (str)
        expected: Expected requirements (dict with 'min_words' key)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    min_words = expected.get('min_words', 0)
    word_count = result.get('word_count', 0)
    last_paragraph = result.get('last_paragraph', '')
    pattern = 'word\\s+count\\s+requirement\\s+met\\s*:\\s*\\d+\\s+words'
    note_exists = bool(re.search(pattern, last_paragraph, re.IGNORECASE))
    if word_count < min_words:
        return 0.0
    elif word_count >= min_words and note_exists:
        return 1.0
    else:
        return 0.3

