def check_snake_color_change__ca45bb58(vm_file_result: List[Optional[str]], rules: Dict, **options) -> float:
    """
    Check if the snake color has been changed from GREEN to BLUE.

    This function verifies:
    1. BLUE constant is defined in settings.py with RGB value (0, 0, 255)
    2. Snake's self.color in __init__ is set to BLUE or (0, 0, 255)

    Args:
        vm_file_result (List[Optional[str]]): List of file paths returned by get_vm_file with multi=true
                                               Order matches dest array: ['food.py', 'main.py', 'settings.py', 'snake.py']
        rules (Dict): Dictionary containing expected values
                      Expected key: 'color_rgb' with value [0, 0, 255]
        **options: Additional options (unused)

    Returns:
        float: 1.0 if snake color is correctly changed to blue, 0.0 otherwise
    """
    expected_color_rgb = rules.get('color_rgb')
    if expected_color_rgb is None:
        return 0.0
    expected_color_tuple = tuple(expected_color_rgb) if isinstance(expected_color_rgb, list) else expected_color_rgb
    dest_names = ['food.py', 'main.py', 'settings.py', 'snake.py']
    if not vm_file_result or len(vm_file_result) < len(dest_names):
        return 0.0
    file_dict = dict(zip(dest_names, vm_file_result))
    settings_file_path = file_dict.get('settings.py')
    snake_file_path = file_dict.get('snake.py')
    if not settings_file_path or not snake_file_path:
        return 0.0
    if not os.path.exists(settings_file_path) or not os.path.exists(snake_file_path):
        return 0.0
    try:
        with open(settings_file_path, 'r') as f:
            settings_code = f.read()
        settings_tree = ast.parse(settings_code)
        blue_defined = False
        for node in ast.walk(settings_tree):
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name) and target.id == 'BLUE':
                        if isinstance(node.value, ast.Tuple):
                            values = []
                            for elt in node.value.elts:
                                if isinstance(elt, ast.Constant):
                                    values.append(elt.value)
                                elif isinstance(elt, ast.Num):
                                    values.append(elt.n)
                            if tuple(values) == expected_color_tuple:
                                blue_defined = True
                                break
        if not blue_defined:
            return 0.0
        with open(snake_file_path, 'r') as f:
            snake_code = f.read()
        snake_tree = ast.parse(snake_code)
        color_set_correctly = False
        for node in ast.walk(snake_tree):
            if isinstance(node, ast.ClassDef) and node.name == 'Snake':
                for item in node.body:
                    if isinstance(item, ast.FunctionDef) and item.name == '__init__':
                        for stmt in ast.walk(item):
                            if isinstance(stmt, ast.Assign):
                                for target in stmt.targets:
                                    if isinstance(target, ast.Attribute):
                                        if isinstance(target.value, ast.Name) and target.value.id == 'self' and (target.attr == 'color'):
                                            if isinstance(stmt.value, ast.Name) and stmt.value.id == 'BLUE':
                                                color_set_correctly = True
                                                break
                                            elif isinstance(stmt.value, ast.Tuple):
                                                values = []
                                                for elt in stmt.value.elts:
                                                    if isinstance(elt, ast.Constant):
                                                        values.append(elt.value)
                                                    elif isinstance(elt, ast.Num):
                                                        values.append(elt.n)
                                                if tuple(values) == expected_color_tuple:
                                                    color_set_correctly = True
                                                    break
                                if color_set_correctly:
                                    break
                            if color_set_correctly:
                                break
                    if color_set_correctly:
                        break
            if color_set_correctly:
                break
        if blue_defined and color_set_correctly:
            return 1.0
        else:
            return 0.0
    except SyntaxError:
        return 0.0
    except Exception:
        return 0.0

def check_tetris_rotate_fix__0e016e1b(result, expected, **options):
    """Checks both implementation correctness and functional behavior of rotate() method fix.

    Args:
        result: dict of filename -> file content
        expected: dict with test scenario

    Returns:
        float: Score 0.0-1.0
    """
    import tempfile
    import os
    import sys
    import importlib.util
    import ast
    import re
    files = {'tetris.py': result.get('tetris.py'), 'block.py': result.get('block.py'), 'settings.py': result.get('settings.py')}
    for (name, content) in files.items():
        if not content:
            return 0.0
    tetris_content = files['tetris.py']
    try:
        tree = ast.parse(tetris_content)
    except SyntaxError:
        print('Syntax error in tetris.py')
        return 0.0
    rotate_method_found = False
    rotate_method_code = None
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef):
            for item in node.body:
                if isinstance(item, ast.FunctionDef) and item.name == 'rotate':
                    rotate_method_found = True
                    rotate_method_code = ast.get_source_segment(tetris_content, item)
                    break
            if rotate_method_found:
                break
    if not rotate_method_found:
        print('rotate() method not found in tetris.py')
        return 0.0
    if not rotate_method_code:
        rotate_pattern = 'def rotate\\(self\\):.*?(?=\\n    def |\\n\\nclass |\\Z)'
        match = re.search(rotate_pattern, tetris_content, re.DOTALL)
        if match:
            rotate_method_code = match.group(0)
        else:
            print('Could not extract rotate() method code')
            return 0.0
    has_rotation_backup = False
    has_intersect_call = False
    has_rollback_logic = False
    if re.search('old_rotation\\s*=\\s*self\\.block\\.rotation', rotate_method_code):
        has_rotation_backup = True
    if 'intersect(' in rotate_method_code or 'self.intersect()' in rotate_method_code:
        has_intersect_call = True
    if re.search('self\\.block\\.rotation\\s*=\\s*old_rotation', rotate_method_code):
        has_rollback_logic = True
    if not (has_rotation_backup and has_intersect_call and has_rollback_logic):
        print(f'Static code analysis failed: backup={has_rotation_backup}, intersect={has_intersect_call}, rollback={has_rollback_logic}')
        return 0.0
    with tempfile.TemporaryDirectory() as tmpdir:
        for (name, content) in files.items():
            with open(os.path.join(tmpdir, name), 'w') as f:
                f.write(content)
        sys.path.insert(0, tmpdir)
        try:
            spec = importlib.util.spec_from_file_location('tetris', os.path.join(tmpdir, 'tetris.py'))
            tetris_module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(tetris_module)
            spec2 = importlib.util.spec_from_file_location('settings', os.path.join(tmpdir, 'settings.py'))
            settings_module = importlib.util.module_from_spec(spec2)
            spec2.loader.exec_module(settings_module)
            Tetris = tetris_module.Tetris
            BOARD_HEIGHT = settings_module.BOARD_HEIGHT
            BOARD_WIDTH = settings_module.BOARD_WIDTH
            test_scenario = expected.get('test_scenario', 'left_boundary')
            if test_scenario == 'left_boundary':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                while game.block.x > 0:
                    game.move(-1, 0)
                game.rotate()
                if game.intersect():
                    return 0.0
                return 1.0
            elif test_scenario == 'right_boundary':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                while game.block.x + len(game.block.shape[0]) < game.width:
                    game.move(1, 0)
                game.rotate()
                if game.intersect():
                    return 0.0
                return 1.0
            elif test_scenario == 'complete_rotation_cycle':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                for _ in range(4):
                    game.rotate()
                    if game.intersect():
                        return 0.0
                return 1.0
            elif test_scenario == 'comprehensive':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                while game.block.x > 0:
                    game.move(-1, 0)
                rotation_before = game.block.rotation
                game.rotate()
                if game.intersect():
                    return 0.0
                game.new_block()
                while game.block.x + len(game.block.shape[0]) < game.width:
                    game.move(1, 0)
                game.rotate()
                if game.intersect():
                    return 0.0
                game.new_block()
                game.block.x = 0
                old_rot = game.block.rotation
                game.rotate()
                if game.intersect():
                    return 0.0
                return 1.0
            elif test_scenario == 'full_game_flow':
                game = Tetris(BOARD_HEIGHT, BOARD_WIDTH)
                game.new_block()
                game.move(-1, 0)
                game.rotate()
                game.move(1, 0)
                game.rotate()
                game.go_down()
                if game.intersect():
                    return 0.0
                return 1.0
            return 0.0
        except Exception as e:
            print(f'Test execution error: {e}')
            return 0.0
        finally:
            sys.path.remove(tmpdir)

