def check_background_present__daf96dfa(result, expected, **options):
    """Check if the slide has a background image from the video at the correct timestamp.

    Args:
        result: Dict from getter with 'has_background' boolean and 'image_name' string
        expected: Dict with expected values (e.g., {'has_background': True})
        **options: Additional comparison options

    Returns:
        float: 1.0 if match and image is from video at 00:22, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    result_has_bg = result.get('has_background', False)
    expected_has_bg = expected.get('has_background', False)
    if result_has_bg != expected_has_bg:
        return 0.0
    if not expected_has_bg:
        return 1.0
    image_name = result.get('image_name', '')
    if not image_name:
        return 0.0
    image_name_lower = image_name.lower()
    pattern1 = '00[_\\-\\s]?22'
    pattern2 = '(^|[_\\-\\s])0*22([_\\-\\s\\.]|$)'
    is_from_landscape_video = 'landscape' in image_name_lower
    has_timestamp_pattern = bool(re.search(pattern1, image_name_lower))
    has_frame_22 = bool(re.search(pattern2, image_name_lower))
    if has_timestamp_pattern:
        return 1.0
    if is_from_landscape_video and has_frame_22:
        return 1.0
    frame_keywords = ['frame', 'snap', 'capture', 'screenshot', 'vlc']
    has_frame_keyword = any((keyword in image_name_lower for keyword in frame_keywords))
    if has_frame_keyword and has_frame_22:
        return 1.0
    return 0.0

