def check_tsv_comprehensive__50173021406cfda3b24cebb95d2a9b1c(result, expected, **options):
    """Comprehensively verify TSV file export completeness.

    This metric checks:
    - File exists and has proper tab-delimited format
    - Row and column counts match expected structure (strict thresholds)
    - Multiple strategic cells across different regions match expected values
    - Verifies diverse cell coverage to ensure complete export (not partial)

    Args:
        result: Dict from comprehensive getter with cells, row_count, col_count
        expected: Dict with expected cells, min_rows, min_cols
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None:
        return 0.0
    if not isinstance(result, dict):
        return 0.0
    if not result.get('file_exists', False):
        return 0.0
    if not result.get('has_tabs', False):
        return 0.0
    expected_min_rows = expected.get('min_rows', 0)
    if result.get('row_count', 0) < expected_min_rows:
        return 0.0
    expected_min_cols = expected.get('min_cols', 0)
    if result.get('col_count', 0) < expected_min_cols:
        return 0.0
    result_cells = result.get('cells', {})
    if len(result_cells) < 4:
        return 0.0
    cell_keys = list(result_cells.keys())
    row_indices = set()
    col_indices = set()
    for cell_key in cell_keys:
        if '_' in cell_key:
            parts = cell_key.split('_')
            if len(parts) == 2:
                try:
                    row_idx = int(parts[0])
                    col_idx = int(parts[1])
                    row_indices.add(row_idx)
                    col_indices.add(col_idx)
                except ValueError:
                    pass
    if len(row_indices) < 3:
        return 0.0
    if len(col_indices) < 2:
        return 0.0
    expected_cells = expected.get('cells', {})
    for (cell_key, expected_value) in expected_cells.items():
        result_value = result_cells.get(cell_key)
        if result_value is None:
            return 0.0
        result_str = str(result_value).strip()
        expected_str = str(expected_value).strip()
        if result_str == expected_str:
            continue
        try:
            result_num = float(result_str)
            expected_num = float(expected_str)
            if abs(result_num - expected_num) < 0.01:
                continue
        except (ValueError, TypeError):
            pass
        return 0.0
    non_empty_count = sum((1 for v in result_cells.values() if v and str(v).strip()))
    if len(result_cells) > 0:
        non_empty_ratio = non_empty_count / len(result_cells)
        if non_empty_ratio < 0.6:
            return 0.0
    return 1.0

