def check_keyword_exists__f7a262b5(result: List[Dict[str, str]], expected: dict, **options) -> float:
    """Check if at least one paper entry contains the keyword in title, has a valid arXiv link,
    and was published in the specified month/year.

    Args:
        result: List of paper dicts with 'title', 'arxiv_link', and 'publication_date'
        expected: Expected rules dict with 'keyword', 'month', and 'year'
        **options: Additional comparison options

    Returns:
        1.0 if a valid paper matching all criteria is found, 0.0 otherwise
    """
    keyword = expected.get('keyword', '').lower()
    expected_month = expected.get('month', 'September').lower()
    expected_year = expected.get('year', '2023')
    if not keyword:
        return 0.0
    for paper in result:
        title = paper.get('title', '').lower()
        arxiv_link = paper.get('arxiv_link', '')
        pub_date = paper.get('publication_date', '')
        if keyword not in title:
            continue
        if not arxiv_link:
            continue
        arxiv_link_lower = arxiv_link.lower()
        has_valid_arxiv = 'arxiv.org' in arxiv_link_lower or 'arxiv:' in arxiv_link_lower or re.search('\\d{4}\\.\\d{4,5}', arxiv_link)
        if not has_valid_arxiv:
            continue
        if not pub_date:
            continue
        pub_date_lower = pub_date.lower()
        date_matches = expected_month in pub_date_lower and expected_year in pub_date_lower or ('sep' in pub_date_lower and expected_year in pub_date_lower) or ('09' in pub_date and expected_year in pub_date) or ('9' in pub_date and expected_year in pub_date and ('2023-09' in pub_date)) or ('2023-9-' in pub_date) or ('-09-' in pub_date and expected_year in pub_date)
        if not date_matches:
            continue
        return 1.0
    return 0.0

