def check_contains_keyword__e38643bd(result: Optional[str], expected: Dict[str, Any], **options) -> float:
    """Check if text contains required keywords with comprehensive validation.

    This function validates that the extracted content:
    1. Contains Apple HIG-specific accessibility terms
    2. Has sufficient content length
    3. Includes multiple required keywords (not just one)
    4. Returns partial scoring based on quality

    Args:
        result: Actual text content from getter
        expected: Rules dict with 'keywords' key (list of keywords)
        **options: Additional options

    Returns:
        Score from 0.0 to 1.0 based on content quality and completeness
    """
    if result is None:
        return 0.0
    MIN_CONTENT_LENGTH = 200
    basic_keywords = expected.get('keywords', [])
    apple_hig_keywords = ['voiceover', 'dynamic type', 'accessibility features', 'ios', 'screen reader', 'color contrast', 'assistive', 'reduce motion', 'switch control', 'hearing', 'vision', 'motor']
    result_lower = result.lower()
    word_count = len(result.split())
    if word_count < MIN_CONTENT_LENGTH:
        return 0.0
    basic_found = 0
    for keyword in basic_keywords:
        if keyword.lower() in result_lower:
            basic_found += 1
    if basic_found == 0:
        return 0.0
    apple_keywords_found = 0
    for keyword in apple_hig_keywords:
        if keyword.lower() in result_lower:
            apple_keywords_found += 1
    if apple_keywords_found >= 4:
        return 1.0
    elif apple_keywords_found >= 3:
        return 0.8
    elif apple_keywords_found >= 2:
        return 0.6
    elif apple_keywords_found >= 1:
        return 0.4
    else:
        return 0.2

