def check_rgb_color__5d0b7a3b(result, expected, **options):
    """Compare RGB color tuples.

    Args:
        result: Tuple of (r, g, b) from getter
        expected: Expected RGB tuple from rules
        **options: Additional options (tolerance for fuzzy matching)

    Returns:
        float: 1.0 if colors match, 0.0 otherwise
    """
    if result is None:
        return 0.0
    expected_rgb = expected.get('rules', {}).get('rgb', (255, 0, 0))
    tolerance = options.get('color_tolerance', 0)
    if tolerance == 0:
        return 1.0 if result == tuple(expected_rgb) else 0.0
    else:
        (r1, g1, b1) = result
        (r2, g2, b2) = expected_rgb
        distance = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** 0.5
        max_distance = tolerance
        return 1.0 if distance <= max_distance else 0.0

def check_subject_contains_count__04c070c4(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Check if accessibility tree contains subject field with expected count.

    Args:
        result: Accessibility tree XML
        expected: Dict with "count" key specifying the expected number
        **options: Additional options

    Returns:
        float: 1.0 if subject contains the count, 0.0 otherwise
    """
    if result is None:
        logger.warning('Accessibility tree result is None')
        return 0.0
    count = expected.get('count', 0)
    subject_text = None
    subject_pattern = re.compile('name=["\\\']Subject:\\s*([^"\\\']+)["\\\']', re.IGNORECASE)
    match = subject_pattern.search(result)
    if match:
        subject_text = match.group(1)
        logger.info(f'Found subject field using pattern 1: {subject_text}')
    if not subject_text:
        lines = result.split('\n')
        for (i, line) in enumerate(lines):
            if 'subject' in line.lower() and 'role=' in line:
                name_match = re.search('name=["\\\']([^"\\\']+)["\\\']', line)
                if name_match:
                    candidate = name_match.group(1)
                    if candidate.lower() != 'subject' and len(candidate) > 3:
                        subject_text = candidate
                        logger.info(f'Found subject field using pattern 2: {subject_text}')
                        break
    if not subject_text:
        text_pattern = re.compile('role=["\\\'](?:text|entry)["\\\'][^>]*name=["\\\']([^"\\\']{10,})["\\\']', re.IGNORECASE)
        matches = text_pattern.findall(result)
        for match_text in matches:
            if match_text.lower() not in ['subject', 'to', 'from', 'cc', 'bcc'] and 'reminder' in match_text.lower():
                subject_text = match_text
                logger.info(f'Found subject field using pattern 3: {subject_text}')
                break
    if not subject_text:
        logger.warning('Could not find subject field in accessibility tree')
        return 0.0
    logger.info(f'Extracted subject field text: {subject_text}')
    count_patterns = [f'\\b{count}\\s+student', f'\\b{count}\\s+unpaid', f'unpaid.*?\\b{count}\\b', f'\\b{count}\\b.*?student', f'count.*?\\b{count}\\b', f'\\b{count}\\b']
    for pattern in count_patterns:
        if re.search(pattern, subject_text, re.IGNORECASE):
            logger.info(f'Found count {count} in subject field with pattern: {pattern}')
            return 1.0
    logger.info(f'Count {count} not found in subject field. Subject was: {subject_text}')
    return 0.0

