def check_acceptance_rates__e3c84456(actual_file_path, expected):
    """Check if acceptance rates are filled in correctly for conferences.

    Args:
        actual_file_path: Path to the Excel file with filled acceptance rate data
        expected: Expected configuration with acceptance rate values

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('expected_values', [])
    wb = openpyxl.load_workbook(actual_file_path, data_only=True)
    sheet = wb.active
    actual_values = []
    for row in sheet['C2:C22']:
        for cell in row:
            actual_values.append(cell.value)
    score = 0.0
    total_checks = len(expected_values)
    if total_checks == 0:
        return 0.0
    for i in range(total_checks):
        try:
            expected_val = expected_values[i]
            actual_val = actual_values[i]
            if actual_val is None:
                continue
            actual_num = None
            if isinstance(actual_val, str):
                if '%' in actual_val:
                    try:
                        actual_num = float(actual_val.replace('%', '').strip())
                    except ValueError:
                        pass
                else:
                    try:
                        actual_num = float(actual_val)
                        if actual_num < 1:
                            actual_num = actual_num * 100
                    except ValueError:
                        pass
            elif isinstance(actual_val, (int, float)):
                actual_num = float(actual_val)
                if actual_num < 1:
                    actual_num = actual_num * 100
            if actual_num is not None:
                if abs(actual_num - expected_val) <= 3.0:
                    score += 1.0 / total_checks
        except (IndexError, KeyError, TypeError) as e:
            logger.debug(f'Error checking index {i}: {e}')
            continue
    return round(score, 3)

