def check_column_filled__14390480(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if all cells in a column are filled with correct values from lookup table.

    Args:
        result: Dict with 'all_filled', 'values', 'head_offices', 'lookup_table' from getter
        expected: Dict with 'require_all_filled' (bool) and 'verify_lookup' (bool)
        **options: Additional options (not used)

    Returns:
        float: 1.0 if requirement met, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    require_all_filled = expected.get('require_all_filled', True)
    verify_lookup = expected.get('verify_lookup', True)
    all_filled = result.get('all_filled', False)
    if require_all_filled and (not all_filled):
        return 0.0
    if verify_lookup:
        values = result.get('values', [])
        head_offices = result.get('head_offices', [])
        lookup_table = result.get('lookup_table', {})
        if not lookup_table:
            return 1.0 if all_filled else 0.0
        correct_count = 0
        total_count = len(values)
        for (i, (value, head_office)) in enumerate(zip(values, head_offices)):
            if value is None or head_office is None:
                continue
            expected_officer = lookup_table.get(head_office)
            if expected_officer and value == expected_officer:
                correct_count += 1
            elif expected_officer is None:
                if value:
                    correct_count += 1
        if total_count > 0 and correct_count == total_count:
            return 1.0
        else:
            return 0.0
    return 1.0 if all_filled else 0.0

def check_char_counts__0cb0f902(result: Dict, expected: Dict, **opts) -> float:
    """
    Check character counts in xlsx file.

    This metric validates data extracted from a vm_file by the corresponding getter.
    The getter (get_xlsx_char_counts__0cb0f902) fetches the Excel file from the VM,
    reads cells A2-A6 for names and B2-B6 for character counts, and returns them
    as a dict. This metric then compares those extracted values against expected values.

    Args:
        result: Dict with 'names' and 'lengths' keys from getter (vm_file data)
        expected: Dict with 'expected_names' and 'expected_lengths' keys
        **opts: Additional options

    Returns:
        float: Score (0.0-1.0) based on name and length matches
              40% weight for name matching, 60% weight for length matching
    """
    s = 0.0
    en = expected.get('expected_names', [])
    rn = result.get('names', [])
    el = expected.get('expected_lengths', [])
    rl = result.get('lengths', [])
    if len(rn) == len(en) and len(en) > 0:
        name_matches = sum((1 for i in range(len(en)) if i < len(rn) and rn[i].lower().strip() == en[i].lower().strip()))
        s += 0.4 * name_matches / len(en)
    if len(rl) == len(el) and len(el) > 0:
        length_matches = 0
        for i in range(len(el)):
            if i < len(rl):
                if isinstance(rl[i], (int, float)) and rl[i] >= 0 and (rl[i] == el[i]):
                    length_matches += 1
                elif rl[i] is None:
                    pass
        s += 0.6 * length_matches / len(el)
    return s

