def check_ext_manifest__86d1adf05912c94007ba506be4096d7e(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the extension manifest data matches expected values.

    Args:
        result: Dict containing manifest data from getter
        expected: Dict with expected manifest fields (e.g., 'manifest_version', 'version', 'name')
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on how many fields match
    """
    if not result:
        logger.info('Extension manifest not found')
        return 0.0
    fields_to_check = []
    if 'manifest_version' in expected:
        fields_to_check.append('manifest_version')
    if 'version' in expected:
        fields_to_check.append('version')
    if 'name' in expected:
        fields_to_check.append('name')
    if not fields_to_check:
        logger.warning('No fields specified to check in expected')
        return 0.0
    matched = 0
    total = len(fields_to_check)
    for field in fields_to_check:
        expected_value = expected.get(field)
        actual_value = result.get(field)
        if actual_value == expected_value:
            matched += 1
            logger.info(f"Field '{field}' matches: {actual_value}")
        else:
            logger.info(f"Field '{field}' mismatch. Expected: {expected_value}, Got: {actual_value}")
    score = matched / total
    logger.info(f'Manifest check score: {score} ({matched}/{total} fields matched)')
    return score

