def check_zip_and_contents__1a0ccf050b10545e05649e32a895cb33(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if zip file exists and contains the expected files.

    This verifies both:
    1. The zip file exists at the expected location
    2. The zip contains exactly the expected files (no more, no less)

    Args:
        result: Dict with 'zip_exists' (bool), 'zip_path' (str), and 'contents' (list of filenames)
        expected: Dict with 'expected_files' key containing list of expected filenames
        **options: Additional options

    Returns:
        1.0 if zip exists and contains exactly the expected files
        0.5 if zip exists but has wrong contents (missing or extra files)
        0.0 if zip doesn't exist
    """
    expected_files = expected.get('expected_files', [])
    if not expected_files:
        return 0.0
    if not result.get('zip_exists', False):
        return 0.0
    contents = result.get('contents', [])
    contents_set = set(contents)
    expected_set = set(expected_files)
    missing_files = expected_set - contents_set
    extra_files = contents_set - expected_set
    if not missing_files and (not extra_files):
        return 1.0
    return 0.0

def check_food_color_yellow__d82a8676(actual_files, expected, **options):
    """Check if YELLOW constant is defined and Food class uses it.

    Verifies:
    1. YELLOW = (255, 255, 0) is defined in settings.py
    2. Food class in food.py uses YELLOW specifically for self.color in __init__

    Args:
        actual_files: List of file paths from vm_file getter
        expected: Expected rules dict
        **options: Additional options

    Returns:
        float: 1.0 if both checks pass, 0.5 if only one passes, 0.0 if none pass
    """
    if not actual_files or not isinstance(actual_files, list) or len(actual_files) == 0:
        return 0.0
    file_paths = [fp for fp in actual_files if fp and isinstance(fp, str)]
    if not file_paths:
        return 0.0
    settings_file_path = None
    food_file_path = None
    for file_path in file_paths:
        filename = os.path.basename(file_path)
        if filename == 'settings.py':
            settings_file_path = file_path
        elif filename == 'food.py':
            food_file_path = file_path
    if not settings_file_path or not os.path.exists(settings_file_path):
        return 0.0
    if not food_file_path or not os.path.exists(food_file_path):
        return 0.0
    try:
        score = 0.0
        with open(settings_file_path, 'r', encoding='utf-8') as f:
            settings_content = f.read()
        settings_tree = ast.parse(settings_content)
        yellow_defined_correctly = False
        for node in ast.walk(settings_tree):
            if isinstance(node, ast.Assign):
                if len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                    var_name = node.targets[0].id
                    if var_name == 'YELLOW':
                        if isinstance(node.value, ast.Tuple) and len(node.value.elts) == 3:
                            values = []
                            for elt in node.value.elts:
                                if isinstance(elt, ast.Constant):
                                    values.append(elt.value)
                            if values == [255, 255, 0]:
                                yellow_defined_correctly = True
                                score += 0.5
                                break
        with open(food_file_path, 'r', encoding='utf-8') as f:
            food_content = f.read()
        food_tree = ast.parse(food_content)
        food_uses_yellow = False
        for node in ast.walk(food_tree):
            if isinstance(node, ast.ClassDef) and node.name == 'Food':
                for class_item in node.body:
                    if isinstance(class_item, ast.FunctionDef) and class_item.name == '__init__':
                        for init_node in ast.walk(class_item):
                            if isinstance(init_node, ast.Assign):
                                if isinstance(init_node.value, ast.Name) and init_node.value.id == 'YELLOW':
                                    if len(init_node.targets) == 1:
                                        target = init_node.targets[0]
                                        if isinstance(target, ast.Attribute):
                                            if isinstance(target.value, ast.Name) and target.value.id == 'self' and (target.attr == 'color'):
                                                food_uses_yellow = True
                                                score += 0.5
                                                break
                        if food_uses_yellow:
                            break
                if food_uses_yellow:
                    break
        return score
    except Exception as e:
        return 0.0

def check_attendance_counts__ba2f4897(actual_file_path, expected):
    """Check if attendance counts are filled in correctly for conferences.

    Validates that:
    1. The table has the correct structure (3 conferences × 7 years = 21 rows)
    2. Conference names and years are correctly paired
    3. Attendance values match expected values with 10% tolerance

    Args:
        actual_file_path: Path to the Excel file with filled attendance data
        expected: Expected configuration with attendance values

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('expected_values', [])
    wb = openpyxl.load_workbook(actual_file_path, data_only=True)
    sheet = wb.active
    expected_conferences = ['ICLR', 'ICML', 'Neurips']
    expected_years = list(range(2013, 2020))
    expected_structure = []
    for conf in expected_conferences:
        for year in expected_years:
            expected_structure.append((conf, year))
    if len(expected_structure) != 21 or len(expected_values) != 21:
        logger.error('Expected structure mismatch: should have 21 rows')
        return 0.0
    score = 0.0
    total_checks = len(expected_values)
    structure_score = 0.0
    value_score = 0.0
    actual_data = []
    for row_idx in range(2, 23):
        try:
            conference = sheet.cell(row=row_idx, column=1).value
            year = sheet.cell(row=row_idx, column=2).value
            attendance = sheet.cell(row=row_idx, column=3).value
            actual_data.append((conference, year, attendance))
        except Exception as e:
            logger.debug(f'Error reading row {row_idx}: {e}')
            actual_data.append((None, None, None))
    for i in range(min(len(expected_structure), len(actual_data))):
        (expected_conf, expected_year) = expected_structure[i]
        (actual_conf, actual_year, actual_attendance) = actual_data[i]
        expected_attendance = expected_values[i]
        structure_match = False
        if actual_conf and actual_year:
            actual_conf_normalized = str(actual_conf).strip().upper()
            expected_conf_normalized = expected_conf.strip().upper()
            conf_match = actual_conf_normalized == expected_conf_normalized
            year_match = False
            try:
                actual_year_int = int(actual_year)
                year_match = actual_year_int == expected_year
            except (ValueError, TypeError):
                pass
            structure_match = conf_match and year_match
        if structure_match:
            structure_score += 0.4 / total_checks
        if isinstance(expected_attendance, (int, float)) and actual_attendance is not None:
            try:
                actual_num = float(actual_attendance)
                if abs(actual_num - expected_attendance) / expected_attendance <= 0.1:
                    value_score += 0.6 / total_checks
            except (ValueError, TypeError):
                pass
        elif expected_attendance == actual_attendance:
            value_score += 0.6 / total_checks
    score = structure_score + value_score
    return round(score, 3)

def check_three_phones_filled__11108259(result, expected, **options):
    """Check if cell(s) are filled with valid data

    Args:
        result: Data from getter function
        expected: Expected rules dict
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    if isinstance(result, list):
        min_length = expected.get('min_length', 1)
        cells = expected.get('cells', [])
        if len(result) != len(cells):
            return 0.0
        score = 0.0
        for value in result:
            if value and len(value) >= min_length:
                score += 1.0 / len(result)
        return score
    elif isinstance(result, dict):
        name = result.get('name', '')
        address = result.get('address', '')
        min_name_length = expected.get('min_name_length', 1)
        min_address_length = expected.get('min_address_length', 1)
        score = 0.0
        if name and len(name) >= min_name_length:
            score += 0.5
        if address and len(address) >= min_address_length:
            score += 0.5
        return score
    elif isinstance(result, int):
        min_count = expected.get('min_count', 1)
        if result >= min_count:
            return 1.0
        else:
            return result / min_count if min_count > 0 else 0.0
    elif 'must_contain' in expected:
        if expected['must_contain'].lower() in result.lower():
            return 1.0
        else:
            return 0.0
    else:
        min_length = expected.get('min_length', 1)
        if result and len(result) >= min_length:
            return 1.0
        else:
            return 0.0

def check_torch_ops__c5d7e2f1(result, expected, **options):
    """
    Validate extracted torch operations.

    Args:
        result: List of torch operation lines from getter
        expected: Dict with 'min_operations', 'must_contain' keys
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, list):
        return 0.0
    min_operations = expected.get('min_operations', 1)
    must_contain = expected.get('must_contain', [])
    score = 0.0
    if len(result) >= min_operations:
        score += 0.4
    else:
        score += 0.4 * (len(result) / min_operations)
    valid_lines = 0
    for line in result:
        if 'torch.' in line or '.to(' in line:
            valid_lines += 1
    if len(result) > 0:
        score += 0.3 * (valid_lines / len(result))
    if must_contain:
        all_content = ' '.join(result)
        keywords_found = sum((1 for kw in must_contain if kw in all_content))
        score += 0.3 * (keywords_found / len(must_contain))
    else:
        score += 0.3
    return min(1.0, score)

def check_column_sorted__49e77bb0b54802cc0429ebcbecc68fd3(result, expected, **options):
    """
    Check if a column is sorted according to specified order.

    Args:
        result: List of values from getter
        expected: Expected sorting rules (from rules dict)
            - order: "desc" or "asc" (default: "desc")
            - treat_dash_as_none: Whether to treat "--" as None/empty (default: True)
        **options: Additional options

    Returns:
        float: 1.0 if sorted correctly, 0.0 otherwise
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    order = expected.get('order', 'desc')
    treat_dash_as_none = expected.get('treat_dash_as_none', True)
    numeric_values = []
    for val in result:
        if val is None:
            continue
        if treat_dash_as_none and (val == '--' or val == ''):
            continue
        try:
            numeric_values.append(float(val))
        except (ValueError, TypeError):
            continue
    if len(numeric_values) < 2:
        return 1.0
    is_sorted = True
    if order == 'desc':
        for i in range(len(numeric_values) - 1):
            if numeric_values[i] < numeric_values[i + 1]:
                is_sorted = False
                break
    else:
        for i in range(len(numeric_values) - 1):
            if numeric_values[i] > numeric_values[i + 1]:
                is_sorted = False
                break
    return 1.0 if is_sorted else 0.0

