def check_cs_avg_rate__fe33fa8497826ffab54958d76a7a0463(result, expected, **options):
    """Compare calculated average success rate and verify file structure

    Args:
        result: Dict containing average rate and yearly rates
        expected: Dict with 'average_rate' key (from rules)
        **options: tolerance for floating point comparison

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None or expected is None:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    try:
        result_avg = result.get('average_rate')
        yearly_rates = result.get('yearly_rates', {})
        expected_avg = expected.get('average_rate')
        if result_avg is None or expected_avg is None:
            return 0.0
        result_val = float(result_avg)
        expected_val = float(expected_avg)
        if abs(result_val - expected_val) > tolerance:
            return 0.0
        required_years = {2019, 2020, 2021, 2022, 2023}
        if not all((year in yearly_rates for year in required_years)):
            return 0.0
        for (year, rate) in yearly_rates.items():
            try:
                rate_val = float(rate)
                if rate_val < 0 or rate_val > 100:
                    return 0.0
            except (ValueError, TypeError):
                return 0.0
        return 1.0
    except (ValueError, TypeError, KeyError):
        return 0.0

