        has_new_sheet = expected.get('has_new_sheet', False)
        wb = openpyxl.load_workbook(result, data_only=True)
        score = 0.0
        if has_new_sheet:
            found_chart_in_new_sheet = False
            chart_found = False
            correct_type = False
            correct_title = False
            for sheet_name in wb.sheetnames:
                if sheet_name == 'Sheet1':
                    continue
                ws = wb[sheet_name]
