def check_conference_month__90f5f307(actual_file_path, expected):
    """Check if conference month is filled in correctly.

    Args:
        actual_file_path: Path to the Excel file with filled month data
        expected: Expected configuration with month values

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('expected_values', [])
    wb = openpyxl.load_workbook(actual_file_path, data_only=True)
    sheet = wb.active
    actual_values = []
    for row in sheet['C2:C22']:
        for cell in row:
            actual_values.append(cell.value)
    score = 0.0
    total_checks = len(expected_values)
    if total_checks == 0:
        return 0.0
    for i in range(total_checks):
        try:
            expected_val = expected_values[i]
            actual_val = actual_values[i]
            if actual_val is None:
                continue
            actual_str = str(actual_val).strip().lower()
            if isinstance(expected_val, list):
                if any((exp.strip().lower() in actual_str for exp in expected_val)):
                    score += 1.0 / total_checks
            elif expected_val.strip().lower() in actual_str:
                score += 1.0 / total_checks
        except (IndexError, KeyError, TypeError, AttributeError) as e:
            logger.debug(f'Error checking index {i}: {e}')
            continue
    return round(score, 3)

def check_station_filter__237db233bbdb3a0cc4ac31a2e872f7e8(result: List[str], expected: Dict[str, Any], **options) -> float:
    """
    Check if the docx file contains only records for the specified station.

    Args:
        result: List of train record lines from getter
        expected: Dict with 'station_id' and 'expected_count' keys
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list):
        logger.error(f'Result is not a list: {type(result)}')
        return 0.0
    target_station = expected.get('station_id')
    expected_count = expected.get('expected_count')
    if not target_station or expected_count is None:
        logger.error('Missing station_id or expected_count in expected config')
        return 0.0
    valid_count = 0
    for line in result:
        parts = line.split(',')
        if len(parts) == 4:
            station_id = parts[2].strip()
            if station_id == target_station:
                valid_count += 1
            else:
                logger.info(f'Found record for wrong station: {station_id} (expected {target_station})')
                return 0.0
    if valid_count == expected_count:
        return 1.0
    else:
        logger.info(f'Record count mismatch: got {valid_count}, expected {expected_count}')
        return 0.0

def check_notes_extraction__68f3f443f3006ce9bd32bcff7b4875f2(result: Dict[str, Any], expected: dict, **options) -> float:
    """Check if the extracted notes match the expected notes from slides.

    Verifies:
    1. Count matches expected count
    2. Each output note matches an expected note (content verification)
    3. All expected notes are present in output
    4. Each note is on its own line (one paragraph per note)

    Args:
        result: Dict from getter with 'output_notes', 'expected_notes', 'count'
        expected: Expected rules dict with 'count' key
        **options: Additional options

    Returns:
        1.0 if all checks pass, 0.0 otherwise
    """
    expected_count = expected.get('count', 0)
    output_notes = result.get('output_notes', [])
    expected_notes = result.get('expected_notes', [])
    actual_count = result.get('count', 0)
    if actual_count != expected_count:
        return 0.0
    if len(expected_notes) != expected_count:
        return 0.0
    if len(output_notes) != expected_count:
        return 0.0

    def normalize(text: str) -> str:
        """Normalize text for comparison."""
        return ' '.join(text.split())
    normalized_output = [normalize(note) for note in output_notes]
    normalized_expected = [normalize(note) for note in expected_notes]
    if set(normalized_expected) != set(normalized_output):
        return 0.0
    return 1.0

def check_preprocessing_code__f8d0ee8f(result_file, expected, **options):
    """
    Check if a Python file contains data preprocessing code.

    Args:
        result_file: Path to the Python file to check
        expected: Dict with 'required_vars', 'min_vars', 'required_patterns'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (0.5 for variables + 0.5 for patterns)
    """
    if not result_file:
        return 0.0
    try:
        with open(result_file, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        print(f'Error reading file: {e}')
        return 0.0
    required_vars = expected.get('required_vars', [])
    min_vars = expected.get('min_vars', len(required_vars))
    required_patterns = expected.get('required_patterns', [])
    score = 0.0
    if required_vars:
        found_vars = set()
        try:
            tree = ast.parse(content)
            for node in ast.walk(tree):
                if isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name):
                            found_vars.add(target.id)
                elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                    found_vars.add(node.target.id)
        except SyntaxError:
            pass
        vars_found = sum((1 for var in required_vars if var in found_vars))
        if vars_found >= min_vars:
            var_score = 0.5 * (vars_found / len(required_vars))
            score += var_score
    if required_patterns:
        patterns_found = sum((1 for pattern in required_patterns if re.search(pattern, content)))
        pattern_score = 0.5 * (patterns_found / len(required_patterns))
        score += pattern_score
    return min(score, 1.0)

