def check_parentheses_answers__faacb6dea70ef25b404521dc6e6554b5(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Check if the answer file contains answers in correct format.

    Test 1 should remain in lowercase format (bbbad).
    Test 2 and Test 3 should be in uppercase parentheses format.

    Args:
        result: Full text content from the docx file
        expected: Dict with 'test_patterns' containing regex patterns for each test
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    test_patterns = expected.get('test_patterns', {})
    if not test_patterns:
        logger.warning('No test patterns provided')
        return 0.0
    total_tests = len(test_patterns)
    if total_tests == 0:
        return 0.0
    correct_count = 0
    for (test_name, pattern_info) in test_patterns.items():
        pattern = pattern_info.get('pattern', '')
        if not pattern:
            logger.info(f"No pattern for test '{test_name}'")
            continue
        if test_name == 'Grammar test 1':
            match = re.search(pattern, result, re.IGNORECASE | re.MULTILINE)
        else:
            match = re.search(pattern, result, re.MULTILINE)
        if match:
            correct_count += 1
            logger.info(f"Test '{test_name}' pattern matched: {match.group(0)}")
        else:
            logger.info(f"Test '{test_name}' pattern not found in result")
    score = correct_count / total_tests
    return score

def check_bib_has_venue__1829c383(result, expected, **options):
    """Check if bibtex contains the correct Spider paper from EMNLP 2018.

    Args:
        result: Dict with 'venues', 'titles', 'authors', and 'years' lists from getter
        expected: Dict with 'venue_keywords' to search for
        **options: Additional options

    Returns:
        float: 1.0 if correct Spider paper from EMNLP is found, 0.0 otherwise
    """
    venue_keywords = expected.get('venue_keywords', [])
    venues = result.get('venues', [])
    titles = result.get('titles', [])
    authors = result.get('authors', [])
    years = result.get('years', [])
    if not venues and (not titles):
        return 0.0
    venue_match = False
    for keyword in venue_keywords:
        keyword_lower = keyword.lower()
        for venue in venues:
            if keyword_lower in venue.lower():
                venue_match = True
                break
        if venue_match:
            break
    if not venue_match:
        return 0.0
    title_match = False
    for title in titles:
        if 'spider' in title.lower():
            title_match = True
            break
    if not title_match:
        return 0.0
    year_match = False
    for year in years:
        if year == '2018':
            year_match = True
            break
    if not year_match:
        return 0.0
    author_match = False
    for author in authors:
        if 'tao yu' in author.lower() or 'yu' in author.lower():
            author_match = True
            break
    return 1.0

def check_multi_step__de59967047914828e21a9fc9ad62546c(result, expected, **options):
    """Multi-step verification with partial credit.

    Args:
        result: Dict with verification results
        expected: Expected numeric value (from rules dict)
        **options: Additional options (tolerance for numeric comparison)

    Returns:
        float: Score from 0.0 to 1.0 based on completion of all steps
    """
    if not isinstance(result, dict):
        return 0.0
    score = 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_value = expected.get('value')
    if result.get('csv_exists'):
        score += 0.3
    if result.get('python_code_exists'):
        if result.get('python_has_logic'):
            score += 0.3
        else:
            score += 0.15
    if result.get('result_value') is not None and expected_value is not None:
        try:
            if abs(result['result_value'] - expected_value) <= tolerance:
                score += 0.4
        except:
            pass
    return score

