def check_profit_column__f7f5d9b0(result, expected, **options):
    """
    Check if profit column is correctly added with formulas.

    Args:
        result: Path to the Excel file
        expected: Dict with keys:
            - sheet: Sheet index
            - header_cell: Cell containing column header (e.g., "D1")
            - header_value: Expected header text (e.g., "Profit")
            - sample_checks: Dict of cell:value pairs to verify calculations
        **options: Additional options (tolerance for float comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        header_cell = expected.get('header_cell')
        header_value = expected.get('header_value')
        sample_checks = expected.get('sample_checks', {})
        tolerance = options.get('tolerance', 1.0)
        wb = openpyxl.load_workbook(result, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        score = 0.0
        if header_cell and header_value:
            actual_header = ws[header_cell].value
            logger.info(f"Header cell {header_cell}: expected '{header_value}', got '{actual_header}'")
            if actual_header and str(actual_header).strip().lower() == str(header_value).strip().lower():
                score += 0.3
        if sample_checks:
            correct_samples = 0
            total_samples = len(sample_checks)
            for (cell, expected_value) in sample_checks.items():
                actual_value = ws[cell].value
                logger.info(f'Cell {cell}: expected {expected_value}, got {actual_value}')
                if actual_value is not None and expected_value is not None:
                    if isinstance(expected_value, (int, float)) and isinstance(actual_value, (int, float)):
                        rel_tolerance = max(tolerance, abs(expected_value * 0.001))
                        if abs(float(actual_value) - float(expected_value)) < rel_tolerance:
                            correct_samples += 1
                    elif actual_value == expected_value:
                        correct_samples += 1
            if total_samples > 0:
                score += 0.7 * (correct_samples / total_samples)
                logger.info(f'Correct samples: {correct_samples}/{total_samples}')
        logger.info(f'Final score: {score}')
        return min(score, 1.0)
    except Exception as e:
        logger.error(f'Error checking profit column: {e}')
        return 0.0

def check_archive_contents__6131523f(result, expected, **options):
    """Check if archive contains expected files.

    Args:
        result: List of filenames from getter
        expected: Dict with 'files' key containing expected filenames
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, list) or not isinstance(expected, dict):
        return 0.0
    expected_files = expected.get('files', [])
    if not expected_files:
        return 0.0
    result_set = set(result)
    expected_set = set(expected_files)
    matches = len(expected_set.intersection(result_set))
    total = len(expected_set)
    return matches / total if total > 0 else 0.0

