def check_acl_papers__03036500(result: List[Dict[str, Any]], expected: Any, **options) -> float:
    """
    Check if ACL papers data is complete and correct.

    Args:
        result: List of paper dicts from getter
        expected: Dict with:
            - required_years: List of required year values (e.g., [2022, 2021, 2019])
            - min_entries: Minimum number of entries required

    Returns:
        Score between 0.0 and 1.0
    """
    required_years = expected.get('required_years', [2022, 2021, 2019])
    min_entries = expected.get('min_entries', 3)
    if len(result) < min_entries:
        return 0.0
    result_years = []
    score_components = []
    for (i, paper) in enumerate(result):
        title = paper.get('title')
        year = paper.get('year')
        authors = paper.get('authors')
        pdf_link = paper.get('pdf_link')
        if not title or not year or (not authors) or (not pdf_link):
            score_components.append(0.0)
            continue
        try:
            year_int = int(year)
            result_years.append(year_int)
        except (ValueError, TypeError):
            score_components.append(0.0)
            continue
        if not isinstance(title, str) or len(str(title).strip()) == 0:
            score_components.append(0.5)
            continue
        if not isinstance(authors, str) or len(str(authors).strip()) == 0:
            score_components.append(0.5)
            continue
        pdf_link_str = str(pdf_link).strip()
        if not pdf_link_str or 'aclanthology.org' not in pdf_link_str.lower():
            score_components.append(0.7)
            continue
        score_components.append(1.0)
    if len(result_years) < len(required_years):
        return 0.0
    result_years_sorted = sorted(result_years, reverse=True)
    required_years_sorted = sorted(required_years, reverse=True)
    result_years_subset = result_years_sorted[:len(required_years)]
    if result_years_subset != required_years_sorted:
        return 0.0
    if result_years != result_years_sorted:
        return 0.7
    if not score_components:
        return 0.0
    avg_score = sum(score_components[:len(required_years)]) / len(required_years)
    return avg_score

