def check_answer_letters__112a5429503d5081250dc76b0c9a2ac0(result: Dict[str, Dict[str, str]], expected: Dict[str, Any], **options) -> float:
    """
    Check if the extracted answer letters match expected values AND verify dash/bullet formatting.

    Args:
        result: Dict mapping test names to dicts with 'letters' and 'raw_text' keys (from getter)
        expected: Dict with 'answers' key containing expected answer letters
        **options: Additional options (e.g., 'ignore_case')

    Returns:
        Score between 0.0 and 1.0
    """
    expected_answers = expected.get('answers', {})
    ignore_case = options.get('ignore_case', False)
    if not expected_answers:
        logger.warning('No expected answers provided')
        return 0.0
    total_tests = len(expected_answers)
    if total_tests == 0:
        return 0.0
    correct_count = 0
    for (test_name, expected_answer) in expected_answers.items():
        if test_name not in result:
            logger.info(f"Test '{test_name}' not found in result")
            continue
        result_data = result[test_name]
        result_letters = result_data.get('letters', '')
        result_raw_text = result_data.get('raw_text', '')
        if ignore_case:
            result_letters = result_letters.lower()
            expected_answer = expected_answer.lower()
        if result_letters != expected_answer:
            logger.info(f"Answer mismatch for '{test_name}': got '{result_letters}', expected '{expected_answer}'")
            continue
        if not _has_dash_bullet_formatting(result_raw_text):
            logger.info(f"Formatting issue for '{test_name}': text '{result_raw_text}' does not match dash/bullet format")
            continue
        correct_count += 1
    score = correct_count / total_tests
    return score

