def check_code_index__e4b9a1f3(result, expected, **options):
    """
    Validate code index entries.

    Args:
        result: List of index entries from getter
        expected: Dict with 'min_entries', 'required_prefixes', 'expected_items' keys
        **options: Additional options (partial_credit)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, list):
        return 0.0
    min_entries = expected.get('min_entries', 1)
    required_prefixes = expected.get('required_prefixes', [])
    expected_items = expected.get('expected_items', [])
    partial_credit = options.get('partial_credit', False)
    score = 0.0
    if len(result) >= min_entries:
        score += 0.3
    if required_prefixes:
        all_content = '\n'.join(result)
        prefixes_found = sum((1 for prefix in required_prefixes if prefix in all_content))
        score += 0.3 * (prefixes_found / len(required_prefixes))
    else:
        score += 0.3
    if expected_items:
        all_content = ' '.join(result)
        items_found = sum((1 for item in expected_items if item in all_content))
        if partial_credit:
            score += 0.4 * (items_found / len(expected_items))
        elif items_found == len(expected_items):
            score += 0.4
    else:
        score += 0.4
    return min(1.0, score)

def check_student_name_v7__d4477d7a(result, expected, **options):
    """Verify that grading was completed and correct perfect scorer identified.

    Checks:
    1. Cell O3 contains the expected student name
    2. Grading was performed for all students (scores recorded)
    3. The named student actually has a perfect score of 100
    4. The named student is the ONLY one with 100 points

    Args:
        result: Dict with 'o3_value' and 'students' list
        expected: Rules dict with 'expected_name' key
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    expected_name = expected.get('expected_name')
    if expected_name is None:
        return 0.0
    o3_value = result.get('o3_value')
    students = result.get('students', [])
    if o3_value is None:
        return 0.0
    o3_str = str(o3_value).strip().lower()
    expected_str = str(expected_name).strip().lower()
    if o3_str != expected_str:
        return 0.0
    if len(students) == 0:
        return 0.0
    graded_students = 0
    for student in students:
        question_scores = student.get('question_scores', [])
        if any((score is not None for score in question_scores)):
            graded_students += 1
    if graded_students == 0:
        return 0.0
    perfect_scorers = []
    named_student_found = False
    named_student_total = None
    for student in students:
        student_name = student.get('name', '').strip().lower()
        total_score = student.get('total_score')
        if student_name == expected_str:
            named_student_found = True
            named_student_total = total_score
        if total_score is not None:
            try:
                score_value = float(total_score)
                if score_value == 100.0:
                    perfect_scorers.append(student.get('name'))
            except (ValueError, TypeError):
                pass
    if not named_student_found:
        return 0.0
    if named_student_total is None:
        return 0.0
    try:
        named_score = float(named_student_total)
        if named_score != 100.0:
            return 0.0
    except (ValueError, TypeError):
        return 0.0
    if len(perfect_scorers) != 1:
        return 0.0
    return 1.0

def check_brightness_increased__42b8076d(actual: Dict, rules: Dict, **options) -> float:
    """Check if image brightness meets threshold and image matches reference.

    Args:
        actual: Dict with 'brightness' and 'similarity' keys from getter
        rules: Dict with 'min_brightness' and 'min_similarity' keys
        **options: Additional options

    Returns:
        float: 1.0 if both checks pass, 0.0 otherwise
    """
    if actual is None or not isinstance(actual, dict):
        logger.warning(f'Invalid actual value: {actual}')
        return 0.0
    brightness = actual.get('brightness', 0.0)
    similarity = actual.get('similarity', 0.0)
    min_brightness = rules.get('min_brightness', 0.0)
    min_similarity = rules.get('min_similarity', 0.5)
    brightness_ok = brightness >= min_brightness
    similarity_ok = similarity >= min_similarity
    if brightness_ok and similarity_ok:
        logger.info(f'Image check passed: brightness={brightness} >= {min_brightness}, similarity={similarity} >= {min_similarity}')
        return 1.0
    else:
        logger.info(f'Image check failed: brightness={brightness} >= {min_brightness}? {brightness_ok}, similarity={similarity} >= {min_similarity}? {similarity_ok}')
        return 0.0

def check_zip_contents__ed5b60c9b586e02ab1d262e432f8c2c4(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if ZIP file exists, is valid, and contains expected files.

    Args:
        result: Dict from getter with 'exists', 'is_valid_zip', 'file_list'
        expected: Dict with 'required_files' list
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    if result.get('exists', False):
        score += 0.3
    else:
        return 0.0
    if result.get('is_valid_zip', False):
        score += 0.3
    else:
        return score
    required_files = expected.get('required_files', [])
    file_list = result.get('file_list', [])
    if not required_files:
        return score
    matched = sum((1 for f in required_files if f in file_list))
    file_score = matched / len(required_files)
    score += 0.4 * file_score
    return score

