def check_subtitle_purple_title_size__100663d5(result_file, expected, **options):
    """
    Check if subtitle text color is purple and title font size is 36 points.

    Args:
        result_file: Path to the PPTX file
        expected: Dict containing:
            - subtitle_color_rgb: [128, 0, 128] (purple)
            - title_size: 36.0 (in points)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (partial credit for meeting one requirement)
    """
    try:
        prs = Presentation(result_file)
        expected_subtitle_color = tuple(expected.get('subtitle_color_rgb', [128, 0, 128]))
        expected_title_size = expected.get('title_size', 36.0)
        if len(prs.slides) == 0:
            return 0.0
        slide = prs.slides[0]
        subtitle_correct = False
        title_correct = False
        for shape in slide.shapes:
            if not hasattr(shape, 'text_frame'):
                continue
            if hasattr(shape, 'placeholder_format'):
                try:
                    placeholder_type = shape.placeholder_format.type
                    if placeholder_type == 2:
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                if hasattr(run.font.color, 'rgb'):
                                    actual_color = run.font.color.rgb
                                    if actual_color == expected_subtitle_color:
                                        subtitle_correct = True
                                        break
                            if subtitle_correct:
                                break
                    elif placeholder_type == 1:
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                if run.font.size is not None:
                                    actual_size_pt = run.font.size.pt
                                    if abs(actual_size_pt - expected_title_size) < 0.1:
                                        title_correct = True
                                        break
                            if title_correct:
                                break
                except Exception as e:
                    continue
        score = 0.0
        if subtitle_correct:
            score += 0.5
        if title_correct:
            score += 0.5
        return score
    except Exception as e:
        return 0.0

def check_average_row__91d5c465(result, expected, **options):
    """Check if average score has been added to the spreadsheet.

    Verifies:
    1. A summary row exists at the bottom with a label like "Average" or "Summary"
    2. The average value is calculated via a formula (not hardcoded)
    3. The formula references the correct range of student scores
    4. The calculated value matches the expected average

    Args:
        result: Path to the result Excel file
        expected: Dict with 'average_score'

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        wb = openpyxl.load_workbook(result, data_only=False)
        ws = wb['Sheet1']
        wb_data = openpyxl.load_workbook(result, data_only=True)
        ws_data = wb_data['Sheet1']
        expected_avg = expected.get('average_score')
        last_data_row = 1
        for row_idx in range(2, 50):
            has_data = False
            for col_idx in range(1, 10):
                cell_value = ws_data.cell(row=row_idx, column=col_idx).value
                if cell_value is not None and str(cell_value).strip() != '':
                    has_data = True
                    break
            if has_data:
                last_data_row = row_idx
            elif last_data_row > 1:
                break
        found_valid_summary = False
        for row_idx in range(last_data_row + 1, last_data_row + 4):
            has_label = False
            label_text = ''
            for col_idx in range(1, 5):
                cell_value = ws_data.cell(row=row_idx, column=col_idx).value
                if cell_value is not None:
                    label_text = str(cell_value).lower().strip()
                    if any((keyword in label_text for keyword in ['average', 'summary', 'mean', 'avg', 'total average'])):
                        has_label = True
                        break
            has_formula = False
            formula_correct = False
            value_correct = False
            for col_idx in range(1, 14):
                cell_formula = ws.cell(row=row_idx, column=col_idx).value
                cell_data_value = ws_data.cell(row=row_idx, column=col_idx).value
                if cell_formula and isinstance(cell_formula, str) and cell_formula.startswith('='):
                    has_formula = True
                    formula_upper = cell_formula.upper()
                    if 'AVERAGE' in formula_upper or 'AVG' in formula_upper or 'MEAN' in formula_upper:
                        formula_correct = True
                        if cell_data_value is not None:
                            try:
                                if isinstance(cell_data_value, (int, float)):
                                    if abs(float(cell_data_value) - expected_avg) < 0.1:
                                        value_correct = True
                                        break
                            except:
                                pass
                if cell_formula and isinstance(cell_formula, str) and cell_formula.startswith('='):
                    if cell_data_value is not None:
                        try:
                            if isinstance(cell_data_value, (int, float)):
                                if abs(float(cell_data_value) - expected_avg) < 0.1:
                                    has_formula = True
                                    value_correct = True
                                    if any((func in cell_formula.upper() for func in ['AVERAGE', 'SUM', 'COUNT', 'AVG', 'MEAN'])):
                                        formula_correct = True
                                        break
                        except:
                            pass
            if has_formula and value_correct:
                if has_label or row_idx == last_data_row + 1:
                    found_valid_summary = True
                    break
        wb.close()
        wb_data.close()
        return 1.0 if found_valid_summary else 0.0
    except Exception as e:
        print(f'Error in check_average_row__91d5c465: {e}')
        import traceback
        traceback.print_exc()
        return 0.0

def check_simplified_names__43be33c33f047d68d3b6cab5bd4d55ce(result: List[Optional[str]], expected: dict, **options) -> float:
    """Check if email files with simplified names were successfully uploaded.

    Args:
        result: List of downloaded file paths (or None for missing files)
        expected: Expected rules dict with:
            - count: Expected number of files
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0 based on number of successful files
    """
    expected_count = expected.get('count', 2)
    if result is None:
        return 0.0
    successful = sum((1 for path in result if path is not None))
    if expected_count == 0:
        return 0.0
    return successful / expected_count

def check_zip_contents__36707f80(result, expected, **options):
    """Check if ZIP archive contains all required files.

    Args:
        result: Output from 'unzip -l' command
        expected: Rules dict with required_files list
        **options: Additional options

    Returns:
        float: 1.0 if all required files are in archive, 0.0 otherwise
    """
    if result is None or not isinstance(result, str):
        return 0.0
    if 'ZIP_NOT_FOUND' in result:
        return 0.0
    required_files = expected.get('required_files', [])
    min_count = expected.get('min_count', len(required_files))
    found_count = 0
    for filename in required_files:
        if filename in result:
            found_count += 1
    if found_count >= min_count:
        return 1.0
    else:
        return 0.0

def check_title_centered__4e9ea3f6(docx_file, expected, **options):
    """Check if the title (first paragraph) is center-aligned.

    Args:
        docx_file: Path to the DOCX file
        expected: Expected state (dict with 'alignment' - 'center', 'left', 'right', or 'justify')
        **options: Additional options

    Returns:
        float: 1.0 if title alignment matches expected, 0.0 otherwise
    """
    if not docx_file:
        return 0.0
    try:
        doc = Document(docx_file)
    except Exception as e:
        logger.error(f'Error loading document: {e}')
        return 0.0
    if not doc.paragraphs:
        logger.error('Document has no paragraphs')
        return 0.0
    expected_alignment = expected.get('alignment', 'center')
    alignment_map = {'center': WD_PARAGRAPH_ALIGNMENT.CENTER, 'left': WD_PARAGRAPH_ALIGNMENT.LEFT, 'right': WD_PARAGRAPH_ALIGNMENT.RIGHT, 'justify': WD_PARAGRAPH_ALIGNMENT.JUSTIFY}
    if expected_alignment not in alignment_map:
        logger.error(f'Unknown alignment: {expected_alignment}')
        return 0.0
    first_para = doc.paragraphs[0]
    actual_alignment = first_para.paragraph_format.alignment
    if actual_alignment == alignment_map[expected_alignment]:
        return 1.0
    else:
        logger.info(f'Expected {expected_alignment}, got {actual_alignment}')
        return 0.0

