def check_comprehensive_grading__d4477d7a(result, expected, **options):
    """Verify all grading requirements: completeness, Q8 accuracy, and Q8 is lowest.

    Args:
        result: Dict from comprehensive getter with all grading info
        expected: Rules dict with 'expected_q8_accuracy' key
        **options: Additional options (tolerance)

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_q8_accuracy = expected.get('expected_q8_accuracy', 0.444)
    if not result.get('all_graded', False):
        return 0.0
    if result.get('total_students', 0) < 1:
        return 0.0
    q8_accuracy = result.get('q8_accuracy', 0.0)
    if abs(q8_accuracy - expected_q8_accuracy) > tolerance:
        return 0.0
    if not result.get('q8_is_lowest', False):
        return 0.0
    cell_o2_value = result.get('cell_o2_value')
    if cell_o2_value is None:
        return 0.0
    try:
        cell_o2_float = float(cell_o2_value)
    except (TypeError, ValueError):
        return 0.0
    if abs(cell_o2_float - expected_q8_accuracy) > tolerance:
        return 0.0
    return 1.0

def check_sort_and_zip__e2b9921b3a4cfcd62d172fdaae4844bb(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if files are correctly sorted into categories AND zip archives were created.

    Args:
        result: Dict containing:
            - dir1_files: List of files in first directory
            - dir2_files: List of files in second directory
            - zip1_exists: Boolean indicating if first zip file exists
            - zip2_exists: Boolean indicating if second zip file exists
        expected: Dict with 'category1_files' and 'category2_files' keys
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0 based on correctness:
        - 0.35 for correct category1 folder contents
        - 0.35 for correct category2 folder contents
        - 0.15 for zip1 existence
        - 0.15 for zip2 existence
    """
    category1_files = expected.get('category1_files', [])
    category2_files = expected.get('category2_files', [])
    if not category1_files or not category2_files:
        return 0.0
    dir1_files = result.get('dir1_files', [])
    dir2_files = result.get('dir2_files', [])
    zip1_exists = result.get('zip1_exists', False)
    zip2_exists = result.get('zip2_exists', False)
    dir1_set = set(dir1_files)
    dir2_set = set(dir2_files)
    expected1_set = set(category1_files)
    expected2_set = set(category2_files)
    score = 0.0
    if expected1_set.issubset(dir1_set) and len(dir1_set) == len(expected1_set):
        score += 0.35
    if expected2_set.issubset(dir2_set) and len(dir2_set) == len(expected2_set):
        score += 0.35
    if zip1_exists:
        score += 0.15
    if zip2_exists:
        score += 0.15
    return score

