def check_average_values__700003716f1e7ad11cf256f44b13f71f(result: Optional[Dict[str, float]], expected: Dict[str, Any], **options) -> float:
    """Check if calculated average values match expected values.

    Args:
        result: Dict from getter mapping category to average value
        expected: Dict with 'averages' containing expected values for each category
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    expected_averages = expected.get('averages', {})
    if not expected_averages:
        return 0.0
    tolerance = options.get('tolerance', 1.0)
    total_checks = 0
    passed_checks = 0
    for (category, expected_value) in expected_averages.items():
        total_checks += 1
        if category not in result:
            continue
        result_value = result[category]
        if abs(result_value - expected_value) <= tolerance:
            passed_checks += 1
    if total_checks == 0:
        return 0.0
    return passed_checks / total_checks

