def check_list_match__8278c76c3e9924f1866901a10447ca8f(result, expected, **options):
    """Check if list matches expected list and is sorted alphabetically.

    Args:
        result: List of strings (in original file order)
        expected: Expected list with items
        **options: Additional options (ignore_case)

    Returns:
        float: 1.0 if lists match AND result is sorted, 0.0 otherwise
    """
    if not result:
        return 0.0
    expected_list = expected.get('items', [])
    if not expected_list:
        return 0.0
    ignore_case = options.get('ignore_case', False)
    if ignore_case:
        result = [item.lower() for item in result]
        expected_list = [item.lower() for item in expected_list]
    if result != sorted(result):
        return 0.0
    expected_sorted = sorted(expected_list)
    result_sorted = sorted(result)
    if result_sorted == expected_sorted:
        return 1.0
    matching = sum((1 for item in expected_sorted if item in result_sorted))
    return matching / len(expected_sorted)

def check_grade_counts__cce1216327b416f535dd8f41b26505d5(result, expected, **options):
    """Check if grade remarks, labels, and counts are all correct.

    Args:
        result: Dictionary with 'counts', 'labels', and 'student_remarks' from getter
        expected: Dictionary with 'counts', 'labels', and 'student_remarks' expected values
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 with weighted scoring for each component
    """
    REMARKS_WEIGHT = 0.4
    LABELS_WEIGHT = 0.2
    COUNTS_WEIGHT = 0.4
    total_score = 0.0
    expected_remarks = expected.get('student_remarks', {})
    actual_remarks = result.get('student_remarks', {})
    if expected_remarks:
        correct_remarks = 0
        total_students = len(expected_remarks)
        for (student, expected_remark) in expected_remarks.items():
            actual_remark = actual_remarks.get(student, '')
            if actual_remark == expected_remark:
                correct_remarks += 1
        remarks_score = correct_remarks / total_students if total_students > 0 else 0.0
        total_score += remarks_score * REMARKS_WEIGHT
    expected_labels = expected.get('labels', {})
    actual_labels = result.get('labels', {})
    if expected_labels:
        correct_labels = 0
        total_labels = len(expected_labels)
        for (grade, expected_label) in expected_labels.items():
            actual_label = actual_labels.get(grade, '')
            if actual_label == expected_label:
                correct_labels += 1
        labels_score = correct_labels / total_labels if total_labels > 0 else 0.0
        total_score += labels_score * LABELS_WEIGHT
    expected_counts = expected.get('counts', {})
    actual_counts = result.get('counts', {})
    if expected_counts:
        correct_counts = 0
        total_categories = len(expected_counts)
        for (grade, expected_count) in expected_counts.items():
            actual_count = actual_counts.get(grade, 0)
            if actual_count == expected_count:
                correct_counts += 1
        counts_score = correct_counts / total_categories if total_categories > 0 else 0.0
        total_score += counts_score * COUNTS_WEIGHT
    return total_score

def check_transition__48cbefec92f9c367972c7c9f2c14f22d(pptx_file_path, expected, **options):
    """
    Check if a specific slide has the expected transition effect.

    Args:
        pptx_file_path: Path to the PPTX file
        expected: Dictionary with 'slide_idx' and 'transition_type' keys

    Returns:
        1.0 if transition matches, 0.0 otherwise
    """
    slide_idx = expected.get('slide_idx', 0)
    transition_type = expected.get('transition_type', 'dissolve')
    try:
        with zipfile.ZipFile(pptx_file_path, 'r') as zip_ref:
            slide_name = f'ppt/slides/slide{slide_idx + 1}.xml'
            try:
                zip_ref.getinfo(slide_name)
            except KeyError:
                logger.error(f'Slide {slide_name} does not exist')
                return 0.0
            with zip_ref.open(slide_name) as slide_file:
                tree = ET.parse(slide_file)
                root = tree.getroot()
                namespaces = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
                transition = root.find('.//p:transition', namespaces)
                if transition is not None:
                    transition_elem = transition.find(f'.//p:{transition_type}', namespaces)
                    if transition_elem is not None:
                        return 1.0
                    else:
                        logger.info(f'Transition found but not {transition_type}')
                        return 0.0
                else:
                    logger.info('No transition found on slide')
                    return 0.0
    except Exception as e:
        logger.error(f'Error checking transition: {e}')
        return 0.0

def check_priority_values__ee33d883(result, expected, **options):
    """Check if priority values match expected list.

    Args:
        result: List of actual values
        expected: Dict with 'priorities' list to match
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_priorities = expected.get('priorities', [])
    if not isinstance(result, list):
        return 0.0
    if len(result) != len(expected_priorities):
        return 0.0
    matches = 0
    for (actual, exp) in zip(result, expected_priorities):
        if actual == exp:
            matches += 1
        elif isinstance(actual, (int, float)) and isinstance(exp, (int, float)):
            if abs(actual - exp) < 1e-06:
                matches += 1
        elif isinstance(actual, str) and isinstance(exp, str):
            if actual.strip() == exp.strip():
                matches += 1
    return matches / len(expected_priorities) if expected_priorities else 0.0

