def check_brightness_decrease_and_structure_sim__acfc7bbb8c0cd569e87c4f8210570f3d(result_state, expected_state, **options):
    """
    Wrapper for check_brightness_decrease_and_structure_sim that works with rule-based expected state.

    Args:
        result_state: Path to the result image (darker image)
        expected_state: Dict containing 'path' to the original image (brighter image)
        **options: Additional options (threshold, etc.)

    Returns:
        float: 1.0 if brightness decreased and structure preserved, 0.0 otherwise
    """
    result_path = result_state
    expected_path = expected_state.get('path') if isinstance(expected_state, dict) else expected_state
    if result_path is None or expected_path is None:
        logger.error(f'Missing paths - result: {result_path}, expected: {expected_path}')
        return 0.0
    threshold = options.get('threshold', 0.03)
    try:
        img_result = Image.open(result_path)
        img_expected = Image.open(expected_path)
        brightness_result = calculate_brightness(img_result)
        brightness_expected = calculate_brightness(img_expected)
        brightness_reduced = brightness_result < brightness_expected
        logger.debug(f'Brightness - result: {brightness_result}, expected: {brightness_expected}, reduced: {brightness_reduced}')
        target_brightness = 128
        img_result_normalized = normalize_brightness(img_result, target_brightness)
        img_expected_normalized = normalize_brightness(img_expected, target_brightness)
        structure_same = structure_check_by_mse(img_result_normalized, img_expected_normalized, threshold=threshold)
        logger.debug(f'Structure same: {structure_same}')
        if brightness_reduced and structure_same:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        logger.error(f'Error comparing images: {e}')
        return 0.0

def check_user_details__565fa1c24eb22fa66726cab9f4123d31(result, expected, **options):
    """Check user details with partial credit scoring.

    Verifies:
    1. User exists
    2. Home directory is correct
    3. User is in sudo group
    4. Password is correct

    Args:
        result: Dictionary with user details from getter
        expected: Expected values from rules
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 with partial credit
    """
    if not isinstance(result, dict):
        logger.error('Result is not a dictionary')
        return 0.0
    expected_home = expected.get('home_dir', '')
    expected_group = expected.get('group', '')
    total_checks = 4
    passed_checks = 0
    if result.get('exists', False):
        passed_checks += 1
        logger.info('✓ User exists')
    else:
        logger.info('✗ User does not exist')
        return 0.0
    if result.get('home_dir') == expected_home:
        passed_checks += 1
        logger.info(f'✓ Home directory is correct: {expected_home}')
    else:
        logger.info(f"✗ Home directory mismatch - expected: {expected_home}, got: {result.get('home_dir')}")
    groups = result.get('groups', [])
    if expected_group in groups:
        passed_checks += 1
        logger.info(f'✓ User is in {expected_group} group')
    else:
        logger.info(f'✗ User is not in {expected_group} group - groups: {groups}')
    if result.get('password_valid', False):
        passed_checks += 1
        logger.info('✓ Password is correct')
    else:
        logger.info('✗ Password verification failed')
    score = passed_checks / total_checks
    logger.info(f'Final score: {score:.2f} ({passed_checks}/{total_checks} checks passed)')
    return score

