def check_monthly_summary__92787b4efb9fa037eb6789db6178661d(result: Dict[str, float], expected: Dict[str, Any], **options) -> float:
    """Check if monthly revenue summary matches expected values.

    Args:
        result: Dict with month names as keys and revenue totals as values (from getter)
        expected: Dict containing the expected monthly revenues (from rules)
        **options: Additional options (tolerance for float comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not expected:
        return 0.0
    expected_revenues = expected.get('monthly_revenues', {})
    if not expected_revenues:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    total_months = len(expected_revenues)
    if total_months == 0:
        return 0.0
    matched_months = 0
    for (month, expected_value) in expected_revenues.items():
        if month in result:
            actual_value = result[month]
            if abs(actual_value - expected_value) <= tolerance:
                matched_months += 1
    return matched_months / total_months

