def check_vendor_list__5ac98897(result, expected, **options):
    """
    Check if the vendor list file contains the expected vendors in correct order.

    Args:
        result: Path to the file or file content
        expected: Dict with 'rules' containing 'vendors' list
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_vendors = expected.get('vendors', [])
    if isinstance(result, str) and (result.endswith('.txt') or '/' in result):
        try:
            with open(result, 'r') as f:
                content = f.read()
        except:
            return 0.0
    else:
        content = str(result)
    lines = [line.strip() for line in content.split('\n') if line.strip()]
    score = 0.0
    vendors_found = 0
    for expected_vendor in expected_vendors:
        for line in lines:
            if expected_vendor.lower() in line.lower():
                vendors_found += 1
                break
    if vendors_found == len(expected_vendors):
        score = 1.0
