def check_sequential_rename__e9032efc(result, expected, **options):
    """Check if all image files were renamed to sequential pattern with numbers 1, 2, 3.

    Args:
        result: JSON string/dict mapping image hashes to filenames
        expected: Rules dict with pattern, expected_count, and image_hashes
        **options: Additional options

    Returns:
        float: 1.0 if all files match pattern with sequential numbers 1, 2, 3, 0.0 otherwise
    """
    if result is None:
        return 0.0
    if isinstance(result, str):
        result = result.strip().replace("'", '"')
        try:
            result = json.loads(result)
        except:
            return 0.0
    pattern = expected.get('pattern', '')
    image_hashes = expected.get('image_hashes', [])
    expected_count = expected.get('expected_count', 0)
    if len(result) != expected_count:
        return 0.0
    filenames = []
    numbers = []
    for img_hash in image_hashes:
        if img_hash not in result:
            return 0.0
        filename = result[img_hash]
        filenames.append(filename)
        match = re.match('^photo_(\\d+)\\.jpg$', filename)
        if not match:
            return 0.0
        number = int(match.group(1))
        numbers.append(number)
    if sorted(numbers) != [1, 2, 3]:
        return 0.0
    return 1.0

def run_sqlite3__dd84e895_72fd_4023_a336_97689ded257c_task_verify_4(result: str, rules: Dict[str, Any]) -> float:
    """
    Run a SQLite query on a database file with proper error handling.

    This is a custom version of run_sqlite3 that handles None input gracefully.
    When get_vm_file fails to fetch the database file (network issues, file not found,
    permissions), it returns 0.0 instead of crashing.

    Args:
        result: Path to the SQLite database file (can be None if fetch failed)
        rules: Dict containing 'sql' key with the SQL query to execute

    Returns:
        float: Result of the SQL query (expected to be 0 or 1 for boolean checks),
               or 0.0 if result is None or query fails
    """
    if result is None:
        logger.warning('Database file path is None (file fetch failed), returning 0.0')
        return 0.0
    try:
        connection: sqlite3.Connection = sqlite3.connect(result)
        cursor: sqlite3.Cursor = connection.execute(rules['sql'])
        query_result = cursor.fetchone()[0]
        connection.close()
        return float(query_result or 0)
    except sqlite3.Error as e:
        logger.error(f'SQLite error while executing query: {e}')
        return 0.0
    except Exception as e:
        logger.error(f'Unexpected error in run_sqlite3: {e}')
        return 0.0

def check_heading_color__c069c1cc(result, expected, **options):
    """
    Check if headings have the specified color.

    Args:
        result: Dict mapping heading text to RGB color tuples from getter
        expected: Dict with 'target_rgb' (tuple) and optional 'headings' list
        **options: Additional options including 'tolerance' for color matching

    Returns:
        float: Score between 0.0 and 1.0
    """
    target_rgb = expected.get('target_rgb', (0, 0, 128))
    expected_headings = expected.get('headings', [])
    tolerance = options.get('tolerance', 10)
    if not expected_headings:
        expected_headings = list(result.keys())
    if not expected_headings:
        return 0.0
    match_count = 0
    for heading in expected_headings:
        if heading in result:
            actual_rgb = result[heading]
            if all((abs(actual_rgb[i] - target_rgb[i]) <= tolerance for i in range(3))):
                match_count += 1
    return match_count / len(expected_headings)

def check_names_sorted_by_lastname__bdc4201fedfbbb54ee0625123608b59b(result: List[str], expected: Dict[str, Any], **options) -> float:
    """Check if the names are sorted by last name and match expected list.

    Args:
        result: List of names from the getter
        expected: Expected data with 'names_sorted_by_lastname' key
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list):
        return 0.0
    expected_names = expected.get('names_sorted_by_lastname', [])
    if not expected_names:
        return 0.0
    result_normalized = [name.strip().lower() for name in result if name]
    expected_normalized = [name.strip().lower() for name in expected_names]
    if len(result_normalized) != len(expected_normalized):
        return min(len(result_normalized) / len(expected_normalized), 1.0) * 0.3
    score = 0.0
    matches = 0
    for (i, (res_name, exp_name)) in enumerate(zip(result_normalized, expected_normalized)):
        if res_name == exp_name:
            matches += 1
    if matches == len(expected_normalized):
        score = 1.0
    elif matches > 0:
        all_present = all((exp in result_normalized for exp in expected_normalized))
        if all_present:
            score = 0.5 + matches / len(expected_normalized) * 0.5
        else:
            score = matches / len(expected_normalized) * 0.5
    return score

def check_invoice_item_count__fe7b3b87c906805b9607b8fa824022f2(result, expected, **options):
    """Comprehensive verification of invoice Excel file with partial credit scoring.

    Checks:
    - File exists on Desktop (0.2 points)
    - File is .xlsx format (0.1 points)
    - Has proper structure: header and total row (0.2 points)
    - Correct item count (0.3 points)
    - Data content verification: sample items match expected (0.2 points)

    Args:
        result: Dict from getter with file details and extracted data
        expected: Expected values (from rules dict)
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0 with partial credit
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    score = 0.0
    expected_count = expected.get('item_count', 0)
    expected_items = expected.get('sample_items', [])
    if result.get('exists', False):
        if result.get('on_desktop', False):
            score += 0.2
    if result.get('is_xlsx', False):
        score += 0.1
    has_structure = result.get('has_header', False) and result.get('has_total_row', False)
    if has_structure:
        score += 0.2
    actual_count = result.get('item_count', 0)
    if actual_count == expected_count:
        score += 0.3
    if expected_items and result.get('items'):
        actual_items = result.get('items', [])
        matches = 0
        for expected_item in expected_items:
            for actual_item in actual_items:
                match = True
                for key in expected_item:
                    if key in actual_item:
                        expected_val = str(expected_item[key]).strip().lower()
                        actual_val = str(actual_item[key]).strip().lower()
                        if expected_val and actual_val and (expected_val != actual_val):
                            match = False
                            break
                if match:
                    matches += 1
                    break
        if matches > 0:
            match_ratio = matches / len(expected_items)
            score += 0.2 * match_ratio
    elif not expected_items:
        if actual_count == expected_count:
            score += 0.2
    return round(score, 2)

