def multi_evaluator(result: Any, expected: Any, **options) -> float:
    """Multi-step evaluator that runs multiple checks with weights.

    This evaluator runs multiple sub-checks defined in options['checks'],
    each with its own getter, metric, expected value, and weight.
    The final score is the weighted sum of all check scores.

    Args:
        result: Not used (placeholder for compatibility)
        expected: Not used (placeholder for compatibility)
        **options: Must contain 'checks' list and 'env' reference

    Returns:
        float: Weighted average score between 0.0 and 1.0
    """
    checks = options.get('checks', [])
    env = options.get('env')
    if not checks or not env:
        return 0.0
    total_score = 0.0
    total_weight = 0.0
    for check in checks:
        func_name = check.get('func')
        result_config = check.get('result', {})
        expected_value = check.get('expected', {})
        weight = check.get('weight', 1.0)
        if not func_name:
            continue
        try:
            metric_func = globals().get(func_name)
            if not metric_func:
                from importlib import import_module
                module = import_module('metrics.xlsx')
                metric_func = getattr(module, func_name, None)
            if not metric_func:
                continue
            getter_type = result_config.get('type')
            if getter_type:
                from importlib import import_module
                getters_module = import_module('getters.xlsx')
                getter_func = getattr(getters_module, f'get_{getter_type}', None)
                if getter_func:
                    result_data = getter_func(env, result_config)
                    expected_data = expected_value
                    check_score = metric_func(result_data, expected_data)
                    total_score += check_score * weight
                    total_weight += weight
        except Exception:
            continue
    return total_score / total_weight if total_weight > 0 else 0.0

