def check_account_count__c08eab5a(result: str, expected: dict) -> float:
    """
    Check if the number of Thunderbird accounts matches expected count and verify account identity.

    Args:
        result: path to csv file containing account data
        expected: dict with "count" key specifying expected number of accounts
                  and optional "account_email" key specifying which account should remain

    Returns:
        float: 1.0 if count matches and account identity is correct (if specified), 0.0 otherwise
    """
    if result is None:
        return 0.0
    expected_count = expected.get('count', 0)
    expected_email = expected.get('account_email')
    try:
        with open(result) as f:
            reader = csv.DictReader(f)
            accounts = list(reader)
            actual_count = len(accounts)
    except Exception as e:
        logger.error(f'Error reading CSV: {e}')
        return 0.0
    if actual_count != expected_count:
        logger.debug(f'Expected {expected_count} accounts, found {actual_count}')
        return 0.0
    if expected_email is not None:
        if actual_count == 0:
            logger.debug(f'No accounts found, expected account: {expected_email}')
            return 0.0
        actual_email = None
        for field in ['email', 'username', 'user', 'account']:
            if field in accounts[0]:
                actual_email = accounts[0][field]
                break
        if actual_email is None and len(accounts[0]) > 0:
            actual_email = list(accounts[0].values())[0] if accounts[0] else None
        if actual_email != expected_email:
            logger.debug(f"Expected account '{expected_email}', found '{actual_email}'")
            return 0.0
    logger.debug(f'Verification passed: {actual_count} account(s)' + (f" with email '{expected_email}'" if expected_email else ''))
    return 1.0

