def check_class_count__8e31593051ddbcebea635607c768bb8c(result, expected, **options):
    """Check if Python file has expected number of classes.

    Args:
        result: Class data from getter
        expected: Expected rules (dict with min_classes, exact_classes, or class_names)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result.get('exists', False):
        return 0.0
    score = 0.0
    checks = 0
    class_count = result.get('class_count', 0)
    classes = result.get('classes', {})
    if 'min_classes' in expected:
        checks += 1
        if class_count >= expected['min_classes']:
            score += 1.0
    if 'exact_classes' in expected:
        checks += 1
        if class_count == expected['exact_classes']:
            score += 1.0
    if 'class_names' in expected:
        checks += 1
        expected_names = expected['class_names']
        if all((name in classes for name in expected_names)):
            score += 1.0
    return score / checks if checks > 0 else 0.0

