def check_enabled_experiments__480bcfea_d68f_4aaa_a0a9_2589ef319381_task_verify_2(enabled_experiments, rule):
    """
    Check if specific experiments are disabled (not in the enabled experiments list).

    This metric checks that specific flags are NOT present in the enabled experiments,
    while allowing other unrelated experiments to remain enabled.

    Args:
        enabled_experiments: List of enabled experiment strings (e.g., ["experiment@1", "another@2"])
        rule: Dict with structure {"type": "flags_disabled", "flags": ["flag1", "flag2"]}

    Returns:
        float: 1.0 if all specified flags are disabled, 0.0 otherwise
    """
    enabled_experiments_names = [experiment.split('@')[0] for experiment in enabled_experiments]
    if rule['type'] == 'flags_disabled':
        flags_to_check = rule['flags']
        for flag in flags_to_check:
            if flag in enabled_experiments_names:
                return 0.0
        return 1.0
    else:
        raise TypeError(f"{rule['type']} not support yet!")

