def check_top_n_students__054fb987(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Message column is filled and top N students are correctly identified in order.

    Args:
        result: Dict with 'sorted_students' and 'messages_filled'
        expected: Dict with expected top students and message requirements
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (50% for messages filled, 50% for correct sorting)
    """
    expected_top = expected.get('top_students', [])
    n = expected.get('n', len(expected_top))
    expected_messages_filled = expected.get('messages_filled', True)
    if not expected_top:
        return 0.0
    sorted_students = result.get('sorted_students', [])
    messages_filled = result.get('messages_filled', False)
    message_score = 0.5 if messages_filled == expected_messages_filled else 0.0
    sorting_score = 0.0
    result_top = sorted_students[:n] if len(sorted_students) >= n else sorted_students
    if result_top == expected_top:
        sorting_score = 0.5
    else:
        for (i, expected_name) in enumerate(expected_top):
            if i < len(result_top) and result_top[i] == expected_name:
                sorting_score += 0.5 / len(expected_top)
    return message_score + sorting_score

