def check_ratio_values__b2f2b4aac8cb13cbe4c4e471b7057d1e(result: Optional[Dict[int, float]], expected: Dict[str, Any], **options) -> float:
    """Check if calculated ratio values match expected values.

    Args:
        result: Dict from getter mapping year to ratio value
        expected: Dict with 'ratios' containing expected values for each year
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    expected_ratios = expected.get('ratios', {})
    if not expected_ratios:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    total_checks = 0
    passed_checks = 0
    for (year, expected_value) in expected_ratios.items():
        year_int = int(year)
        total_checks += 1
        if year_int not in result:
            continue
        result_value = result[year_int]
        if abs(result_value - expected_value) <= tolerance:
            passed_checks += 1
    if total_checks == 0:
        return 0.0
    return passed_checks / total_checks

