def check_tetris_rotate_fix__ca30528a(result, expected, **options):
    """Check if tetris.py contains proper rotation fix with collision detection.

    The fix must:
    1. Save old_rotation before rotating
    2. Perform rotation
    3. Check for collision with intersect()
    4. Revert rotation if collision detected

    Args:
        result: dict of filename -> file content
        expected: dict with required content list

    Returns:
        float: Score 0.0-1.0
    """
    tetris_content = result.get('tetris.py')
    if not tetris_content:
        return 0.0
    if 'def rotate(self):' not in tetris_content:
        return 0.0
    try:
        tree = ast.parse(tetris_content)
        rotate_method = None
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef) and node.name == 'rotate':
                rotate_method = node
                break
        if not rotate_method:
            return 0.0
        rotate_source_lines = tetris_content.split('\n')
        method_start = rotate_method.lineno - 1
        method_end = rotate_method.end_lineno
        rotate_source = '\n'.join(rotate_source_lines[method_start:method_end])
        has_old_rotation = bool(re.search('old_rotation\\s*=', rotate_source))
        has_intersect_call = bool(re.search('\\.intersect\\s*\\(', rotate_source))
        has_rotation_assignment = bool(re.search('\\.rotation\\s*=', rotate_source))
        has_revert_logic = bool(re.search('if\\s+.*intersect\\s*\\([^)]*\\)\\s*:.*rotation\\s*=\\s*old_rotation', rotate_source, re.DOTALL))
        if not has_revert_logic:
            has_revert_logic = bool(re.search('if\\s+.*intersect.*:\\s*\\n\\s+.*\\.rotation\\s*=\\s*old_rotation', rotate_source, re.MULTILINE))
        score = 0.0
        if has_old_rotation:
            score += 0.25
        if has_intersect_call:
            score += 0.25
        if has_rotation_assignment:
            score += 0.25
        if has_revert_logic:
            score += 0.25
        return score
    except SyntaxError:
        pass
    rotate_pattern = 'def rotate\\(self\\):.*?(?=\\n    def |\\n\\nclass |\\Z)'
    rotate_match = re.search(rotate_pattern, tetris_content, re.DOTALL)
    if not rotate_match:
        return 0.0
    rotate_code = rotate_match.group(0)
    has_old_rotation = bool(re.search('old_rotation\\s*=', rotate_code))
    has_intersect_call = bool(re.search('\\.intersect\\s*\\(', rotate_code))
    has_conditional_revert = bool(re.search('if\\s+.*intersect.*:.*rotation\\s*=\\s*old_rotation', rotate_code, re.DOTALL))
    score = 0.0
    if has_old_rotation:
        score += 0.35
    if has_intersect_call:
        score += 0.35
    if has_conditional_revert:
        score += 0.3
    return score

