def check_grammar_test_answer_details__b1578d294f483f13e4e751bc2459e330(result: Dict[str, Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if grammar test answer details match expected values.

    Args:
        result: Dict of test sections with answer details from getter
        expected: Dict with 'test_requirements' key containing test requirements
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on partial credit
    """
    test_requirements = expected.get('test_requirements', {})
    if not test_requirements:
        logger.error('No test requirements provided')
        return 0.0
    score = 0.0
    total_requirements = len(test_requirements)
    for (test_name, requirements) in test_requirements.items():
        if test_name not in result:
            logger.warning(f"Test section '{test_name}' not found in result")
            continue
        result_details = result[test_name]
        section_score = 0.0
        total_checks = 0
        if 'length' in requirements:
            total_checks += 1
            expected_length = requirements['length']
            result_length = result_details.get('length', 0)
            if result_length == expected_length:
                section_score += 1.0
                logger.info(f"✓ Test '{test_name}' has correct length: {result_length}")
            else:
                logger.warning(f"✗ Test '{test_name}' length mismatch: expected {expected_length}, got {result_length}")
        if 'has_answer' in requirements and requirements['has_answer']:
            total_checks += 1
            result_answer = result_details.get('answer', '')
            if result_answer:
                section_score += 1.0
                logger.info(f"✓ Test '{test_name}' has answer: {result_answer}")
            else:
                logger.warning(f"✗ Test '{test_name}' missing answer")
        if total_checks > 0:
            score += section_score / total_checks / total_requirements
    return score

def check_acl_row__d605b478(result: dict, expected: dict, **options) -> float:
    """
    Check if all required fields for ACL paper entry are present and valid.

    Args:
        result: Dict with keys 'A', 'B', 'C', 'D' representing row data
        expected: Dict with expected values for each field

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    scores = []
    title = result.get('A')
    if 'title' in expected:
        if expected['title'].get('not_empty'):
            if title and isinstance(title, str) and title.strip():
                scores.append(1.0)
            else:
                scores.append(0.0)
    year = result.get('B')
    if 'year' in expected:
        expected_year = expected['year'].get('exact')
        if year == expected_year:
            scores.append(1.0)
        else:
            scores.append(0.0)
    authors = result.get('C')
    if 'authors' in expected:
        if expected['authors'].get('not_empty'):
            if authors and isinstance(authors, str) and authors.strip():
                scores.append(1.0)
            else:
                scores.append(0.0)
    pdf_link = result.get('D')
    if 'pdf_link' in expected:
        if expected['pdf_link'].get('not_empty'):
            if pdf_link and isinstance(pdf_link, str) and pdf_link.strip():
                if expected['pdf_link'].get('contains'):
                    contains_str = expected['pdf_link']['contains']
                    if contains_str in pdf_link:
                        scores.append(1.0)
                    else:
                        scores.append(0.0)
                else:
                    scores.append(1.0)
            else:
                scores.append(0.0)
    if not scores:
        return 0.0
    return sum(scores) / len(scores)

def check_word_document_saved__d7ade9f0(result, expected, **options):
    """
    Check if a Word document was properly saved from email attachment.

    Verifies:
    1. File exists at /home/user/lecture-notes.docx
    2. File is a valid Word document (MIME type check)
    3. File was created during task execution (timestamp check)

    Args:
        result: Output from bash command containing:
                - Line 1: "exists" or "missing"
                - Line 2 (if exists): MIME type
                - Line 3 (if exists): Unix timestamp
        expected: Dict with 'task_start_time' key (Unix timestamp)
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None:
        return 0.0
    lines = result.strip().split('\n')
    if len(lines) == 0 or 'missing' in lines[0]:
        return 0.0
    if 'exists' not in lines[0]:
        return 0.0
    if len(lines) < 3:
        return 0.0
    mime_type = lines[1].strip()
    valid_mime_types = ['application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword', 'application/octet-stream']
    is_word_document = any((valid_type in mime_type for valid_type in valid_mime_types))
    if not is_word_document:
        return 0.0
    try:
        file_timestamp = int(lines[2].strip())
        task_start_time = int(expected.get('task_start_time', 0))
        if task_start_time > 0 and file_timestamp < task_start_time:
            return 0.0
    except (ValueError, IndexError):
        pass
    return 1.0

