def check_autosave_interval__3f228784(config_file, rules):
    """Check if auto-save interval is set to expected value (5 minutes).

    Args:
        config_file: Path to registrymodifications.xcu file
        rules: Dict with "minutes" key - expected interval

    Returns:
        1.0 if interval matches, 0.0 otherwise
    """
    expected_minutes = rules['minutes']
    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
        autosave_time = None
        for item in root.findall('.//item'):
            path = item.get('{http://openoffice.org/2001/registry}path')
            if path == '/org.openoffice.Office.Common/Save/Document':
                for prop in item.findall('.//prop'):
                    name = prop.get('{http://openoffice.org/2001/registry}name')
                    if name == 'AutoSaveTimeIntervall':
                        value_elem = prop.find('.//value')
                        if value_elem is not None:
                            autosave_time = int(value_elem.text)
                        break
        if autosave_time is None:
            return 0.0
        return 1.0 if autosave_time == expected_minutes else 0.0
    except (ET.ParseError, FileNotFoundError, ValueError) as e:
        logger.error(f'Error checking autosave interval: {e}')
        return 0.0

def check_tax_column__cca622ef(result, expected, **options):
    """Check if Tax column (G) contains correct header and 10% of Sales values.

    Args:
        result: dict from getter with 'header' and 'values' keys
        expected: dict with 'expected_taxes' - list of (row_num, expected_tax)
        **options: 'tolerance' for floating point comparison

    Returns:
        float: Score from 0.0 to 1.0 based on header check and percentage of correct values
    """
    if not result or not isinstance(result, dict):
        return 0.0
    header = result.get('header', '')
    if header is None or str(header).strip().lower() != 'tax':
        return 0.0
    values = result.get('values', [])
    if not values:
        return 0.0
    expected_taxes = expected.get('expected_taxes', [])
    if not expected_taxes:
        return 0.0
    tolerance = options.get('tolerance', 0.1)
    result_dict = {row: val for (row, val) in values}
    correct = 0
    total = len(expected_taxes)
    for (row, expected_val) in expected_taxes:
        if row in result_dict:
            result_val = result_dict[row]
            try:
                if abs(float(result_val) - float(expected_val)) <= tolerance:
                    correct += 1
            except (ValueError, TypeError):
                pass
    return correct / total if total > 0 else 0.0

