def check_check_multiple_students_grading__f3b5e1a6(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if multiple students grading is correct.

    Args:
        result: Dictionary from getter with students data
        expected: Expected values with student_ids and their scores
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if 'error' in result:
        return 0.0
    students = result.get('students', {})
    expected_students = expected.get('student_ids', [])
    expected_all_q_scores = expected.get('all_q_scores', {})
    expected_total_grades = expected.get('total_grades', {})
    if not expected_students:
        return 0.0
    total_score = 0.0
    for student_id in expected_students:
        if student_id not in students:
            continue
        student_data = students[student_id]
        actual_q_scores = student_data['q_scores']
        actual_total = student_data['total_grade']
        if any((score is None for score in actual_q_scores)) or actual_total is None:
            continue
        student_key = str(student_id)
        expected_q = expected_all_q_scores.get(student_key, [])
        expected_t = expected_total_grades.get(student_key)
        student_score = 0.0
        correct_q = sum((1 for i in range(10) if i < len(expected_q) and actual_q_scores[i] == expected_q[i]))
        student_score += correct_q / 10 * 0.7
        if actual_total == expected_t:
            student_score += 0.3
        total_score += student_score
    return total_score / len(expected_students) if expected_students else 0.0

def check_title_format__c9be3f87(result, expected, **options):
    """Check if title formatting matches expected properties.

    Args:
        result: Dictionary with formatting properties from getter
        expected: Dictionary with expected formatting properties
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        logger.error('No result data')
        return 0.0
    score = 0.0
    checks = 0
    if 'bold' in expected:
        checks += 1
        if result.get('bold') == expected['bold']:
            score += 1
            logger.info(f"✓ Bold check passed: {result.get('bold')}")
        else:
            logger.warning(f"✗ Bold check failed: expected {expected['bold']}, got {result.get('bold')}")
    if 'italic' in expected:
        checks += 1
        if result.get('italic') == expected['italic']:
            score += 1
            logger.info(f"✓ Italic check passed: {result.get('italic')}")
        else:
            logger.warning(f"✗ Italic check failed: expected {expected['italic']}, got {result.get('italic')}")
    if 'font_size' in expected:
        checks += 1
        result_size = result.get('font_size')
        expected_size = expected['font_size']
        if result_size and abs(result_size - expected_size) < 1:
            score += 1
            logger.info(f'✓ Font size check passed: {result_size}')
        else:
            logger.warning(f'✗ Font size check failed: expected {expected_size}, got {result_size}')
    if 'alignment' in expected:
        checks += 1
        result_align = str(result.get('alignment', ''))
        expected_align = str(expected['alignment'])
        if expected_align in result_align or result_align in expected_align:
            score += 1
            logger.info(f'✓ Alignment check passed: {result_align}')
        else:
            logger.warning(f'✗ Alignment check failed: expected {expected_align}, got {result_align}')
    if checks == 0:
        return 0.0
    final_score = score / checks
    logger.info(f'Final score: {final_score:.2f} ({score}/{checks} checks passed)')
    return final_score

