def check_sorted_ascending__1af6b6b5(result, expected, **options):
    """Check if list is sorted in ascending order.

    Args:
        result: List of values from getter
        expected: Expected sorted list (from rules)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    is_sorted = result == sorted(result, key=lambda x: str(x).lower() if x else '')
    if is_sorted:
        return 1.0
    else:
        correct_positions = sum((1 for (i, val) in enumerate(result) if i < len(expected) and val == expected[i]))
        return correct_positions / len(expected) if expected else 0.0

def check_train_filter__00e7b7ce3e47c77cc7e4d9d9f86fae66(result: List[str], expected: Dict[str, Any], **options) -> float:
    """
    Check if the docx file contains only records for the specified train ID.

    Args:
        result: List of train record lines from getter
        expected: Dict with 'train_id' and 'expected_count' keys
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list):
        logger.error(f'Result is not a list: {type(result)}')
        return 0.0
    target_train_id = expected.get('train_id')
    expected_count = expected.get('expected_count')
    if not target_train_id or expected_count is None:
        logger.error('Missing train_id or expected_count in expected config')
        return 0.0
    valid_count = 0
    for line in result:
        parts = line.split(',')
        if len(parts) == 4:
            train_id = parts[1].strip()
            if train_id == target_train_id:
                valid_count += 1
            else:
                logger.info(f'Found record for wrong train: {train_id} (expected {target_train_id})')
                return 0.0
    if valid_count == expected_count:
        return 1.0
    else:
        logger.info(f'Record count mismatch: got {valid_count}, expected {expected_count}')
        return 0.0

def check_spacing__c4b1b037807b556aad1fdf7aafdbb79a(result, expected, **options):
    """Check if line spacing and font size match expected values.

    Args:
        result: Dictionary with 'spacing' and 'font_size' sub-dictionaries
        expected: Dictionary with expected spacing and font size for each paragraph (from rules)
        **options: Additional comparison options

    Returns:
        float: 1.0 if all spacing and font size match, 0.5 if only spacing matches,
               0.0 if spacing doesn't match
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    result_spacing = result.get('spacing', {})
    result_font_size = result.get('font_size', {})
    expected_spacings = expected.get('paragraph_spacings', {})
    expected_font_size = expected.get('font_size', 12.0)
    spacing_correct = True
    for (para_idx, expected_spacing) in expected_spacings.items():
        para_idx_int = int(para_idx)
        actual_spacing = result_spacing.get(para_idx_int)
        if actual_spacing is None:
            spacing_correct = False
            break
        if abs(actual_spacing - expected_spacing) > 0.01:
            spacing_correct = False
            break
    if not spacing_correct:
        return 0.0
    font_size_correct = True
    for para_idx in expected_spacings.keys():
        para_idx_int = int(para_idx)
        actual_font_size = result_font_size.get(para_idx_int)
        if actual_font_size is None:
            font_size_correct = False
            break
        if abs(actual_font_size - expected_font_size) > 0.1:
            font_size_correct = False
            break
    if spacing_correct and font_size_correct:
        return 1.0
    elif spacing_correct:
        return 0.5
    else:
        return 0.0

def check_bibtex_titles__22ec293d30359609bd92049c80c6d096(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the BibTeX file contains expected paper titles with proper formatting.

    Args:
        result: Dict with 'titles', 'entries', 'has_arxiv', 'has_dblp'
        expected: Expected rules dict with 'required_keywords' key
        **options: Additional options

    Returns:
        Score based on keyword matches, entry completeness, and DBLP preference
    """
    required_keywords = expected.get('required_keywords', [])
    if not required_keywords:
        return 0.0
    titles = result.get('titles', [])
    entries = result.get('entries', [])
    has_arxiv = result.get('has_arxiv', False)
    has_dblp = result.get('has_dblp', False)
    found_keywords = []
    keyword_entries = []
    for keyword in required_keywords:
        keyword_lower = keyword.lower()
        for (i, title) in enumerate(titles):
            if keyword_lower in title:
                found_keywords.append(keyword)
                if i < len(entries):
                    keyword_entries.append(entries[i])
                break
    if not required_keywords:
        base_score = 0.0
    else:
        base_score = len(found_keywords) / len(required_keywords)
    if base_score == 0.0:
        return 0.0
    complete_entries = 0
    for entry in keyword_entries:
        if entry.get('has_author') and entry.get('has_year') and entry.get('has_venue'):
            complete_entries += 1
    if keyword_entries:
        completeness_factor = complete_entries / len(keyword_entries)
    else:
        completeness_factor = 0.0
    source_factor = 1.0
    if has_arxiv and (not has_dblp):
        source_factor = 0.7
    elif has_dblp:
        source_factor = 1.0
    else:
        source_factor = 0.9
    final_score = base_score * 0.7 + completeness_factor * 0.2 + source_factor * 0.1
    return max(0.0, min(1.0, final_score))

