def check_backup_exists__c9bfc81c(result, expected, **options):
    """Check if backup file exists and is a valid copy of the original.

    Args:
        result: Dict with file info (original_exists, backup_exists, original_size, backup_size)
        expected: Expected state (dict with 'is_valid_backup' key)
        **options: Additional options

    Returns:
        float: 1.0 if backup is valid copy, 0.0 otherwise
    """
    if not result.get('original_exists', False):
        return 0.0
    if not result.get('backup_exists', False):
        return 0.0
    original_size = result.get('original_size', 0)
    backup_size = result.get('backup_size', 0)
    if original_size == 0 or backup_size == 0:
        return 0.0
    if original_size == backup_size:
        return 1.0
    else:
        return 0.0

def check_symlink__11701199(result, expected, **options):
    """Check if symbolic link points to expected target.

    Args:
        result: Target path from readlink command (string)
        expected: Expected state rules with 'expected_target'
        **options: Additional comparison options

    Returns:
        float: 1.0 if symlink target matches, 0.0 otherwise
    """
    expected_target = expected.get('expected_target', '')
    result_stripped = result.strip()
    if result_stripped == expected_target:
        return 1.0
    import os
    try:
        result_normalized = os.path.normpath(result_stripped)
        expected_normalized = os.path.normpath(expected_target)
        if result_normalized == expected_normalized:
            return 1.0
    except:
        pass
    return 0.0

def check_title_presence__2a21cca0(result: List[Dict[str, str]], expected: Any, **options) -> float:
    """
    Check if ACL paper entries have all required fields.

    Args:
        result: List of paper entry dicts from getter (each with title, year, authors, pdf_link)
        expected: Dict with:
            - min_entries: Minimum number of entries required (default: 2)
            - min_title_length: Minimum length for title to avoid truncation (default: 30)

    Returns:
        Score between 0.0 and 1.0
    """
    min_entries = expected.get('min_entries', 2)
    min_title_length = expected.get('min_title_length', 30)
    if len(result) < min_entries:
        return 0.0
    valid_count = 0
    for entry in result:
        has_title = entry.get('title', '').strip() != ''
        has_year = entry.get('year', '').strip() != ''
        has_authors = entry.get('authors', '').strip() != ''
        has_pdf_link = entry.get('pdf_link', '').strip() != ''
        if not (has_title and has_year and has_authors and has_pdf_link):
            continue
        title = entry.get('title', '')
        if len(title) < min_title_length:
            continue
        year = entry.get('year', '')
        if not (year.isdigit() and len(year) == 4):
            continue
        pdf_link = entry.get('pdf_link', '')
        if 'aclanthology.org' not in pdf_link.lower():
            continue
        valid_count += 1
    if valid_count >= min_entries:
        return 1.0
    else:
        return valid_count / min_entries

def check_path_contains__225a261e(result_state: List[str], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if any path in the result list contains the expected substring.

    This metric checks if at least one path from the list of extension paths
    contains the substring specified in the expected_state.

    Args:
        result_state: List of extension paths from getter
        expected_state: Dict containing 'substring' to search for (when expected.type='rule', this IS the rules dict)
        **options: Additional options (not used)

    Returns:
        float: 1.0 if any path contains the substring, 0.0 otherwise
    """
    if result_state is None or not result_state:
        logger.warning('Result state is None or empty')
        return 0.0
    if not isinstance(result_state, list):
        logger.warning(f'Result state is not a list, got: {type(result_state)}')
        return 0.0
    if not isinstance(expected_state, dict):
        logger.error(f'Expected state is not a dict, got: {type(expected_state)}')
        return 0.0
    substring = expected_state.get('substring', '')
    if not substring:
        logger.error('No substring specified in expected_state')
        return 0.0
    logger.info(f"Checking if any path contains substring: '{substring}'")
    logger.debug(f'Paths to check: {result_state}')
    for path in result_state:
        if substring.lower() in path.lower():
            logger.info(f"Found matching path: '{path}'")
            return 1.0
    logger.info(f"No path contains substring '{substring}'")
    return 0.0

def check_product_match__464164fa4814917f279d06fca9f345e9(result, expected, **options):
    """Check if the product name matches expected value.

    Args:
        result: The actual product name from the cell
        expected: Expected product name
        **options: Additional options (case_sensitive)

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    if result is None:
        return 0.0
    case_sensitive = options.get('case_sensitive', False)
    result_str = str(result).strip()
    expected_str = str(expected).strip()
    if case_sensitive:
        if result_str == expected_str:
            return 1.0
    elif result_str.lower() == expected_str.lower():
        return 1.0
    return 0.0

def check_sorted_descending__880be75d(result, expected, **options):
    """Check if values are sorted in descending order.

    Args:
        result: List of numeric values
        expected: Not used (we only check sorting, not specific values)
        **options: Additional options

    Returns:
        float: 1.0 if sorted descending, 0.0 otherwise
    """
    if not result or len(result) < 2:
        return 0.0
    for i in range(len(result) - 1):
        if result[i] < result[i + 1]:
            return 0.0
    return 1.0

def check_bibtex_entry_count__158776f670e179a0f46e13d333164963(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if BibTeX entries match the referenced papers in quality and quantity.

    Args:
        result: Dict with 'count', 'entries', and 'referenced_papers' from getter
        expected: Expected rules dict with 'min_count' key
        **options: Additional options

    Returns:
        1.0 if all checks pass, partial score otherwise
    """
    min_count = expected.get('min_count', 6)
    count = result.get('count', 0)
    entries = result.get('entries', [])
    referenced_papers = result.get('referenced_papers', [])
    if count < min_count:
        return 0.0
    valid_entries = 0
    for entry in entries:
        if entry.get('title') and entry.get('type'):
            valid_entries += 1
    if valid_entries < min_count:
        return 0.3
    matched_papers = set()
    for entry in entries:
        entry_title = entry.get('title', '').lower()
        entry_authors = entry.get('authors', '').lower()
        for paper in referenced_papers:
            paper_lower = paper.lower()
            keywords = paper_lower.split()
            match_found = False
            if paper_lower in entry_title or paper_lower in entry_authors:
                match_found = True
            elif len(keywords) >= 3:
                keyword_matches = sum((1 for kw in keywords if kw in entry_title))
                if keyword_matches >= len(keywords) - 1:
                    match_found = True
            elif len(paper_lower) <= 6:
                import re
                if re.search('\\b' + re.escape(paper_lower) + '\\b', entry_title):
                    match_found = True
            if match_found:
                matched_papers.add(paper)
                break
    expected_paper_count = len(referenced_papers)
    matched_count = len(matched_papers)
    if expected_paper_count == 0:
        if valid_entries >= min_count:
            return 0.8
        return 0.5
    match_ratio = matched_count / expected_paper_count
    if match_ratio >= 1.0:
        return 1.0
    elif match_ratio >= 0.8:
        return 0.9
    elif match_ratio >= 0.6:
        return 0.7
    elif match_ratio >= 0.4:
        return 0.5
    else:
        return 0.3

def check_docstring_exists__c84ddf7a(result: str, expected: Dict, **options) -> float:
    """Check if a docstring exists and contains expected keywords.

    Args:
        result: The docstring content
        expected: Dict with optional 'min_length' and 'keywords'

    Returns:
        1.0 if docstring meets criteria, 0.0 otherwise
    """
    if not result:
        return 0.0
    min_length = expected.get('min_length', 10)
    keywords = expected.get('keywords', [])
    if len(result) < min_length:
        return 0.0
    if keywords:
        result_lower = result.lower()
        for keyword in keywords:
            if keyword.lower() not in result_lower:
                return 0.0
    return 1.0

def check_tiff_format__6575e228(result_state: Optional[Dict[str, str]], expected_state: Dict[str, Any], **options) -> float:
    """Check if image format matches the expected TIFF format.

    This metric verifies that an image has been converted to TIFF format
    by checking if the format string matches 'TIFF' or 'TIF' (both are valid
    PIL representations of TIFF format).

    Args:
        result_state: Dictionary with 'format' key from getter
        expected_state: Expected format dict with 'format' key
                       (When type='rule', framework passes config['rules'] directly)
        **options: Additional options (not used currently)

    Returns:
        float: Score (1.0 if format is TIFF, 0.0 otherwise)
    """
    try:
        if result_state is None:
            logger.error("Result state is None - image file likely doesn't exist")
            return 0.0
        if not isinstance(result_state, dict):
            logger.error(f'Result state is not a dict: {type(result_state)}')
            return 0.0
        actual_format = result_state.get('format')
        if actual_format is None:
            logger.error(f'Missing format in result_state: {result_state}')
            return 0.0
        expected_format = expected_state.get('format')
        if expected_format is None:
            logger.error(f'Missing expected format in expected_state: {expected_state}')
            return 0.0
        actual_format_upper = actual_format.upper()
        expected_format_upper = expected_format.upper()
        if expected_format_upper in ['TIFF', 'TIF']:
            format_match = actual_format_upper in ['TIFF', 'TIF']
        else:
            format_match = actual_format_upper == expected_format_upper
        logger.info(f'Actual format: {actual_format}, Expected format: {expected_format}')
        if format_match:
            logger.info('Image format matches expected format')
            return 1.0
        else:
            logger.warning(f'Image format does not match: actual={actual_format}, expected={expected_format}')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking image format: {e}')
        import traceback
        logger.error(traceback.format_exc())
        return 0.0
